// ==UserScript==
// @name         Torn Trading - Buyer-side Opportunity Scanner
// @namespace    torn-trading
// @version      3.8.0
// @description  Finds Bazaar and Item Market listings below NPC / market value - on the page you are viewing, and live from the Torn API and TornW3B - ranked by the profit you can actually realize.
// @author       -
// @match        https://www.torn.com/*
// @run-at       document-idle
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_deleteValue
// @grant        GM_registerMenuCommand
// @grant        GM_openInTab
// @grant        GM_xmlhttpRequest
// @grant        GM_addValueChangeListener
// @connect      api.torn.com
// @connect      www.tornexchange.com
// @connect      weav3r.dev
// @downloadURL  https://raw.githubusercontent.com/abrahamdelosreyes17-oss/torn-moneymaker-releases/main/torn-moneymaker.user.js
// @updateURL    https://raw.githubusercontent.com/abrahamdelosreyes17-oss/torn-moneymaker-releases/main/torn-moneymaker.user.js
// @noframes
// ==/UserScript==

/*
 * Built from src/ by build.mjs - do not edit this file directly.
 *
 * Rules this script keeps, deliberately (see README.md):
 *   - Data comes from the Torn API or from the page you are currently
 *     viewing. It never requests a Torn page you are not on.
 *   - It never buys anything. The only action button navigates.
 *   - Public API key only; the key goes to api.torn.com and nowhere else,
 *     and is never logged.
 *   - The optional TornW3B bazaar feed (weav3r.dev) is opt-in, has its own
 *     client, and never receives the key.
 *   - The live feed runs in one visible tab only, and never raises alerts.
 */

(function () {
    'use strict';

    const TTV2_BUILD_VERSION = '3.8.0';

    /* ===== src/platform/gm.js ===== */
    /*
     * Userscript-host adapter.
     *
     * Every GM_* call in the project goes through this file. core/ and api/ never
     * touch it directly, so those layers stay portable to a plain web app: swap
     * this one module for a localStorage (or server) adapter and nothing else
     * changes.
     *
     * Falls back to an in-memory store when the GM_* globals are absent, which is
     * what lets the unit tests run under plain node.
     */

    const GM_NAMESPACE = 'tornTrading.v2.';

    const gmMemoryStore = new Map();

    const gmHasStorage =
        typeof GM_getValue === 'function' && typeof GM_setValue === 'function';

    function gmKey(key) {
        return GM_NAMESPACE + key;
    }

    /** Read a JSON-serialisable value. Returns `fallback` if absent or corrupt. */
    function gmGet(key, fallback = null) {
        const full = gmKey(key);

        let raw;
        if (gmHasStorage) {
            raw = GM_getValue(full, null);
        } else {
            raw = gmMemoryStore.has(full) ? gmMemoryStore.get(full) : null;
        }

        if (raw === null || raw === undefined || raw === '') return fallback;

        try {
            return JSON.parse(raw);
        } catch {
            // A corrupt entry is not worth crashing over; treat it as absent.
            return fallback;
        }
    }

    /** Write a JSON-serialisable value. */
    function gmSet(key, value) {
        const full = gmKey(key);
        const raw = JSON.stringify(value);

        if (gmHasStorage) {
            GM_setValue(full, raw);
        } else {
            gmMemoryStore.set(full, raw);
        }
    }

    /** Remove a stored value. */
    function gmDel(key) {
        const full = gmKey(key);

        if (gmHasStorage && typeof GM_deleteValue === 'function') {
            GM_deleteValue(full);
        } else if (gmHasStorage) {
            GM_setValue(full, '');
        } else {
            gmMemoryStore.delete(full);
        }
    }

    /** Register a Tampermonkey menu command, if the host supports them. */
    function gmMenu(label, handler) {
        if (typeof GM_registerMenuCommand === 'function') {
            GM_registerMenuCommand(label, handler);
        }
    }

    /**
     * HTTP GET through the userscript host's own transport.
     *
     * This matters more than it looks. A plain fetch() from a userscript runs in
     * the PAGE's context and is therefore subject to Torn's Content-Security-
     * Policy: if their CSP does not allow connect-src to api.torn.com, every API
     * call is blocked by the browser before it is sent. The panel still loads and
     * the buttons still respond - there is simply never any data, which presents
     * as "it does not scan".
     *
     * GM_xmlhttpRequest runs outside the page, so the page's CSP does not apply.
     * It requires `@connect api.torn.com` in the header.
     *
     * Falls back to fetch when the host does not provide it (and under node, for
     * the tests).
     *
     * @returns {Promise<{ok: boolean, status: number, json: function}>}
     */
    function gmFetch(url) {
        if (typeof GM_xmlhttpRequest !== 'function') {
            if (typeof fetch === 'function') return fetch(url);
            return Promise.reject(new Error('No HTTP transport available.'));
        }

        return new Promise((resolve, reject) => {
            GM_xmlhttpRequest({
                method: 'GET',
                url,
                timeout: 30000,
                onload(response) {
                    resolve({
                        ok: response.status >= 200 && response.status < 300,
                        status: response.status,
                        json: async () => JSON.parse(response.responseText),
                    });
                },
                onerror() {
                    reject(new Error('Network request failed.'));
                },
                ontimeout() {
                    reject(new Error('Torn API request timed out.'));
                },
            });
        });
    }

    /** Open a URL in a new tab, if the host supports it; otherwise fall back. */
    function gmOpenTab(url) {
        if (typeof GM_openInTab === 'function') {
            GM_openInTab(url, { active: true });
        } else if (typeof window !== 'undefined') {
            window.open(url, '_blank', 'noopener');
        }
    }

    /**
     * Be told when ANOTHER tab changes a stored value. This is how follower tabs
     * see the live feed the leader tab writes, without polling anything.
     * Returns false when the host has no listener API (the caller then re-reads
     * on its own timer).
     */
    function gmOnChange(key, handler) {
        if (typeof GM_addValueChangeListener !== 'function') return false;

        GM_addValueChangeListener(gmKey(key), (_name, _old, _new, remote) => {
            if (remote) handler();
        });

        return true;
    }

    /* ===== src/core/items.js ===== */
    /*
     * The item database: indexing and cache policy. Pure - no GM_*, no DOM, no
     * network. main.js supplies the storage adapter and the fetcher.
     *
     * The index is built ONCE at load. V1's fatal performance bug was rebuilding
     * and re-sorting a ~1,500-entry name array inside a per-element loop; here
     * name lookup is a Map hit.
     */

    /** Bump to invalidate every cached item database in the wild. */
    const ITEMS_CACHE_VERSION = 'items-v5';

    /**
     * One hour. sell_price barely moves, but market_value moves every day, and
     * every "below market value" judgement is only as good as it. A week-old
     * market value made listings look cheap, or not, against a price that no
     * longer existed. One Public API call an hour is nothing.
     */
    const ITEMS_TTL_MS = 60 * 60 * 1000;

    /**
     * Canonical form for name matching: lowercase, collapsed whitespace.
     * Kept in one place so the index and the lookups can never disagree.
     */
    function normalizeItemName(name) {
        if (typeof name !== 'string') return '';
        return name.trim().toLowerCase().replace(/\s+/g, ' ');
    }

    /**
     * Build the lookup index from the raw `torn/items` payload.
     *
     * @param {object} rawItems - { "1": { name, sell_price, ... }, ... }
     */
    function buildItemIndex(rawItems) {
        const byId = new Map();
        const byName = new Map();

        for (const [id, item] of Object.entries(rawItems || {})) {
            if (!item || typeof item.name !== 'string') continue;

            const record = {
                id: String(id),
                name: item.name,
                type: item.type || null,
                buyPrice: Number(item.buy_price) || 0,
                // 0 when no NPC shop buys it ("Sell: N/A" in game).
                sellPrice: Number(item.sell_price) || 0,
                // Which NPC shop buys it, when the item data names one.
                npcShopName: item.npc_shop || null,
                marketValue: Number(item.market_value) || 0,
                circulation: Number(item.circulation) || 0,
            };

            byId.set(record.id, record);

            const key = normalizeItemName(record.name);
            // Torn item names are unique; if that ever changes, first wins and the
            // duplicate is simply not reachable by name.
            if (key && !byName.has(key)) byName.set(key, record);
        }

        return { byId, byName, size: byId.size };
    }

    /** Wrap a raw payload with the metadata the cache policy needs. */
    function makeItemsCacheEntry(rawItems, now = Date.now()) {
        return {
            version: ITEMS_CACHE_VERSION,
            fetchedAt: now,
            items: rawItems,
        };
    }

    /** True when a stored entry is the right shape, right version, and not stale. */
    function isItemsCacheFresh(entry, now = Date.now(), ttl = ITEMS_TTL_MS) {
        if (!entry || typeof entry !== 'object') return false;
        if (entry.version !== ITEMS_CACHE_VERSION) return false;
        if (!entry.items || typeof entry.items !== 'object') return false;
        if (!Number.isFinite(entry.fetchedAt)) return false;

        return now - entry.fetchedAt < ttl;
    }

    /**
     * Look an item up by display name. Returns null on a miss - never a guess.
     *
     * @param {object} index - from buildItemIndex
     */
    function findItemByName(index, name) {
        if (!index || !index.byName) return null;

        const key = normalizeItemName(name);
        if (!key) return null;

        return index.byName.get(key) || null;
    }

    /** Look an item up by id. */
    function findItemById(index, id) {
        if (!index || !index.byId) return null;
        return index.byId.get(String(id)) || null;
    }

    /* ===== src/core/npc.js ===== */
    /*
     * Which NPC shop will actually buy an item, and what it pays. Pure - no
     * network, no DOM.
     *
     * This is the correctness fix that matters most. V1 treated `sell_price > 0`
     * as "an NPC will pay me this". Essentially every item in Torn carries a
     * sell_price, so V1 confidently reported profit on items no shop will buy.
     *
     * SETTLED, by testing in game: an item does NOT need to be stocked by a city
     * shop for an NPC to buy it. Bottle of Champagne sells to an NPC for $3,100
     * and no shop stocks it. So `sell_price` alone IS the NPC price.
     *
     * The shop index is therefore informational only - it names the shop when it
     * knows one. It must never gate whether an opportunity is shown. An earlier
     * version treated a missing shop as "unverified" and hid those rows, which
     * silently deleted a real $4.7m opportunity from a live page.
     *
     * Note the two prices are different things: `sell_price` is what a shop pays
     * YOU; a shop inventory's `price` is what it CHARGES you.
     *
     * The shop identity is carried through so the panel can name it, which is
     * what makes a claim like "+$104/ea" checkable by the user instead of
     * something they have to take on faith.
     */

    const NPC_ALLOWLIST_VERSION = 'npc-v3';

    /** Shop inventories move rarely; a week is plenty. */
    const NPC_ALLOWLIST_TTL_MS = 7 * 24 * 60 * 60 * 1000;

    function npcShopEntry(shopId, shop, itemId, entry) {
        return {
            itemId: String(itemId),
            shopId: String(shopId),
            shopName: (shop && shop.name) || 'Unknown shop',
            // What the shop charges for it. Kept for display only; it is not the
            // NPC buy-back price and must never be used as one.
            shopPrice: Number(entry && (entry.price ?? entry.cost)) || null,
        };
    }

    /**
     * Index every item stocked by any city shop, keeping which shop and what it
     * charges.
     *
     * Written defensively: the payload shape has changed before, and a shape we
     * do not recognise degrades to "nothing verified" rather than throwing.
     *
     * @param {object} rawShops - { "1": { name, inventory: {...} }, ... }
     * @returns {Map<string, object>} itemId -> shop entry
     */
    function buildNpcShopIndex(rawShops) {
        const index = new Map();

        for (const [shopId, shop] of Object.entries(rawShops || {})) {
            if (!shop || typeof shop !== 'object') continue;

            const inventory = shop.inventory;
            if (!inventory || typeof inventory !== 'object') continue;

            if (Array.isArray(inventory)) {
                for (const entry of inventory) {
                    if (!entry || typeof entry !== 'object') continue;

                    const itemId = entry.ID ?? entry.id ?? entry.item_id;
                    if (itemId === undefined || itemId === null) continue;

                    if (!index.has(String(itemId))) {
                        index.set(
                            String(itemId),
                            npcShopEntry(shopId, shop, itemId, entry),
                        );
                    }
                }
            } else {
                for (const [itemId, entry] of Object.entries(inventory)) {
                    if (entry === null || entry === undefined) continue;
                    if (index.has(String(itemId))) continue;

                    index.set(
                        String(itemId),
                        npcShopEntry(shopId, shop, itemId, entry),
                    );
                }
            }
        }

        return index;
    }

    /** Serialise the index for storage. */
    function makeNpcCacheEntry(index, now = Date.now()) {
        return {
            version: NPC_ALLOWLIST_VERSION,
            fetchedAt: now,
            shops: Array.from((index || new Map()).values()),
        };
    }

    /** Rebuild the index from a stored entry. */
    function readNpcCacheEntry(entry) {
        const index = new Map();

        for (const shop of (entry && entry.shops) || []) {
            if (shop && shop.itemId) index.set(String(shop.itemId), shop);
        }

        return index;
    }

    function isNpcCacheFresh(
        entry,
        now = Date.now(),
        ttl = NPC_ALLOWLIST_TTL_MS,
    ) {
        if (!entry || typeof entry !== 'object') return false;
        if (entry.version !== NPC_ALLOWLIST_VERSION) return false;
        if (!Array.isArray(entry.shops)) return false;
        if (!Number.isFinite(entry.fetchedAt)) return false;

        return now - entry.fetchedAt < ttl;
    }

    /**
     * Which shop buys this item, if any.
     *
     * @param {string|number} itemId
     * @param {Map<string, object>} shopIndex - from buildNpcShopIndex
     * @param {object} manualOverrides - { "<itemId>": {shopName} | true | false }
     * @returns {object|null} { shopName, shopId, shopPrice, manual } or null
     */
    function npcShopFor(itemId, shopIndex, manualOverrides = {}) {
        const id = String(itemId);

        // An explicit user decision wins: they have actually tried to sell the
        // thing, which beats any inference from shop data.
        if (Object.prototype.hasOwnProperty.call(manualOverrides, id)) {
            const override = manualOverrides[id];

            if (override === false) return null;

            if (override === true) {
                return {
                    itemId: id,
                    shopId: null,
                    shopName: 'Confirmed by you',
                    shopPrice: null,
                    manual: true,
                };
            }

            if (override && typeof override === 'object') {
                return { itemId: id, manual: true, ...override };
            }
        }

        const hit = shopIndex && shopIndex.get(id);
        return hit ? { ...hit, manual: false } : null;
    }

    /** Back-compat helper: is there a verified NPC buyer at all? */
    function isNpcSellable(itemId, shopIndex, manualOverrides = {}) {
        return npcShopFor(itemId, shopIndex, manualOverrides) !== null;
    }

    /**
     * The price an NPC pays, or null when there is no usable figure.
     *
     * Deliberately does NOT fall back to market_value, and deliberately does not
     * use the shop's own `price`: this answers "what will a shop hand me", and
     * both of those are different claims.
     */
    function npcExitPrice(item) {
        if (!item) return null;

        const price = Number(item.sellPrice);
        if (!Number.isFinite(price) || price <= 0) return null;

        return price;
    }

    /* ===== src/core/profit.js ===== */
    /*
     * The profit model. Pure functions, no DOM.
     *
     * One formula, venue is a parameter:
     *
     *     net_per_unit = exit_price * (1 - fee) - listing_price
     *
     * V1 hardcoded the NPC route (fee 0) and labelled ROI as "margin". Both are
     * fixed here, and the fee parameter is in place from the start so the Item
     * Market and Auction House routes do not mean touching every call site later.
     */

    /**
     * Sale fees by exit venue, as a fraction of the sale price.
     *
     * - NPC: shops pay the listed sell_price with no tax.
     * - ITEM_MARKET: 5% sales tax (introduced 22 June 2025).
     * - BAZAAR_RESALE: relisting in your own bazaar carries no tax.
     * - ITEM_MARKET_ANON: listing anonymously adds a further 10%, so 15% total.
     * - AUCTION_HOUSE: 3%.
     *
     * These are game-balance numbers and Torn has changed them before, so they
     * live in one place where a change is a one-line edit.
     */
    const VENUE_FEES = {
        NPC: 0,
        ITEM_MARKET: 0.05,
        // Relisting in your own bazaar: no sales tax. The price is still an
        // estimate - someone has to buy it at market value.
        BAZAAR_RESALE: 0,
        ITEM_MARKET_ANON: 0.15,
        AUCTION_HOUSE: 0.03,
        // A player trader (TornExchange price list): paid in the trade, no tax.
        // An offer, not a guarantee - see core/traders.js.
        TRADER: 0,
    };

    /*
     * "Market" is Torn's rolling average, not a price anyone has offered you -
     * the live floor can sit well above or below it. The label says so; the NPC
     * price is the only exit that is guaranteed.
     */
    const VENUE_LABELS = {
        NPC: 'NPC',
        ITEM_MARKET: 'Avg value',
        BAZAAR_RESALE: 'Avg value',
        ITEM_MARKET_ANON: 'Market (anon)',
        AUCTION_HOUSE: 'Auction',
        TRADER: 'Trader',
    };

    /**
     * How many units you can actually afford. This is what turns a theoretical
     * opportunity into a realizable one.
     */
    function capQuantityByCash(qty, listingPrice, cashOnHand) {
        if (!Number.isFinite(qty) || qty <= 0) return 0;
        if (!Number.isFinite(cashOnHand) || cashOnHand <= 0) return qty;
        if (!Number.isFinite(listingPrice) || listingPrice <= 0) return qty;

        return Math.max(0, Math.min(qty, Math.floor(cashOnHand / listingPrice)));
    }

    /**
     * Compute one opportunity.
     *
     * @param {object} input
     * @param {number} input.listingPrice - price per unit you would pay
     * @param {number} input.exitPrice    - price per unit you would receive
     * @param {number} [input.qty]        - units available at this listing
     * @param {string} [input.venue]      - key of VENUE_FEES
     * @param {number} [input.cashOnHand] - optional cash cap
     * @returns {object|null} null when the inputs cannot produce a real number.
     */
    function computeOpportunity({
        listingPrice,
        exitPrice,
        qty = 1,
        venue = 'NPC',
        cashOnHand = null,
    }) {
        if (!Number.isFinite(listingPrice) || listingPrice <= 0) return null;
        if (!Number.isFinite(exitPrice) || exitPrice <= 0) return null;

        const fee = VENUE_FEES[venue];
        if (!Number.isFinite(fee)) return null;

        const quantity = Number.isFinite(qty) && qty > 0 ? Math.floor(qty) : 1;

        const netExit = exitPrice * (1 - fee);
        const profitPerUnit = netExit - listingPrice;

        const affordableQty = capQuantityByCash(
            quantity,
            listingPrice,
            cashOnHand,
        );

        return {
            venue,
            fee,
            listingPrice,
            exitPrice,
            netExit,
            profitPerUnit,
            // ROI on cash deployed. V1 called this "margin"; it never was.
            roi: profitPerUnit / listingPrice,
            qty: quantity,
            affordableQty,
            totalProfit: profitPerUnit * quantity,
            realizableProfit: profitPerUnit * affordableQty,
            cashRequired: listingPrice * affordableQty,
        };
    }

    /**
     * Pick the best exit venue for a listing, given a price for each.
     *
     * @param {object} input
     * @param {number} input.listingPrice
     * @param {object} input.exits - { VENUE_KEY: exitPrice }
     */
    function bestVenue({ listingPrice, exits, qty = 1, cashOnHand = null }) {
        let best = null;

        for (const [venue, exitPrice] of Object.entries(exits || {})) {
            const candidate = computeOpportunity({
                listingPrice,
                exitPrice,
                qty,
                venue,
                cashOnHand,
            });

            if (!candidate) continue;

            if (!best || candidate.realizableProfit > best.realizableProfit) {
                best = candidate;
            }
        }

        return best;
    }

    /* ===== src/core/parse.js ===== */
    /*
     * Pure parsing + formatting helpers. No DOM, no network.
     */

    function applyMagnitude(value, suffix) {
        if (!Number.isFinite(value)) return null;

        switch ((suffix || '').toLowerCase()) {
            case 'k':
                return value * 1e3;
            case 'm':
                return value * 1e6;
            case 'b':
                return value * 1e9;
            default:
                return value;
        }
    }

    /**
     * Parse a money string into a number.
     *
     * Handles "$1,234", "1,234", "$1.2m", "806000". Returns null when the input
     * contains no number, rather than guessing.
     *
     * Note: unlike V1 this is never handed whole-row text. Callers pass the
     * contents of one specific cell, so there is no "first $ in the row" problem
     * to solve here.
     */
    function parseMoney(text) {
        if (typeof text !== 'string' && typeof text !== 'number') return null;

        const cleaned = String(text).replace(/[$,\s]/g, '');

        const exact = cleaned.match(/^(-?\d+(?:\.\d+)?)([kmb])?$/i);
        if (exact) return applyMagnitude(Number(exact[1]), exact[2]);

        /*
         * Embedded in a longer string. The number must END there: a following
         * letter or digit means we are looking at something else.
         *
         * This guard is load-bearing. Without it "$2,896 Buy" collapsed to
         * "2896Buy", the "B" was read as the billions suffix, and the price came
         * out as 2,896,000,000,000. Same for "$3,000 min" and "$500 market".
         */
        const loose = cleaned.match(/(-?\d+(?:\.\d+)?)([kmb])?(?![A-Za-z0-9])/);
        if (!loose) return null;

        return applyMagnitude(Number(loose[1]), loose[2]);
    }

    /**
     * Parse a quantity from strings like "x12", "12", "12 available", "Qty: 12".
     * Returns null when no quantity is present, so the caller decides whether to
     * assume 1 or to skip the row.
     */
    function parseQuantity(text) {
        if (text === null || text === undefined) return null;

        /*
         * Strip money figures before looking for a count.
         *
         * Without this, parseQuantity('$2,896') returned 2896 — so a price cell
         * whose class happened to contain "amount" became the quantity, and total
         * profit was inflated by three orders of magnitude.
         */
        const s = String(text)
            .toLowerCase()
            .replace(/,/g, '')
            .replace(/\$\s*\d+(?:\.\d+)?/g, ' ');

        // "x12" or "12x"
        const xForm = s.match(/(?:^|[^a-z0-9])x\s*(\d+)|(\d+)\s*x(?:[^a-z0-9]|$)/);
        if (xForm) {
            const n = Number(xForm[1] !== undefined ? xForm[1] : xForm[2]);
            if (Number.isFinite(n) && n > 0) return Math.floor(n);
        }

        const plain = s.match(/(\d+)/);
        if (plain) {
            const n = Number(plain[1]);
            if (Number.isFinite(n) && n > 0) return Math.floor(n);
        }

        return null;
    }

    /**
     * A money amount typed by a person: "1000000", "1,000,000", "$1m", "1.5m",
     * "500k", "2b", "1kk", "1 million". Returns null for anything else.
     *
     * The chips used to drop every non-digit, so "1m" became $1 - and a $1 cash
     * cap hides every deal without saying why.
     */
    function parseMoneyInput(text) {
        const raw = String(text == null ? '' : text).trim().toLowerCase().replace(/[$,\s_]/g, '');
        if (!raw) return null;

        const m = raw.match(/^(-?\d+(?:\.\d+)?)(k|kk|m|mil|mill|million|b|bil|bill|billion|thousand)?$/);
        if (!m) return null;

        const mult = {
            k: 1e3, thousand: 1e3,
            kk: 1e6, m: 1e6, mil: 1e6, mill: 1e6, million: 1e6,
            b: 1e9, bil: 1e9, bill: 1e9, billion: 1e9,
        }[m[2] || ''] || 1;

        const n = Number(m[1]) * mult;
        return Number.isFinite(n) ? Math.round(n) : null;
    }

    /** "$1,234" */
    function formatMoney(value) {
        if (!Number.isFinite(value)) return '-';

        const rounded = Math.round(value);
        const sign = rounded < 0 ? '-' : '';

        return sign + '$' + Math.abs(rounded).toLocaleString('en-US');
    }

    /** "$1.2m" - compact form for tight panel rows. */
    function formatMoneyShort(value) {
        if (!Number.isFinite(value)) return '-';

        const abs = Math.abs(value);
        const sign = value < 0 ? '-' : '';

        if (abs >= 1e9) return sign + '$' + (abs / 1e9).toFixed(2) + 'b';
        if (abs >= 1e6) return sign + '$' + (abs / 1e6).toFixed(2) + 'm';
        if (abs >= 1e4) return sign + '$' + (abs / 1e3).toFixed(1) + 'k';

        return formatMoney(value);
    }

    /** "4.2%" */
    function formatPct(ratio) {
        if (!Number.isFinite(ratio)) return '-';
        return (ratio * 100).toFixed(1) + '%';
    }

    /** "12s ago" / "4m ago" - for the staleness readout. */
    function formatAge(ms) {
        if (!Number.isFinite(ms) || ms < 0) return 'never';

        const seconds = Math.floor(ms / 1000);
        if (seconds < 60) return seconds + 's ago';

        const minutes = Math.floor(seconds / 60);
        if (minutes < 60) return minutes + 'm ago';

        const hours = Math.floor(minutes / 60);
        if (hours < 24) return hours + 'h ago';

        return Math.floor(hours / 24) + 'd ago';
    }

    /* ===== src/core/feed.js ===== */
    /*
     * The live feed: listings found anywhere in Torn, not just on this page.
     *
     * Pure - no DOM, no network, no storage. The controller fetches and stores;
     * this decides what is a candidate, what a snapshot means, and when a row
     * is too old to show.
     *
     * The rule that shapes everything here, learned the hard way: a listing is
     * only as live as the data behind it. So every row carries TWO times:
     *
     *   dataAt    - when the SOURCE last saw it (TornW3B's last_checked, the
     *               Item Market's cache_timestamp). Expiry and "age" use this.
     *   fetchedAt - when WE asked. Only a hard cap uses this.
     *
     * The old ledger stamped rows with the time the DOM was re-read, every 2.5s,
     * so a price from twenty minutes ago kept presenting as "just now" and the
     * panel linked trades that no longer existed. Nothing here refreshes a time
     * without new data behind it.
     *
     * And a new snapshot for an item REPLACES everything known about that item
     * from that source. Merging is how a sold listing survives.
     */




    const FEED_CACHE_VERSION = 'feed-v1';

    /*
     * Only what the latest refresh confirmed is shown. Nothing is greyed out:
     * a row that is not re-confirmed in time is removed.
     */

    /** The list is rebuilt from fresh data this often. */
    const REFRESH_MS = 30 * 1000;

    /** A bazaar row TornW3B has not checked within this long is not shown. */
    const BAZAAR_MAX_DATA_AGE_MS = 2 * 60 * 1000;

    /**
     * Re-ask TornW3B about an item this often. Its server caches each answer for
     * 60s, so asking every 30s would return the same body half the time.
     */
    const BAZAAR_REFRESH_MS = 60 * 1000;

    /** A bazaar snapshot not refreshed in time is dropped, rows and all. */
    const BAZAAR_SNAPSHOT_TTL_MS = BAZAAR_REFRESH_MS + REFRESH_MS;

    /**
     * Item Market: Torn refreshes it every 30s, and items with a live
     * opportunity are re-checked each time. One missed refresh is tolerated;
     * two is removal.
     */
    const ITEM_MARKET_SNAPSHOT_TTL_MS = 2 * REFRESH_MS + 15 * 1000;

    /**
     * Most candidates followed up per summary. 25 per minute plus two summaries
     * stays inside the 60/min this tool allows itself on TornW3B.
     */
    const MAX_CANDIDATES = 25;

    const SOURCE_BAZAAR = 'bazaar';
    const SOURCE_ITEM_MARKET = 'itemmarket';

    function emptyFeed() {
        return { bazaar: new Map(), itemmarket: new Map() };
    }

    /**
     * Where you could sell an item, under the current settings. Shared with the
     * page scanner so both price listings identically.
     *
     *   NPC            - "Sell to NPC": the item's Sell price, no tax. The main
     *                    job of this tool. Only when the item HAS a Sell price;
     *                    "Sell: N/A" in game (no sell_price) means no NPC buys it.
     *   BAZAAR_RESALE  - trading: relist in your own bazaar at the average value
     *                    (Torn's "Value"), no tax.
     *   ITEM_MARKET    - trading: sell on the Item Market at the average value,
     *                    minus the 5% tax.
     *
     * The average value is what an item tends to trade for, never an NPC price.
     *
     * @param {object} item - record from buildItemIndex
     * @param {object} settings - sellToNpc, resaleBazaar, resaleMarket
     */
    function exitsFor(item, settings = {}) {
        const exits = {};
        if (!item) return exits;

        if (settings.sellToNpc !== false) {
            const sell = Number(item.sellPrice);
            if (Number.isFinite(sell) && sell > 0) exits.NPC = sell;
        }

        const value = Number(item.marketValue);
        if (Number.isFinite(value) && value > 0) {
            if (settings.resaleBazaar) exits.BAZAAR_RESALE = value;
            if (settings.resaleMarket) exits.ITEM_MARKET = value;
        }

        return exits;
    }

    /**
     * The most a listing at `price` can earn with the user's cash: profit per
     * item x how many the cash buys (and no more than `qty`, when known).
     * Infinity when neither cash nor quantity limits it.
     *
     * This is what makes discovery cash-aware. Ranking by profit PER ITEM always
     * put the $200m items first; with $1m of cash every one of them was then
     * filtered out, and the cheap deals that fit were never fetched at all.
     */
    function reachableProfit(profitPerUnit, price, settings = {}, qty = Infinity) {
        let n = Number.isFinite(qty) && qty > 0 ? qty : Infinity;
        const cash = Number(settings.cashOnHand);
        if (cash > 0 && price > 0) n = Math.min(n, Math.floor(cash / price));
        if (n === 0) return 0;
        return profitPerUnit * n;
    }

    /**
     * Which items are worth a closer look, from TornW3B's one-call summary.
     *
     * Everything here is free - one summary for every item, plus the cached
     * item database - so the Cash and Min filters are applied BEFORE any request:
     * an item you cannot afford one of, or that cannot reach your Min with your
     * cash, is never fetched. What is left is ranked by the profit your cash can
     * actually make.
     *
     * One request covers every item; the friend's script made ~1,100 in a
     * 22-minute loop to answer the same question, and the answer was stale
     * before it finished.
     *
     * @param {Array} summary - from fetchW3bSummary
     * @param {object} index - from buildItemIndex
     * @param {object} settings
     * @returns {Array<{itemId: string, lowestPrice: number, profitPerUnit: number}>}
     */
    function selectCandidates(summary, index, settings = {}, max = MAX_CANDIDATES) {
        const out = [];

        for (const s of summary || []) {
            if (!s || !s.lowestPrice) continue;

            const item = index && index.byId && index.byId.get(String(s.itemId));
            if (!item) continue;

            const best = bestVenue({
                listingPrice: s.lowestPrice,
                exits: exitsFor(item, settings),
                qty: 1,
            });

            if (!best || best.profitPerUnit < 1) continue;

            const reach = reachableProfit(best.profitPerUnit, s.lowestPrice, settings);
            if (reach < 1) continue; // cannot afford even one
            if (reach < (Number(settings.minTotalProfit) || 0)) continue;

            out.push({
                itemId: String(s.itemId),
                lowestPrice: s.lowestPrice,
                profitPerUnit: best.profitPerUnit,
                reach,
            });
        }

        // With cash set, what your cash can make; without, profit per item.
        // Infinity - Infinity is NaN, which breaks a sort: compare finitely.
        out.sort((a, b) => finiteCmp(b.reach, a.reach) || b.profitPerUnit - a.profitPerUnit);
        return max > 0 ? out.slice(0, max) : out;
    }

    /** b - a for a sort, where either side may be Infinity (never NaN). */
    function finiteCmp(a, b) {
        if (a === b) return 0;
        if (!Number.isFinite(a) && !Number.isFinite(b)) return 0;
        return a > b ? 1 : -1;
    }

    /** Seconds, milliseconds, or nothing -> ms or null. Unknown is not "old". */
    function toMs(value) {
        const n = Number(value);
        if (!Number.isFinite(n) || n <= 0) return null;
        return n < 1e12 ? n * 1000 : n;
    }

    /**
     * TornW3B listings -> feed rows. Rows with no seller are dropped: there is
     * nowhere to send the user, and "bazaar.php?userId=null" is not a link.
     * Sorted by price ourselves - TornW3B puts sponsored rows first.
     */
    function normalizeW3bListings(raw) {
        const rows = [];

        for (const l of raw || []) {
            if (!l) continue;

            const sellerId = Number(l.player_id);
            const price = Number(l.price);
            const qty = Number(l.quantity);

            if (!Number.isFinite(sellerId) || sellerId <= 0) continue;
            if (!Number.isFinite(price) || price <= 0) continue;
            if (!Number.isFinite(qty) || qty <= 0) continue;
            /*
             * $1 is Torn's locked "Dollar Sale" price: buyable by a random few
             * percent of players, and the usual price of a target trade meant for
             * one person. TornW3B cannot say which, so none are offered from the
             * feed. (On the page itself, an unlocked $1 card IS yours to buy and
             * is read normally.)
             */
            if (price <= 1) continue;

            rows.push({
                sellerId: String(sellerId),
                sellerName: l.player_name ? String(l.player_name) : null,
                price,
                qty: Math.floor(qty),
                dataAt: toMs(l.last_checked) || toMs(l.content_updated),
                changedAt: toMs(l.content_updated),
            });
        }

        rows.sort((a, b) => a.price - b.price);
        return rows;
    }

    /** Item Market rows are anonymous; identical prices are merged. */
    function normalizeItemMarketRows(listings) {
        const byPrice = new Map();

        for (const l of listings || []) {
            const price = Number(l && l.price);
            const amount = Number(l && l.amount);
            if (!(price > 0) || !(amount > 0)) continue;
            byPrice.set(price, (byPrice.get(price) || 0) + amount);
        }

        return [...byPrice.entries()]
            .sort((a, b) => a[0] - b[0])
            .map(([price, qty]) => ({ price, qty }));
    }

    /** Replace everything known about an item's bazaar listings. */
    function setBazaarSnapshot(feed, itemId, rows, fetchedAt) {
        feed.bazaar.set(String(itemId), { fetchedAt, rows: rows || [] });
        return feed;
    }

    /** Replace everything known about an item's Item Market listings. */
    function setItemMarketSnapshot(
        feed,
        itemId,
        { rows, fetchedAt, dataAt = null, nextAt = null, averagePrice = null },
    ) {
        feed.itemmarket.set(String(itemId), {
            fetchedAt,
            dataAt: dataAt || fetchedAt,
            nextAt: nextAt || fetchedAt + 30000,
            averagePrice,
            rows: rows || [],
        });
        return feed;
    }

    /**
     * Drop whatever is too old to trust.
     * @returns {number} how many rows were removed
     */
    function expireFeed(feed, now = Date.now()) {
        let removed = 0;

        for (const [id, snap] of feed.bazaar) {
            if (!Number.isFinite(snap.fetchedAt) || now - snap.fetchedAt > BAZAAR_SNAPSHOT_TTL_MS) {
                removed += snap.rows.length;
                feed.bazaar.delete(id);
                continue;
            }

            const before = snap.rows.length;
            snap.rows = snap.rows.filter(
                (r) => r.dataAt === null || now - r.dataAt <= BAZAAR_MAX_DATA_AGE_MS,
            );
            removed += before - snap.rows.length;
        }

        for (const [id, snap] of feed.itemmarket) {
            if (!Number.isFinite(snap.fetchedAt) || now - snap.fetchedAt > ITEM_MARKET_SNAPSHOT_TTL_MS) {
                removed += snap.rows.length;
                feed.itemmarket.delete(id);
            }
        }

        return removed;
    }

    /**
     * Should this candidate's bazaar listings be (re)fetched now?
     * Yes when never fetched, when the summary's cheapest price moved, or when
     * the snapshot is older than TornW3B's own cache.
     */
    function bazaarDue(feed, candidate, now = Date.now()) {
        const snap = feed.bazaar.get(String(candidate.itemId));
        if (!snap) return true;
        if (now - snap.fetchedAt >= BAZAAR_REFRESH_MS) return true;

        const cheapest = snap.rows.length ? snap.rows[0].price : null;
        return cheapest !== candidate.lowestPrice;
    }

    /**
     * Items whose Item Market snapshot holds a live opportunity - these are
     * re-checked before they expire. A snapshot keeps EVERY listing Torn
     * returned (the page-vs-feed correction needs them), so "has rows" is not
     * "is a deal": judging liveness by rows alone made every swept item a
     * re-check candidate, and after a dozen sweeps the whole Torn budget went
     * to re-checking items that were never deals. The sweep then stood still.
     *
     * @param {function} isDeal - (itemId, cheapestPrice) => boolean
     */
    function itemMarketLiveIds(feed, isDeal = () => true) {
        const ids = [];
        for (const [id, snap] of feed.itemmarket) {
            if (snap.rows.length && isDeal(id, snap.rows[0].price)) ids.push(id);
        }
        return ids;
    }

    /** Item Market: never before Torn's global cache can have changed. */
    function itemMarketDue(feed, itemId, now = Date.now()) {
        const snap = feed.itemmarket.get(String(itemId));
        return !snap || now >= snap.nextAt;
    }

    /** Forget one seller's listing of one item (e.g. the page proved it gone). */
    function removeBazaarRows(feed, itemId, predicate) {
        const snap = feed.bazaar.get(String(itemId));
        if (!snap) return 0;

        const before = snap.rows.length;
        snap.rows = snap.rows.filter((r) => !predicate(r));
        return before - snap.rows.length;
    }

    /**
     * The page you are viewing is the most authoritative source there is. When
     * it contradicts the feed, the feed loses.
     *
     * - On a seller's bazaar: if the page shows an item from that seller only at
     *   a HIGHER price than a feed row claims, that row is gone.
     * - On the Item Market: the page shows the current cheapest price per item;
     *   any feed row cheaper than that has sold.
     *
     * Absence from the page proves nothing - bazaars render lazily - so only a
     * visible contradiction removes a row.
     *
     * @param {object} feed
     * @param {object} page
     * @param {'bazaar'|'itemmarket'} page.pageType
     * @param {string|null} page.sellerId - bazaar owner, from the URL
     * @param {Array<{itemId, listingPrice}>} page.listings
     * @returns {number} rows removed
     */
    function reconcileWithPage(feed, { pageType, sellerId, listings }) {
        const pageMin = new Map();
        for (const l of listings || []) {
            const id = String(l.itemId);
            const p = Number(l.listingPrice);
            if (!(p > 0)) continue;
            if (!pageMin.has(id) || p < pageMin.get(id)) pageMin.set(id, p);
        }

        let removed = 0;

        if (pageType === SOURCE_BAZAAR && sellerId) {
            for (const [id, min] of pageMin) {
                removed += removeBazaarRows(
                    feed,
                    id,
                    (r) => r.sellerId === String(sellerId) && r.price < min,
                );
            }
        }

        if (pageType === SOURCE_ITEM_MARKET) {
            for (const [id, min] of pageMin) {
                const snap = feed.itemmarket.get(id);
                if (!snap) continue;
                const before = snap.rows.length;
                snap.rows = snap.rows.filter((r) => r.price >= min);
                removed += before - snap.rows.length;
            }
        }

        return removed;
    }

    /**
     * Has fresher data proved that a listing on the page you are viewing is gone?
     *
     * Torn's page does not update itself, and this script may not reload it -
     * so a listing can sell while it is still on screen. The feed re-checks it:
     *
     * - Item Market: if a snapshot taken AFTER the page showed the row has
     *   nothing at or below that price, it sold.
     * - Bazaar: if TornW3B checked that seller AFTER the page showed the row and
     *   has them at a higher price, it was bought or repriced. A seller missing
     *   from TornW3B's data proves nothing - it may simply not track them.
     *
     * @param {object} feed
     * @param {object} row - a page row: itemId, source, sellerId, seenAt, listingPrice
     */
    function pageRowContradicted(feed, row) {
        const id = String(row.itemId);
        const price = Number(row.listingPrice ?? (row.profit && row.profit.listingPrice));
        const seenAt = Number(row.seenAt) || 0;

        if (row.source === SOURCE_ITEM_MARKET) {
            const snap = feed.itemmarket.get(id);
            if (!snap || !(snap.dataAt > seenAt)) return false;
            return !snap.rows.some((r) => r.price <= price);
        }

        if (row.source === SOURCE_BAZAAR && row.sellerId) {
            const snap = feed.bazaar.get(id);
            if (!snap) return false;

            const mine = snap.rows.filter(
                (r) => r.sellerId === String(row.sellerId) && r.dataAt > seenAt,
            );
            return mine.length > 0 && !mine.some((r) => r.price <= price);
        }

        return false;
    }

    /** Deep link to one seller's bazaar, carrying what to highlight there. */
    function bazaarUrl(sellerId, itemId, price) {
        const params = new URLSearchParams({ userId: String(sellerId) });
        if (itemId) params.set('ttItem', String(itemId));
        if (price) params.set('ttPrice', String(price));
        return 'https://www.torn.com/bazaar.php?' + params.toString() + '#/';
    }

    /**
     * Feed rows -> priced opportunities the ranker and panel understand.
     *
     * @param {object} feed
     * @param {object} index - item index
     * @param {object} settings
     * @param {object} [ctx]
     * @param {function} [ctx.npcShopFor] - (itemId) => shop | null
     * @param {function} [ctx.itemMarketUrl] - (itemId, name) => url
     * @param {number} [ctx.now]
     */
    function feedOpportunities(feed, index, settings = {}, ctx = {}) {
        const now = ctx.now || Date.now();
        const shopOf = ctx.npcShopFor || (() => null);
        const out = [];

        const price = (item, row, extra) => {
            const npcShop = shopOf(item.id);
            const profit = bestVenue({
                listingPrice: row.price,
                exits: exitsFor(item, settings),
                qty: row.qty,
                cashOnHand: settings.cashOnHand,
            });

            if (!profit || profit.profitPerUnit <= 0) return;

            out.push({
                itemId: item.id,
                name: item.name,
                item,
                el: null,
                fromFeed: true,
                qtyAtPrice: true,
                npcShop,
                npcVerified: npcShop !== null,
                profit,
                cardLabel: '+' + formatMoneyShort(profit.totalProfit),
                ...extra,
            });
        };

        for (const [id, snap] of feed.bazaar) {
            const item = index && index.byId && index.byId.get(id);
            if (!item) continue;

            for (const row of snap.rows) {
                price(item, row, {
                    source: SOURCE_BAZAAR,
                    sellerId: row.sellerId,
                    sellerName: row.sellerName,
                    dataAt: row.dataAt || snap.fetchedAt,
                    dataAgeKnown: row.dataAt !== null,
                    fetchedAt: snap.fetchedAt,
                    url: bazaarUrl(row.sellerId, id, row.price),
                });
            }
        }

        for (const [id, snap] of feed.itemmarket) {
            const item = index && index.byId && index.byId.get(id);
            if (!item) continue;

            for (const row of snap.rows) {
                price(item, row, {
                    source: SOURCE_ITEM_MARKET,
                    sellerId: null,
                    sellerName: null,
                    dataAt: snap.dataAt,
                    dataAgeKnown: true,
                    fetchedAt: snap.fetchedAt,
                    url: ctx.itemMarketUrl ? ctx.itemMarketUrl(id, item.name) : null,
                });
            }
        }

        // Keep `now` meaningful for callers that sort by freshness.
        for (const row of out) row.ageMs = Math.max(0, now - row.dataAt);

        return out;
    }

    /* -------------------------------------------------------------- storage */

    function makeFeedCacheEntry(feed, now = Date.now()) {
        return {
            version: FEED_CACHE_VERSION,
            savedAt: now,
            bazaar: [...feed.bazaar.entries()],
            itemmarket: [...feed.itemmarket.entries()],
        };
    }

    function readFeedCacheEntry(entry, now = Date.now()) {
        const feed = emptyFeed();
        if (!entry || entry.version !== FEED_CACHE_VERSION) return feed;

        for (const [id, snap] of entry.bazaar || []) {
            if (snap && Array.isArray(snap.rows)) feed.bazaar.set(String(id), snap);
        }
        for (const [id, snap] of entry.itemmarket || []) {
            if (snap && Array.isArray(snap.rows)) feed.itemmarket.set(String(id), snap);
        }

        expireFeed(feed, now);
        return feed;
    }

    /**
     * Which items to sweep on the Item Market, likeliest deal first.
     *
     * Every item with an exit is a possible deal: someone may list it under its
     * NPC price (or, with the Market / My bazaar chips, under its value). What
     * differs is how LIKELY that is. A listing tends to sit near the item's
     * value, so the closer the exit price is to the value, the smaller the
     * discount a seller has to give before the listing beats the exit. So:
     *
     *   NPC items:          1 + NPC price / market value  (checked first)
     *   resale-only items:  1 - the exit's fee
     *
     * and the sweep runs highest score first, then cheaper items first, so the
     * items most likely to pay are checked soonest and the whole list is still
     * covered. An NPC flip is guaranteed and untaxed - the job this tool is for
     * - so every item with an NPC price goes before the resale-only ones. Two earlier versions got this wrong: 3.5/3.6 only swept items
     * whose NPC price beat a probe at 85% of value, which dropped most NPC items
     * outright; 3.7 swept every item with a value in id order, because its sort
     * compared Infinity with Infinity (NaN) whenever no cash was set.
     *
     * With cash set, an item you cannot afford one of at half its value is
     * skipped, and what your cash could make breaks ties.
     *
     * @returns {Array<string>} item ids
     */
    function itemMarketSweepList(index, settings = {}) {
        const scored = [];
        const cash = Number(settings.cashOnHand) || 0;

        for (const item of (index && index.byId && index.byId.values()) || []) {
            const sell = Number(item.sellPrice);
            const mv = Number(item.marketValue);
            const npcOn = settings.sellToNpc !== false && sell > 0;
            const resaleOn = Boolean(settings.resaleMarket || settings.resaleBazaar) && mv > 0;
            if (!npcOn && !resaleOn) continue;

            const value = mv > 0 ? mv : sell;
            let score = 0;
            let exit = 0;
            if (npcOn) {
                // NPC flips first: guaranteed and untaxed, the job this tool is
                // for. Among them, the closer the NPC price to the value, the
                // likelier a listing beats it.
                score = 1 + (mv > 0 ? Math.min(sell / mv, 2) : 1);
                exit = sell;
            }
            if (resaleOn) {
                const fee = settings.resaleBazaar ? 0 : 0.05;
                score = Math.max(score, 1 - fee);
                exit = Math.max(exit, mv * (1 - fee));
            }

            // The cheapest a real listing plausibly gets: half its value.
            const floor = value * 0.5;
            if (cash > 0 && floor > cash) continue;

            const reach = cash > 0 ? Math.floor(cash / floor) * Math.max(exit - floor, 1) : 0;
            scored.push({ id: item.id, score, value, reach });
        }

        scored.sort(
            (a, b) =>
                b.score - a.score ||
                b.reach - a.reach ||
                a.value - b.value ||
                String(a.id).localeCompare(String(b.id), undefined, { numeric: true }),
        );
        return scored.map((s) => s.id);
    }

    /* ===== src/core/leader.js ===== */
    /*
     * Which Torn tab runs the live feed. Pure: the caller reads and writes the
     * shared record.
     *
     * Every Torn tab boots this script. Without one leader, five tabs make five
     * times the requests - Torn's 100/min is per USER across every key and tool,
     * and TornW3B's 100/min is per IP. So exactly one tab polls and the others
     * render what it stores.
     *
     * Only a VISIBLE tab may lead. Torn's rules forbid software that works from
     * unfocused pages to "generate alerts, or draw attention to itself"; a hidden
     * tab polling in the background is the shape of that, so a tab that is
     * hidden gives up the role instead of keeping it.
     */

    /** A leader that has not renewed in this long is presumed gone. */
    const LEADER_STALE_MS = 10000;

    /** How often the leader renews its claim. */
    const LEADER_HEARTBEAT_MS = 3000;

    /**
     * @param {object|null} record - { id, ts } as last stored
     * @param {string} me - this tab's id
     * @param {object} opts
     * @param {number} opts.now
     * @param {boolean} opts.visible
     * @returns {{lead: boolean, confirmed: boolean, write: object|null}}
     *   `write` is the record to store (null = leave it alone). `confirmed` is
     *   true only when the stored record ALREADY named this tab: two tabs can
     *   both claim a stale record in the same instant, and only the one whose
     *   write survived sees itself there on the next tick. Poll only when
     *   confirmed, and the race costs one heartbeat instead of double requests.
     */
    function decideLeader(record, me, { now, visible, staleMs = LEADER_STALE_MS }) {
        const held = record && record.id && Number.isFinite(record.ts);
        const mine = held && record.id === me;
        const fresh = held && now - record.ts < staleMs;

        if (mine) {
            if (visible) {
                return { lead: true, confirmed: true, write: { id: me, ts: now } };
            }
            // Hidden: step down so a visible tab can take over at once.
            return { lead: false, confirmed: false, write: { id: null, ts: 0 } };
        }

        if (!fresh && visible) {
            return { lead: true, confirmed: false, write: { id: me, ts: now } };
        }

        return { lead: false, confirmed: false, write: null };
    }

    function makeTabId() {
        return (
            Date.now().toString(36) +
            '-' +
            Math.random().toString(36).slice(2, 10)
        );
    }

    /* ===== src/core/ranker.js ===== */
    /*
     * Ranking and filtering. Pure, no DOM.
     *
     * The product decision lives here: opportunities rank by the profit you can
     * actually realize (profit/unit x quantity you can afford), not by profit per
     * unit and not by percentage. A $104/ea hit with 1 available is noise; the
     * same margin with 400 available is the whole afternoon. V1 gave both the
     * same badge.
     */

    const DEFAULT_RANK_OPTIONS = {
        minTotalProfit: 1000,
        minRoi: 0,
        cashOnHand: null,
        /* See main.js: this defaults on, because the verification is an inference. */
        includeUnverifiedNpc: true,
        /*
         * Rows whose unit price had to be inferred are excluded by default.
         *
         * This is not tidiness. Ranking is by profit, and a price read too LOW
         * produces a huge apparent profit — so without this filter the least
         * trustworthy rows sort straight to the top of the list, which is exactly
         * where a wrong number does the most damage.
         */
        includeAssumedPrice: false,
        limit: 100,
    };

    /**
     * @param {Array<object>} opportunities - rows carrying a computed `profit` block
     * @param {object} options - see DEFAULT_RANK_OPTIONS
     */
    function rankOpportunities(opportunities, options = {}) {
        const opts = { ...DEFAULT_RANK_OPTIONS, ...options };

        const kept = (opportunities || []).filter((row) => {
            if (!row || !row.profit) return false;

            if (!opts.includeUnverifiedNpc && row.npcVerified === false) {
                return false;
            }

            if (!opts.includeAssumedPrice && row.priceAssumed === true) {
                return false;
            }

            /*
             * The minimum applies only to rows that HAVE a real total.
             *
             * A category tile cannot say how many units are available at its
             * price, so its "total" is a single unit's profit. Testing that
             * against a total-profit threshold compares two different quantities
             * and silently deletes most of the list - which is exactly what
             * happened when the inflated market-wide totals were corrected.
             */
            if (
                row.qtyAtPrice !== false &&
                row.profit.realizableProfit < opts.minTotalProfit
            ) {
                return false;
            }

            if (row.qtyAtPrice === false && row.profit.profitPerUnit <= 0) {
                return false;
            }
            if (row.profit.roi < opts.minRoi) return false;

            /*
             * Cash: a listing you cannot buy one of is not a deal for you, and
             * is hidden - whether or not its quantity is known, and whatever Min
             * is. A row you can afford part of stays, priced for that part.
             */
            if (!affordableRow(row, opts.cashOnHand)) return false;

            return true;
        });

        kept.sort((a, b) => {
            const byProfit = b.profit.realizableProfit - a.profit.realizableProfit;
            if (byProfit !== 0) return byProfit;

            // Tie-break on ROI, so the cheaper route to the same money wins.
            return b.profit.roi - a.profit.roi;
        });

        return opts.limit > 0 ? kept.slice(0, opts.limit) : kept;
    }

    /** Can this cash buy at least one unit of the row? No cash set = yes. */
    function affordableRow(row, cashOnHand) {
        const cash = Number(cashOnHand);
        if (!(cash > 0)) return true;
        const p = row.profit;
        if (!p) return false;
        if (row.qtyAtPrice === false) return Number(p.listingPrice) <= cash;
        return Number(p.affordableQty) >= 1;
    }

    /**
     * What the Cash and Min filters took out of a list, so an empty list can say
     * why instead of looking like "no deals".
     * @returns {{cash: number, min: number}}
     *   cash: profitable, but you cannot afford enough of it (or any of it)
     *   min:  profitable, but under Min even buying every one
     */
    function hiddenCounts(opportunities, options = {}) {
        const min = Number(options.minTotalProfit) || 0;
        const out = { cash: 0, min: 0 };

        for (const row of opportunities || []) {
            if (!row || !row.profit || row.profit.profitPerUnit <= 0) continue;
            if (!affordableRow(row, options.cashOnHand)) {
                out.cash++;
                continue;
            }
            if (row.qtyAtPrice === false) continue;
            if (row.profit.realizableProfit >= min) continue;
            if (row.profit.totalProfit >= min) out.cash++;
            else out.min++;
        }
        return out;
    }

    /**
     * Headline totals for the panel.
     *
     * With cash set, the total is what that cash can make: rows are taken best
     * first, the last one that fits only for the units the remaining cash buys,
     * and nothing after it. Summing every row's own capped profit claimed the
     * cash could be spent on all of them at once.
     *
     * @returns {{count, totalProfit, cashRequired, capped: boolean}}
     */
    function summarize(rankedRows, options = {}) {
        const rows = rankedRows || [];
        const cash = Number(options.cashOnHand);
        const limited = cash > 0;

        let totalProfit = 0;
        let cashRequired = 0;
        let capped = false;

        for (const row of rows) {
            const p = row.profit;
            if (!limited) {
                totalProfit += p.realizableProfit;
                cashRequired += p.cashRequired;
                continue;
            }

            const left = cash - cashRequired;
            if (left <= 0) {
                capped = true;
                break;
            }
            if (p.cashRequired <= left) {
                totalProfit += p.realizableProfit;
                cashRequired += p.cashRequired;
                continue;
            }
            const units = p.listingPrice > 0 ? Math.floor(left / p.listingPrice) : 0;
            totalProfit += p.profitPerUnit * units;
            cashRequired += p.listingPrice * units;
            capped = true;
            break;
        }

        return { count: rows.length, totalProfit, cashRequired, capped };
    }

    /* ===== src/api/client.js ===== */
    /*
     * The one place that talks to the network.
     *
     * Non-negotiables enforced here rather than by convention:
     *
     *   1. api.torn.com is the ONLY destination. The base URL is a constant and
     *      callers pass a path, never a URL. No third party ever receives a Torn
     *      key, because no third party can be addressed from this client.
     *   2. The key is never logged. Errors are redacted before they are thrown,
     *      so a stack trace pasted into Discord cannot leak it.
     *   3. Every call goes through one rate-limited queue (<=70/min against
     *      Torn's ~100/min ceiling) with request dedup and exponential backoff.
     *      A key that trips abuse detection is a worse outcome than a slow panel.
     */



    const TORN_API_BASE = 'https://api.torn.com/';

    /** Torn error codes worth reacting to specifically. */
    const TORN_ERROR_KEY_INVALID = 2;
    const TORN_ERROR_RATE_LIMIT = 5;
    const TORN_ERROR_IP_BLOCK = 8;
    const TORN_ERROR_UNAVAILABLE = 9;
    const TORN_ERROR_KEY_DISABLED = 13;
    const TORN_ERROR_KEY_PAUSED = 18;

    /**
     * Errors that mean "this key must not be used again until the user changes
     * it". Torn's docs: "Multiple requests using invalid keys may result in a
     * temporary IP ban - you must account for this by removing disabled or
     * invalid keys upon error."
     */
    const KEY_DEAD_CODES = new Set([
        TORN_ERROR_KEY_INVALID,
        TORN_ERROR_KEY_DISABLED,
        TORN_ERROR_KEY_PAUSED,
    ]);

    /** Torn's rate block lasts "a small period"; 1-2-4s retries only burn it. */
    const RATE_LIMIT_BACKOFF_MS = 30000;

    class TornApiError extends Error {
        constructor(message, { code = null, http = null } = {}) {
            super(message);
            this.name = 'TornApiError';
            this.code = code;
            this.http = http;
        }
    }

    function apiSleep(ms) {
        return new Promise((resolve) => setTimeout(resolve, ms));
    }

    /**
     * Strip anything that looks like an API key out of a string before it can
     * reach a console, an alert, or the panel.
     */
    function redactKey(text, key) {
        let out = String(text === null || text === undefined ? '' : text);

        if (key) out = out.split(key).join('<redacted>');

        // Belt and braces: catch a key that arrived from somewhere else.
        return out.replace(/key=[A-Za-z0-9]{8,}/g, 'key=<redacted>');
    }

    class TornApiClient {
        /**
         * @param {object} options
         * @param {function(): string} options.getKey - returns the current API key
         * @param {function} [options.fetchImpl]      - injectable for tests
         * @param {number} [options.maxPerMinute]     - request ceiling
         * @param {number} [options.dedupTtlMs]       - reuse identical responses
         * @param {number} [options.maxRetries]
         * @param {function(): number[]} [options.loadWindow] - shared request
         *   timestamps, so every open Torn tab draws on ONE budget. Torn's limit
         *   is per user across all keys; a per-tab window let two tabs make
         *   140/min against a 100/min ceiling.
         * @param {function(number[])} [options.saveWindow]
         */
        constructor({
            getKey,
            fetchImpl = gmFetch,
            maxPerMinute = 70,
            dedupTtlMs = 5000,
            maxRetries = 3,
            loadWindow = null,
            saveWindow = null,
            rateLimitBackoffMs = RATE_LIMIT_BACKOFF_MS,
        } = {}) {
            this.getKey = getKey;
            this.fetchImpl = fetchImpl;
            this.maxPerMinute = maxPerMinute;
            this.dedupTtlMs = dedupTtlMs;
            this.maxRetries = maxRetries;
            this.loadWindow = loadWindow;
            this.saveWindow = saveWindow;
            this.rateLimitBackoffMs = rateLimitBackoffMs;

            /** Timestamps of recent requests, for the sliding window. */
            this.recent = [];
            /** Serialises the queue so the window check cannot race. */
            this.chain = Promise.resolve();
            /** In-flight and recently-completed requests, keyed without the key. */
            this.inflight = new Map();
            this.cache = new Map();
        }

        /** Requests made in the last 60s, and room remaining. */
        stats(now = Date.now()) {
            this.syncWindow(now);
            const window = this.recent.filter((t) => now - t < 60000);
            return {
                usedLastMinute: window.length,
                remaining: Math.max(0, this.maxPerMinute - window.length),
            };
        }

        /**
         * Adopt the shared window: it already holds this tab's own requests,
         * because every slot taken is saved back to it. Replacing rather than
         * merging matters - two requests in the same millisecond are two
         * requests, and a Set of timestamps would count them as one.
         */
        syncWindow(now = Date.now()) {
            if (!this.loadWindow) return;

            let shared;
            try {
                shared = this.loadWindow();
            } catch {
                return;
            }
            if (!Array.isArray(shared)) return;

            this.recent = shared
                .filter((t) => Number.isFinite(t) && now - t < 60000)
                .sort((a, b) => a - b);
        }

        /** Block until the sliding window has room for one more request. */
        async waitForSlot() {
            for (;;) {
                const now = Date.now();
                this.syncWindow(now);
                this.recent = this.recent.filter((t) => now - t < 60000);

                if (this.recent.length < this.maxPerMinute) {
                    this.recent.push(now);
                    if (this.saveWindow) {
                        try {
                            this.saveWindow(this.recent);
                        } catch {
                            // Sharing the window is best-effort; the local one
                            // still limits this tab.
                        }
                    }
                    return;
                }

                const oldest = this.recent[0];
                await apiSleep(Math.max(50, 60000 - (now - oldest) + 25));
            }
        }

        /**
         * GET a Torn API path.
         *
         * @param {string} path - e.g. "torn" or "user" or "market/123"
         * @param {object} params - query params; `key` is added here and only here
         */
        async get(path, params = {}) {
            const cacheKey = path + '?' + new URLSearchParams(params).toString();

            const cached = this.cache.get(cacheKey);
            if (cached && Date.now() - cached.at < this.dedupTtlMs) {
                return cached.data;
            }

            const existing = this.inflight.get(cacheKey);
            if (existing) return existing;

            // Queue behind whatever is already scheduled, then take a slot.
            const promise = this.chain
                .catch(() => {})
                .then(() => this.execute(path, params, cacheKey));

            this.chain = promise.catch(() => {});
            this.inflight.set(cacheKey, promise);

            try {
                const data = await promise;
                this.pruneCache();
                this.cache.set(cacheKey, { at: Date.now(), data });
                return data;
            } finally {
                this.inflight.delete(cacheKey);
            }
        }

        /** The dedup cache is for bursts, not memory; a sweep adds hundreds. */
        pruneCache(now = Date.now()) {
            for (const [k, v] of this.cache) {
                if (now - v.at >= this.dedupTtlMs) this.cache.delete(k);
            }
        }

        async execute(path, params, cacheKey) {
            if (!this.fetchImpl) {
                throw new TornApiError('No fetch implementation available.');
            }

            const key = this.getKey ? this.getKey() : '';
            if (!key) {
                throw new TornApiError('No API key set.', {
                    code: TORN_ERROR_KEY_INVALID,
                });
            }

            let attempt = 0;
            let lastError = null;

            while (attempt <= this.maxRetries) {
                await this.waitForSlot();

                try {
                    return await this.requestOnce(path, params, key);
                } catch (error) {
                    lastError = error;

                    if (!this.isRetryable(error) || attempt === this.maxRetries) {
                        throw error;
                    }

                    // Torn's rate block outlasts a quick retry; wait it out.
                    // Otherwise exponential backoff: 1s, 2s, 4s.
                    const rateLimited =
                        error instanceof TornApiError &&
                        (error.code === TORN_ERROR_RATE_LIMIT || error.http === 429);

                    await apiSleep(
                        rateLimited
                            ? this.rateLimitBackoffMs
                            : 1000 * Math.pow(2, attempt),
                    );
                    attempt += 1;
                }
            }

            throw lastError;
        }

        isRetryable(error) {
            if (!(error instanceof TornApiError)) return true;

            if (error.code === TORN_ERROR_RATE_LIMIT) return true;
            if (error.code === TORN_ERROR_UNAVAILABLE) return true;
            if (error.http && error.http >= 500) return true;
            if (error.http === 429) return true;

            // A bad key or an IP block will not fix itself by asking again.
            return false;
        }

        async requestOnce(path, params, key) {
            /*
             * v1 paths take a trailing slash ("torn/?selections=items" is the form
             * verified in game). v2 paths are written without one everywhere they
             * are documented, so they are left exactly as given.
             */
            const clean = String(path).replace(/^\/+/, '');
            const url = new URL(
                /^v2\//.test(clean) ? clean : clean + '/',
                TORN_API_BASE,
            );

            /*
             * A relative path resolves under the base, but an ABSOLUTE one
             * ("https://elsewhere/steal") overrides it entirely — and the key is
             * attached below. The base being a constant is therefore not enough
             * on its own; this is the assertion that actually enforces "one
             * destination".
             */
            if (url.hostname !== 'api.torn.com') {
                throw new TornApiError(
                    'Refusing to send the API key to ' + url.hostname + '.',
                );
            }

            for (const [name, value] of Object.entries(params || {})) {
                if (value === undefined || value === null) continue;
                url.searchParams.set(name, String(value));
            }
            url.searchParams.set('key', key);
            url.searchParams.set('comment', 'TornTradingV2');

            let response;
            try {
                response = await this.fetchImpl(url.toString());
            } catch (error) {
                throw new TornApiError(
                    'Network error: ' + redactKey(error && error.message, key),
                );
            }

            if (!response.ok) {
                throw new TornApiError('HTTP ' + response.status, {
                    http: response.status,
                });
            }

            let data;
            try {
                data = await response.json();
            } catch {
                throw new TornApiError('Torn API returned invalid JSON.');
            }

            /*
             * Errors arrive as HTTP 200 with { error: { code, error } } - and
             * some v2 endpoints are reported to put { code, error } at the top
             * level instead. Read both, or a v2 error looks like an empty result.
             */
            const err =
                data && data.error && typeof data.error === 'object'
                    ? data.error
                    : data &&
                        Number.isFinite(Number(data.code)) &&
                        typeof data.error === 'string'
                      ? { code: Number(data.code), error: data.error }
                      : null;

            if (err) {
                throw new TornApiError(
                    'Torn API ' + err.code + ': ' + redactKey(err.error, key),
                    { code: Number(err.code) },
                );
            }

            return data;
        }
    }

    /* ===== src/api/w3b.js ===== */
    /*
     * TornW3B (weav3r.dev) - the crowd-sourced bazaar price feed.
     *
     * Torn's API has no per-listing bazaar prices a Public key can trust (the
     * `user -> bazaar` selection can be served days old on a Public key, and the
     * `market -> bazaar` selection is a directory with no prices). TornW3B polls
     * bazaars with keys their SELLERS donated, for their own bazaar only, and
     * publishes the result. TornTools, TornPDA and Weav3r's own script read it.
     *
     * Non-negotiables, enforced here rather than by convention:
     *
     *   1. This client NEVER sees a Torn API key. It has no key parameter, no
     *      getKey, and the only query it ever sends is `comment`. The Torn client
     *      and this one share nothing.
     *   2. weav3r.dev is the only destination - asserted on the resolved URL, not
     *      just implied by a constant, exactly as client.js does for api.torn.com.
     *   3. Its own sliding window, well under TornW3B's 100/min Cloudflare limit,
     *      and a hard cooldown on 429 or a non-JSON (Cloudflare challenge) body.
     *
     * Responses are cached server-side for 60s, so asking faster is pointless.
     */



    const W3B_API_BASE = 'https://weav3r.dev/api/';
    const W3B_HOST = 'weav3r.dev';
    const W3B_TERMS_URL = 'https://weav3r.dev/terms-of-service';
    const W3B_SITE_URL = 'https://weav3r.dev';

    /** TornW3B enforces 100/min per IP; leave 40 for TornTools and friends. */
    const W3B_MAX_PER_MINUTE = 60;

    /** After a 429 or a challenge page, stop asking for this long. */
    const W3B_COOLDOWN_MS = 60000;

    class W3bError extends Error {
        constructor(message, { http = null, blocked = false } = {}) {
            super(message);
            this.name = 'W3bError';
            this.http = http;
            this.blocked = blocked;
        }
    }

    function w3bSleep(ms) {
        return new Promise((resolve) => setTimeout(resolve, ms));
    }

    class W3bClient {
        /**
         * @param {object} [options]
         * @param {function} [options.fetchImpl] - injectable for tests
         * @param {number} [options.maxPerMinute]
         * @param {function} [options.now]
         */
        constructor({
            fetchImpl = gmFetch,
            maxPerMinute = W3B_MAX_PER_MINUTE,
            now = () => Date.now(),
        } = {}) {
            this.fetchImpl = fetchImpl;
            this.maxPerMinute = maxPerMinute;
            this.now = now;
            this.recent = [];
            this.chain = Promise.resolve();
            this.cooldownUntil = 0;
        }

        stats() {
            const t = this.now();
            const used = this.recent.filter((x) => t - x < 60000).length;
            return {
                usedLastMinute: used,
                remaining: Math.max(0, this.maxPerMinute - used),
                coolingDown: t < this.cooldownUntil,
            };
        }

        async waitForSlot() {
            for (;;) {
                const t = this.now();
                this.recent = this.recent.filter((x) => t - x < 60000);

                if (this.recent.length < this.maxPerMinute) {
                    this.recent.push(t);
                    return;
                }

                await w3bSleep(Math.max(50, 60000 - (t - this.recent[0]) + 25));
            }
        }

        /** Build and check a URL. Exposed for tests. */
        buildUrl(path) {
            const url = new URL(String(path).replace(/^\/+/, ''), W3B_API_BASE);

            if (url.hostname !== W3B_HOST) {
                throw new W3bError('Refusing to contact ' + url.hostname + '.');
            }

            // Nothing but an attribution comment ever goes in the query.
            url.search = '';
            url.searchParams.set('comment', 'TornTradingV2');

            return url;
        }

        /** GET one TornW3B path. Serialised, rate-limited, never keyed. */
        get(path) {
            const run = () => this.execute(path);
            const promise = this.chain.catch(() => {}).then(run);
            this.chain = promise.catch(() => {});
            return promise;
        }

        async execute(path) {
            if (this.now() < this.cooldownUntil) {
                throw new W3bError('TornW3B is rate limiting us; paused briefly.', {
                    blocked: true,
                });
            }

            const url = this.buildUrl(path);
            await this.waitForSlot();

            let response;
            try {
                response = await this.fetchImpl(url.toString());
            } catch (error) {
                throw new W3bError(
                    'TornW3B network error: ' + ((error && error.message) || error),
                );
            }

            if (response.status === 429) {
                this.cooldownUntil = this.now() + W3B_COOLDOWN_MS;
                throw new W3bError('TornW3B rate limit (429).', {
                    http: 429,
                    blocked: true,
                });
            }

            if (!response.ok) {
                throw new W3bError('TornW3B HTTP ' + response.status, {
                    http: response.status,
                });
            }

            try {
                return await response.json();
            } catch {
                // Cloudflare answers a challenge page with HTML, not JSON.
                this.cooldownUntil = this.now() + W3B_COOLDOWN_MS;
                throw new W3bError('TornW3B returned a non-JSON page (blocked?).', {
                    blocked: true,
                });
            }
        }
    }

    /**
     * Cheapest bazaar price for every item, in one request.
     *
     * @returns {Promise<Array<{itemId: string, name: string, lowestPrice: number|null,
     *   marketPrice: number|null, bazaarAverage: number|null, totalBazaars: number}>>}
     */
    async function fetchW3bSummary(client) {
        const data = await client.get('marketplace');
        const items = data && Array.isArray(data.items) ? data.items : null;

        if (!items) throw new W3bError('TornW3B returned no item summary.');

        return items
            .filter((i) => i && Number.isFinite(Number(i.item_id)))
            .map((i) => ({
                itemId: String(i.item_id),
                name: i.item_name || '',
                lowestPrice: positiveOrNull(i.lowest_price),
                marketPrice: positiveOrNull(i.market_price),
                bazaarAverage: positiveOrNull(i.bazaar_average),
                totalBazaars: Number(i.total_bazaars) || 0,
            }));
    }

    /**
     * Every bazaar listing TornW3B knows for one item.
     *
     * Retries once when the payload says there are listings but sends none - a
     * known mid-scan glitch. `maxPrice` and friends are deliberately NOT sent:
     * they are not in TornW3B's spec, TornTools filters client-side anyway, and
     * trusting an ignored filter is how a list fills with rows that are not deals.
     *
     * @returns {Promise<{listings: Array, total: number}>} raw listing objects
     */
    async function fetchW3bListings(client, itemId) {
        const path = 'marketplace/' + encodeURIComponent(String(itemId));

        let data = await client.get(path);

        const empty = (d) =>
            d &&
            Number(d.total_listings) > 0 &&
            Array.isArray(d.listings) &&
            d.listings.length === 0;

        if (empty(data)) data = await client.get(path);

        return {
            listings: data && Array.isArray(data.listings) ? data.listings : [],
            total: Number(data && data.total_listings) || 0,
        };
    }

    function positiveOrNull(value) {
        const n = Number(value);
        return Number.isFinite(n) && n > 0 ? n : null;
    }

    /* ===== src/api/te.js ===== */
    /*
     * TornExchange (tornexchange.com) - traders' published buy prices.
     *
     * TornExchange is where traders post "I buy X at $Y". Its API wants `?key=`
     * equal to the Torn API key the user last logged into TornExchange with
     * (main/api.py, require_api_key). So this client carries a key - but NEVER
     * the main one:
     *
     *   1. It is given its own key (Settings -> TornExchange), which main.js
     *      refuses to accept if it equals the main Torn key. The Torn client and
     *      this one share nothing.
     *   2. www.tornexchange.com is the only destination - asserted on the
     *      resolved URL, as client.js does for api.torn.com.
     *   3. Its rate limit is harsh: 10 requests a minute PER IP across the whole
     *      API, and every request over it doubles a penalty that can reach 48
     *      hours (rate_limit_exponential in main/api.py). So this client makes
     *      at most TE_MIN_GAP_MS between requests, never retries on its own, and
     *      after a 429 waits out the server's `retry_after` before asking again.
     *
     * One call, /api/all_best_listings, returns the top three buyers for EVERY
     * item (active traders with a non-negative score only). The server caches it
     * for 5 minutes; we ask every 30. /api/listings?item_id= lists every buyer
     * of one item (names and prices only, 20 a page), fetched only when the user
     * opens that item and kept for 30 minutes.
     */



    const TE_API_BASE = 'https://www.tornexchange.com/api/';
    const TE_HOST = 'www.tornexchange.com';
    const TE_SITE_URL = 'https://www.tornexchange.com';

    /** A trader's public price list on TornExchange (accepts id or name). */
    function tePriceListUrl(traderId) {
        return TE_SITE_URL + '/prices/' + encodeURIComponent(String(traderId)) + '/';
    }

    /**
     * Never two requests closer than this, from any code path: at most 6 a
     * minute against TornExchange's 10, leaving room for its own site.
     */
    const TE_MIN_GAP_MS = 10000;

    class TeError extends Error {
        constructor(message, { http = null, retryAfterMs = 0, badKey = false, tooSoon = false } = {}) {
            super(message);
            this.name = 'TeError';
            this.http = http;
            this.retryAfterMs = retryAfterMs;
            this.badKey = badKey;
            /** Refused by this client for pacing, never sent: ask again later. */
            this.tooSoon = tooSoon;
        }
    }

    class TeClient {
        /**
         * @param {object} options
         * @param {function} options.getKey      - () => the TornExchange key ('' = none)
         * @param {function} [options.fetchImpl] - injectable for tests
         * @param {function} [options.now]
         * @param {function} [options.loadState] - () => { lastRequestAt, blockedUntil }
         *   shared by every tab, so a reload or a second selling tab keeps the
         *   same pace and the same penalty wait as this one.
         * @param {function} [options.saveState] - (state) => void
         */
        constructor({ getKey, fetchImpl = gmFetch, now = () => Date.now(), loadState = null, saveState = null } = {}) {
            this.getKey = getKey || (() => '');
            this.fetchImpl = fetchImpl;
            this.now = now;
            this.loadState = loadState;
            this.saveState = saveState;
            this.lastRequestAt = 0;
            this.blockedUntil = 0;
        }

        /** Adopt the shared state: the later of what this tab and storage know. */
        syncState() {
            if (!this.loadState) return;
            let shared;
            try {
                shared = this.loadState();
            } catch {
                return;
            }
            if (!shared || typeof shared !== 'object') return;
            const last = Number(shared.lastRequestAt);
            const blocked = Number(shared.blockedUntil);
            if (Number.isFinite(last) && last > this.lastRequestAt) this.lastRequestAt = last;
            if (Number.isFinite(blocked) && blocked > this.blockedUntil) this.blockedUntil = blocked;
        }

        persistState() {
            if (!this.saveState) return;
            try {
                this.saveState({ lastRequestAt: this.lastRequestAt, blockedUntil: this.blockedUntil });
            } catch {
                // Sharing is best-effort; this tab still paces itself.
            }
        }

        /** Build and check a URL. The key is attached here and nowhere else. */
        buildUrl(path, key) {
            const url = new URL(String(path).replace(/^\/+/, ''), TE_API_BASE);

            if (url.hostname !== TE_HOST) {
                throw new TeError('Refusing to contact ' + url.hostname + '.');
            }

            url.search = '';
            url.searchParams.set('key', key);
            return url;
        }

        /** When the next request may go, given the gap and any 429 wait. */
        nextAllowedAt() {
            this.syncState();
            return Math.max(this.blockedUntil, this.lastRequestAt + TE_MIN_GAP_MS);
        }

        async get(path, params = {}) {
            const key = String(this.getKey() || '').trim();
            if (!key) throw new TeError('No TornExchange key.', { badKey: true });

            this.syncState();
            const t = this.now();
            if (t < this.blockedUntil) {
                throw new TeError('TornExchange asked us to wait.', {
                    http: 429,
                    retryAfterMs: this.blockedUntil - t,
                });
            }
            if (t - this.lastRequestAt < TE_MIN_GAP_MS) {
                throw new TeError('Too soon to ask TornExchange again.', {
                    retryAfterMs: TE_MIN_GAP_MS - (t - this.lastRequestAt),
                    tooSoon: true,
                });
            }

            const url = this.buildUrl(path, key);
            for (const [name, value] of Object.entries(params || {})) {
                if (value !== undefined && value !== null && name !== 'key') {
                    url.searchParams.set(name, String(value));
                }
            }
            this.lastRequestAt = t;
            this.persistState();

            let response;
            try {
                response = await this.fetchImpl(url.toString());
            } catch (error) {
                // The message never carries the URL, so never the key.
                throw new TeError('TornExchange network error.');
            }

            let body = null;
            try {
                body = await response.json();
            } catch {
                body = null;
            }

            if (response.status === 429) {
                const seconds = Number(body && body.retry_after);
                const wait = (Number.isFinite(seconds) && seconds > 0 ? seconds : 60) * 1000;
                this.blockedUntil = this.now() + wait;
                this.persistState();
                throw new TeError('TornExchange rate limit - waiting ' + Math.ceil(wait / 1000) + 's.', {
                    http: 429,
                    retryAfterMs: wait,
                });
            }

            if (response.status === 401) {
                throw new TeError(
                    'TornExchange did not accept the key. Log in at tornexchange.com ' +
                        'with this same key, then save it again.',
                    { http: 401, badKey: true },
                );
            }

            if (!response.ok || !body) {
                throw new TeError('TornExchange HTTP ' + response.status + '.', {
                    http: response.status,
                });
            }

            if (body.status && body.status !== 'success') {
                throw new TeError('TornExchange: ' + String(body.message || 'error') + '.');
            }

            return body;
        }
    }

    /**
     * The top three buyers for every item, highest price first.
     *
     * @returns {Promise<Map<string, Array<{name: string, id: string, price: number, score: number}>>>}
     */
    async function fetchTeBestListings(client) {
        return parseTeBestListings(await client.get('all_best_listings'));
    }

    /** Exposed for tests. Bad rows are dropped, never guessed. */
    function parseTeBestListings(body) {
        const data = body && body.data;
        if (!data || typeof data !== 'object') {
            throw new TeError('TornExchange returned no trader prices.');
        }

        const out = new Map();

        for (const [itemId, entry] of Object.entries(data)) {
            if (!/^\d+$/.test(itemId) || !entry || !Array.isArray(entry.traders)) continue;

            const traders = [];
            for (const t of entry.traders) {
                const id = String((t && t.trader_id) || '').replace(/\D/g, '');
                const price = Number(t && t.price);
                if (!id || !Number.isFinite(price) || price <= 0) continue;

                traders.push({
                    name: typeof t.trader === 'string' && t.trader ? t.trader : 'Trader ' + id,
                    id,
                    price,
                    score: Number(t.vote_score) || 0,
                });
            }

            if (traders.length) {
                traders.sort((a, b) => b.price - a.price);
                out.set(itemId, traders);
            }
        }

        return out;
    }

    /**
     * Every buyer of one item, highest price first: /api/listings?item_id=.
     * Names and prices only - the endpoint carries no trader id - and 20 a page;
     * up to `maxPages` pages are read. Each page is its own request, handed to
     * `schedule` (a TeQueue's enqueue) so pages go one per slot: asked directly,
     * page 2 would follow page 1 inside the gap and be refused.
     *
     * @returns {Promise<{traders: Array<{name: string, price: number}>, total: number, complete: boolean}>}
     */
    async function fetchTeListings(client, itemId, { maxPages = 3, schedule = (fn) => fn() } = {}) {
        const traders = [];
        let total = 0;
        let pages = 1;

        for (let page = 1; page <= maxPages && page <= pages; page += 1) {
            const body = await schedule(() =>
                client.get('listings', {
                    item_id: String(itemId),
                    sort_by: 'price',
                    order: 'desc',
                    page,
                }),
            );
            const parsed = parseTeListings(body);
            traders.push(...parsed.traders);
            total = parsed.total;
            pages = parsed.pages;
        }

        traders.sort((a, b) => b.price - a.price);
        return { traders, total, complete: pages <= maxPages };
    }

    /**
     * TornExchange calls one at a time, each in its own slot: the next runs no
     * sooner than the client's nextAllowedAt(), which includes the shared pace
     * and any 429 wait. A call the client refuses as too soon goes back to the
     * front of the line; anything else fails that call only. Nothing runs while
     * the tab is hidden.
     */
    class TeQueue {
        /**
         * @param {object} options
         * @param {TeClient} options.client
         * @param {function} [options.now]
         * @param {function} [options.setTimer]  - (fn, ms) => void; injectable for tests
         * @param {function} [options.isVisible] - () => boolean
         * @param {function} [options.onSettled] - (error|null) after every call
         */
        constructor({ client, now = () => Date.now(), setTimer = (fn, ms) => setTimeout(fn, ms), isVisible = () => true, onSettled = () => {} }) {
            this.client = client;
            this.now = now;
            this.setTimer = setTimer;
            this.isVisible = isVisible;
            this.onSettled = onSettled;
            this.jobs = [];
            this.waiting = false;
        }

        get length() {
            return this.jobs.length;
        }

        /** @returns {Promise} what `fn` returns, once its slot has come. */
        enqueue(fn) {
            return new Promise((resolve, reject) => {
                this.jobs.push({ fn, resolve, reject });
                this.run();
            });
        }

        run() {
            if (this.waiting || !this.jobs.length) return;
            this.waiting = true;
            const wait = Math.max(0, this.client.nextAllowedAt() - this.now());
            this.setTimer(() => this.step(), wait);
        }

        async step() {
            this.waiting = false;
            if (!this.isVisible()) {
                this.waiting = true;
                this.setTimer(() => {
                    this.waiting = false;
                    this.run();
                }, 5000);
                return;
            }
            // Another tab may have used the slot since the timer was set.
            if (this.client.nextAllowedAt() > this.now()) {
                this.run();
                return;
            }
            const job = this.jobs.shift();
            if (!job) return;
            try {
                const result = await job.fn();
                job.resolve(result);
                this.onSettled(null);
            } catch (error) {
                if (error && error.tooSoon) {
                    this.jobs.unshift(job);
                } else {
                    job.reject(error);
                    this.onSettled(error);
                }
            }
            this.run();
        }
    }

    /** Exposed for tests. */
    function parseTeListings(body) {
        const data = body && body.data;
        if (!data || !Array.isArray(data.listings)) {
            throw new TeError('TornExchange returned no buyer list.');
        }

        const traders = [];
        for (const l of data.listings) {
            const price = Number(l && l.price);
            if (!l || typeof l.trader !== 'string' || !l.trader || !Number.isFinite(price) || price <= 0) continue;
            traders.push({ name: l.trader, price });
        }
        traders.sort((a, b) => b.price - a.price);

        const meta = data.meta || {};
        return {
            traders,
            total: Number(meta.total_listings) || traders.length,
            pages: Number(meta.total_pages) || 1,
        };
    }

    /**
     * Every active trader's name and Torn id: /api/active_traders. Used to give
     * a name from a buyer list its id (for the profile link and online status).
     * @returns {Promise<Map<string, string>>} lowercase name -> torn id
     */
    async function fetchTeActiveTraders(client) {
        return parseTeActiveTraders(await client.get('active_traders'));
    }

    function parseTeActiveTraders(body) {
        const verbose = body && body.data && body.data.verbose;
        const out = new Map();
        if (!verbose || typeof verbose !== 'object') return out;
        for (const t of Object.values(verbose)) {
            const id = String((t && t.torn_id) || '').replace(/\D/g, '');
            if (t && typeof t.name === 'string' && t.name && id) out.set(t.name.toLowerCase(), id);
        }
        return out;
    }

    /* ===== src/core/selling.js ===== */
    /*
     * The selling page's logic: which trader pays most for each item you hold.
     * Pure - no DOM, no network.
     *
     * Traders are ALWAYS ranked highest price first. "Online only" drops the
     * traders who are not online and ranks the rest the same way; it never
     * reorders by status. A trader's price is an offer on their TornExchange
     * list, so every row also shows what the item usually goes for (Torn's
     * market value, the daily average of actual sales) and what traders offer
     * on average, for a sense of whether the best offer is out of line.
     */

    /** Ask TornExchange for the top buyers this often. It caches for 5 min. */
    const TE_REFRESH_MS = 30 * 60 * 1000;

    /** Trader prices older than this are not used at all. */
    const TE_MAX_AGE_MS = 24 * 60 * 60 * 1000;

    const TE_CACHE_VERSION = 1;

    /** A per-item full buyer list is kept this long before it is asked again. */
    const TE_ITEM_TTL_MS = 30 * 60 * 1000;

    /** 'online' | 'idle' | 'offline' | 'unknown' from a parsed presence. */
    function presenceLevel(presence) {
        const s = presence && presence.online;
        return s ? String(s).toLowerCase() : 'unknown';
    }

    /**
     * Highest price first; ties by TornExchange score. With onlineOnly, only
     * traders known to be online are kept.
     *
     * @param {Array<{name, id, price, score}>} traders
     * @param {object} ctx
     * @param {function} ctx.presenceOf - (traderId) => presence | null
     * @param {boolean} [ctx.onlineOnly]
     * @returns {Array<{trader, level}>}
     */
    function rankOffers(traders, { presenceOf = () => null, onlineOnly = false } = {}) {
        const ranked = [];
        for (const trader of traders || []) {
            if (!trader || !(trader.price > 0)) continue;
            const level = trader.id ? presenceLevel(presenceOf(trader.id)) : 'unknown';
            if (onlineOnly && level !== 'online') continue;
            ranked.push({ trader, level });
        }

        ranked.sort(
            (a, b) =>
                b.trader.price - a.trader.price ||
                (b.trader.score || 0) - (a.trader.score || 0) ||
                String(a.trader.name).localeCompare(String(b.trader.name)),
        );
        return ranked;
    }

    /** Plain average of every trader's price, or null with nothing to average. */
    function tradersAverage(traders) {
        let sum = 0;
        let n = 0;
        for (const t of traders || []) {
            if (t && t.price > 0) {
                sum += t.price;
                n += 1;
            }
        }
        return n ? Math.round(sum / n) : null;
    }

    /**
     * Traders from two sources, merged by name: TornExchange's top-three list
     * (with ids) and an item's full buyer list (names and prices only). A name
     * on the full list that the top-three or the active-traders list knows gets
     * its id; the rest keep no id and so no profile link or online status.
     *
     * The full list carries everyone, where the top-three list carries only
     * active traders with a non-negative score. So when the active-traders list
     * is known, a full-list name on neither it nor the top three is left out
     * (an inactive trader), and a known negative score is left out too.
     *
     * @param {Array} best - top-three traders for the item (name, id, price, score)
     * @param {Array|null} full - the full buyer list (name, price), or null if not loaded
     * @param {Map} [idsByName] - lowercase active trader name -> torn id
     * @returns {{traders: Array, partial: boolean}} partial = only the top three are known
     */
    function mergeTraders(best, full, idsByName = new Map()) {
        const known = new Map();
        const negative = new Set();
        for (const t of best || []) {
            if (!t || !t.name) continue;
            const key = String(t.name).toLowerCase();
            if (t.score < 0) negative.add(key);
            else known.set(key, { ...t });
        }

        if (!Array.isArray(full)) {
            return { traders: [...known.values()], partial: true };
        }

        const activeKnown = idsByName && idsByName.size > 0;
        const out = new Map();
        for (const t of full) {
            if (!t || !t.name || !(t.price > 0)) continue;
            const key = String(t.name).toLowerCase();
            if (negative.has(key)) continue;
            const b = known.get(key);
            if (!b && activeKnown && !idsByName.has(key)) continue;
            out.set(key, {
                name: b ? b.name : t.name,
                id: (b && b.id) || idsByName.get(key) || null,
                price: t.price,
                score: b ? b.score : 0,
            });
        }
        // A top-three trader missing from the full list (paging, a hidden
        // listing) is still a buyer.
        for (const [key, b] of known) if (!out.has(key)) out.set(key, b);

        return { traders: [...out.values()], partial: false };
    }

    /** How the item list is ordered: by the best single-item offer, or by the bundle (qty x offer). */
    const SORT_ITEM = 'item';
    const SORT_BUNDLE = 'bundle';

    /**
     * One row per item you hold, with its best offer.
     *
     * @param {Array<{id, name, qty}>} inventory - from mergeInventory
     * @param {object} index - item index (market values, names)
     * @param {object} ctx
     * @param {function} ctx.tradersFor - (itemId) => {traders, partial}
     * @param {function} ctx.presenceOf
     * @param {boolean} [ctx.onlineOnly]
     * @param {string} [ctx.sortBy] - SORT_ITEM (default): best offer per item,
     *   highest first; SORT_BUNDLE: qty x best offer, highest first. Items with
     *   no buyer come last either way, by value.
     * @returns {Array<object>}
     */
    function buildSellingRows(inventory, index, { tradersFor, presenceOf = () => null, onlineOnly = false, sortBy = SORT_ITEM }) {
        const rows = [];

        for (const held of inventory || []) {
            const item = index && index.byId ? index.byId.get(String(held.id)) : null;
            const { traders, partial } = tradersFor(held.id) || { traders: [], partial: true };
            const offers = rankOffers(traders, { presenceOf, onlineOnly });
            const best = offers[0] || null;
            const marketValue = item ? Number(item.marketValue) || null : null;

            rows.push({
                itemId: String(held.id),
                name: (item && item.name) || held.name || 'Item ' + held.id,
                qty: held.qty,
                marketValue,
                offers,
                best,
                bestPrice: best ? best.trader.price : null,
                total: best ? best.trader.price * held.qty : null,
                tradersAvg: tradersAverage(traders),
                avgPartial: partial,
                buyers: traders.length,
            });
        }

        const bundle = sortBy === SORT_BUNDLE;
        rows.sort((a, b) => {
            if ((a.total === null) !== (b.total === null)) return a.total === null ? 1 : -1;
            if (a.total !== null) {
                return bundle
                    ? b.total - a.total || b.bestPrice - a.bestPrice
                    : b.bestPrice - a.bestPrice || b.total - a.total;
            }
            const av = (a.marketValue || 0) * (bundle ? a.qty : 1);
            const bv = (b.marketValue || 0) * (bundle ? b.qty : 1);
            return bv - av || String(a.name).localeCompare(String(b.name));
        });
        return rows;
    }

    /** Everyone a selling list would like a status for: best traders first. */
    function tradersToWatch(rows, { expanded = new Set(), max = 20 } = {}) {
        const ids = [];
        const push = (id) => {
            if (id && !ids.includes(id) && ids.length < max) ids.push(String(id));
        };
        for (const r of rows) if (r.best) push(r.best.trader.id);
        for (const r of rows) {
            if (!expanded.has(r.itemId)) continue;
            for (const o of r.offers) push(o.trader.id);
        }
        for (const r of rows) for (const o of r.offers) push(o.trader.id);
        return ids;
    }

    /* -------------------------------------------------------------- storage */

    /** Compact form for GM storage: {id: [[name, traderId, price, score], ...]}. */
    function makeTeCacheEntry(map, now = Date.now()) {
        const items = {};
        for (const [itemId, traders] of map) {
            items[itemId] = traders.map((t) => [t.name, t.id, t.price, t.score]);
        }
        return { version: TE_CACHE_VERSION, fetchedAt: now, items };
    }

    /** @returns {{fetchedAt: number, map: Map}|null} null if absent, old-format or too old */
    function readTeCacheEntry(entry, now = Date.now()) {
        if (!entry || entry.version !== TE_CACHE_VERSION || !entry.items) return null;

        const fetchedAt = Number(entry.fetchedAt);
        if (!Number.isFinite(fetchedAt) || now - fetchedAt > TE_MAX_AGE_MS) return null;

        const map = new Map();
        for (const [itemId, rows] of Object.entries(entry.items)) {
            if (!Array.isArray(rows)) continue;
            const traders = rows
                .filter((r) => Array.isArray(r) && r.length >= 3)
                .map(([name, id, price, score]) => ({
                    name: String(name),
                    id: String(id),
                    price: Number(price),
                    score: Number(score) || 0,
                }))
                .filter((t) => t.id && t.price > 0);
            if (traders.length) map.set(itemId, traders);
        }

        return { fetchedAt, map };
    }

    /** Per-item full buyer lists: {itemId: {at, traders: [[name, price], ...]}}. */
    function readTeItemLists(entry, now = Date.now()) {
        const out = new Map();
        if (!entry || typeof entry !== 'object') return out;
        for (const [itemId, rec] of Object.entries(entry)) {
            if (!rec || !Array.isArray(rec.traders)) continue;
            const at = Number(rec.at);
            if (!Number.isFinite(at) || now - at > TE_ITEM_TTL_MS) continue;
            out.set(itemId, {
                at,
                traders: rec.traders
                    .filter((r) => Array.isArray(r) && r.length >= 2)
                    .map(([name, price]) => ({ name: String(name), price: Number(price) }))
                    .filter((t) => t.name && t.price > 0),
            });
        }
        return out;
    }

    function writeTeItemList(entry, itemId, traders, now = Date.now(), max = 200) {
        const next = { ...(entry && typeof entry === 'object' ? entry : {}) };
        next[String(itemId)] = { at: now, traders: (traders || []).map((t) => [t.name, t.price]) };
        const keys = Object.keys(next);
        if (keys.length > max) {
            keys.sort((a, b) => Number(next[a].at) - Number(next[b].at));
            for (const k of keys.slice(0, keys.length - max)) delete next[k];
        }
        return next;
    }

    /* ===== src/core/inventory.js ===== */
    /*
     * Your inventory, from GET /v2/user/inventory (Limited key). Pure.
     *
     * Torn returns one entry per stack: the same item can appear several times
     * (different uids, an equipped copy, a faction-owned copy). The selling page
     * wants one line per item with the quantity you could actually hand over,
     * so stacks are merged by item id, and equipped and faction-owned copies are
     * left out: you cannot trade what you are wearing or what is the faction's.
     */

    const INVENTORY_CACHE_VERSION = 1;

    /** Torn caches the selection for an hour; re-asking sooner returns the same. */
    const INVENTORY_TTL_MS = 60 * 60 * 1000;

    /**
     * One response page -> plain rows. Bad rows are dropped, never guessed.
     * @returns {Array<{id: string, name: string, amount: number, equipped: boolean, factionOwned: boolean}>}
     */
    function parseInventoryPage(body) {
        const inv = body && body.inventory;
        const items = inv && Array.isArray(inv.items) ? inv.items : null;
        if (!items) throw new Error('Torn API returned no inventory.');

        const out = [];
        for (const raw of items) {
            if (!raw) continue;
            const id = Number(raw.id);
            const amount = Number(raw.amount);
            if (!Number.isFinite(id) || id <= 0) continue;
            if (!Number.isFinite(amount) || amount <= 0) continue;

            out.push({
                id: String(id),
                name: typeof raw.name === 'string' ? raw.name : '',
                amount: Math.floor(amount),
                equipped: Boolean(raw.equipped),
                factionOwned: Boolean(raw.faction_owned),
            });
        }
        return out;
    }

    /**
     * Merge stacks by item id; equipped and faction-owned copies are excluded.
     * @returns {Array<{id: string, name: string, qty: number}>} sorted by id
     */
    function mergeInventory(rows) {
        const byId = new Map();

        for (const r of rows || []) {
            if (!r || r.equipped || r.factionOwned) continue;
            if (!(r.amount > 0)) continue;

            const cur = byId.get(r.id);
            if (cur) {
                cur.qty += r.amount;
                if (!cur.name && r.name) cur.name = r.name;
            } else {
                byId.set(r.id, { id: r.id, name: r.name || '', qty: r.amount });
            }
        }

        return [...byId.values()].sort((a, b) => Number(a.id) - Number(b.id));
    }

    /** The `_metadata.links.next` offset, or null when this was the last page. */
    function nextInventoryOffset(body) {
        const next = body && body._metadata && body._metadata.links && body._metadata.links.next;
        if (!next) return null;
        try {
            const offset = Number(new URL(String(next), 'https://api.torn.com/').searchParams.get('offset'));
            return Number.isFinite(offset) && offset > 0 ? offset : null;
        } catch {
            return null;
        }
    }

    /** A failed inventory read is not asked again sooner than this. */
    const INVENTORY_RETRY_MS = 5 * 60 * 1000;

    /**
     * Whether the inventory should be read again now, on the timer: it is old,
     * the last failure's wait is over, and the key is not one Torn rejected
     * (that waits for a new key, not for time).
     */
    function inventoryRefreshDue({ inventoryAt, retryAt = 0, keyDead = false, now = Date.now(), refreshMs = INVENTORY_TTL_MS }) {
        if (keyDead) return false;
        if (now < (Number(retryAt) || 0)) return false;
        const at = Number(inventoryAt) || 0;
        return now - at >= refreshMs;
    }

    function makeInventoryCacheEntry(items, now = Date.now()) {
        return { version: INVENTORY_CACHE_VERSION, fetchedAt: now, items };
    }

    /** @returns {{fetchedAt: number, items: Array}|null} */
    function readInventoryCacheEntry(entry, now = Date.now(), ttl = INVENTORY_TTL_MS) {
        if (!entry || entry.version !== INVENTORY_CACHE_VERSION || !Array.isArray(entry.items)) return null;
        const at = Number(entry.fetchedAt);
        if (!Number.isFinite(at) || now - at > ttl) return null;
        return { fetchedAt: at, items: entry.items };
    }

    /* ===== src/core/history.js ===== */
    /*
     * Price history the script records itself. Pure - the caller stores it.
     *
     * No API gives an item's price history: Torn's market value is a single
     * daily average of sales, and TornW3B publishes only what is listed now. So
     * the only way to say "what did this go for over the past week" is to write
     * down what was asked, regularly, from now on. What is recorded:
     *
     *   im  - the lowest Item Market asking price (one Torn call per item)
     *   bz  - the lowest bazaar asking price (TornW3B's one-call summary)
     *   mv  - Torn's market value, once a day (the one sale-based number)
     *
     * Three resolutions, each a fixed window, so storage stays small:
     *
     *   5-minute buckets for the last 24 hours   (288 buckets)
     *   hourly buckets    for the last 7 days    (168)
     *   6-hourly buckets  for the last 30 days   (120)
     *
     * A bucket is [bucketNumber, im, bz] - the LAST sample in that bucket for
     * 5-minute buckets, the average of samples for the coarser ones ([n, im, bz,
     * count]). Only items the user has shown interest in (their own bazaar, their
     * inventory) are tracked, up to HISTORY_MAX_ITEMS, oldest interest dropped.
     *
     * An average is only as good as its coverage: every average carries the
     * share of its window that actually has data, and callers must show it.
     */

    const HISTORY_VERSION = 1;
    const HISTORY_MAX_ITEMS = 60;

    const RES = {
        m5: { ms: 5 * 60 * 1000, keep: 288 },
        h1: { ms: 60 * 60 * 1000, keep: 168 },
        h6: { ms: 6 * 60 * 60 * 1000, keep: 120 },
    };

    const DAY_MS = 24 * 60 * 60 * 1000;

    /** The windows the UI shows, with the resolution that spans each. */
    const WINDOWS = [
        { key: '1h', label: '1 hour', ms: 60 * 60 * 1000, res: 'm5' },
        { key: '6h', label: '6 hours', ms: 6 * 60 * 60 * 1000, res: 'm5' },
        { key: '24h', label: '24 hours', ms: DAY_MS, res: 'm5' },
        { key: '7d', label: '7 days', ms: 7 * DAY_MS, res: 'h1' },
        { key: '30d', label: '30 days', ms: 30 * DAY_MS, res: 'h6' },
    ];

    function emptyHistory() {
        return { version: HISTORY_VERSION, items: {} };
    }

    function readHistory(entry) {
        if (!entry || entry.version !== HISTORY_VERSION || !entry.items || typeof entry.items !== 'object') {
            return emptyHistory();
        }
        return entry;
    }

    function itemRec(store, itemId, now) {
        const id = String(itemId);
        if (!store.items[id]) store.items[id] = { m5: [], h1: [], h6: [], mv: [], seen: now };
        const rec = store.items[id];
        rec.seen = now;
        return rec;
    }

    function positive(v) {
        const n = Number(v);
        return Number.isFinite(n) && n > 0 ? Math.round(n) : null;
    }

    /**
     * Record one observation. Missing values (null) leave that column alone.
     * @param {object} sample - { im?: number, bz?: number }
     */
    function recordSample(store, itemId, now, sample) {
        const im = positive(sample && sample.im);
        const bz = positive(sample && sample.bz);
        if (im === null && bz === null) return store;

        const rec = itemRec(store, itemId, now);

        // 5-minute: the last sample wins.
        {
            const n = Math.floor(now / RES.m5.ms);
            const last = rec.m5[rec.m5.length - 1];
            if (last && last[0] === n) {
                if (im !== null) last[1] = im;
                if (bz !== null) last[2] = bz;
            } else {
                rec.m5.push([n, im, bz]);
            }
        }

        // Coarser: running averages per column, with separate counts.
        for (const key of ['h1', 'h6']) {
            const n = Math.floor(now / RES[key].ms);
            const arr = rec[key];
            let last = arr[arr.length - 1];
            if (!last || last[0] !== n) {
                last = [n, null, null, 0, 0];
                arr.push(last);
            }
            if (im !== null) {
                last[1] = last[3] ? Math.round((last[1] * last[3] + im) / (last[3] + 1)) : im;
                last[3] += 1;
            }
            if (bz !== null) {
                last[2] = last[4] ? Math.round((last[2] * last[4] + bz) / (last[4] + 1)) : bz;
                last[4] += 1;
            }
        }

        return store;
    }

    /** Torn's market value, once per day. */
    function recordMarketValue(store, itemId, now, value) {
        const v = positive(value);
        if (v === null) return store;
        const rec = itemRec(store, itemId, now);
        const day = Math.floor(now / DAY_MS);
        const last = rec.mv[rec.mv.length - 1];
        if (last && last[0] === day) last[1] = v;
        else rec.mv.push([day, v]);
        if (rec.mv.length > 31) rec.mv.splice(0, rec.mv.length - 31);
        return store;
    }

    /** Mark an item as one worth keeping (seen in your bazaar or inventory). */
    function touchItem(store, itemId, now) {
        itemRec(store, itemId, now);
        return store;
    }

    /** Drop buckets outside their window, and the least recently seen items over the cap. */
    function pruneHistory(store, now, maxItems = HISTORY_MAX_ITEMS) {
        for (const rec of Object.values(store.items)) {
            for (const key of Object.keys(RES)) {
                const oldest = Math.floor(now / RES[key].ms) - RES[key].keep + 1;
                rec[key] = (rec[key] || []).filter((b) => b[0] >= oldest);
            }
            const oldestDay = Math.floor(now / DAY_MS) - 30;
            rec.mv = (rec.mv || []).filter((b) => b[0] >= oldestDay);
        }

        const ids = Object.keys(store.items);
        if (ids.length > maxItems) {
            ids.sort((a, b) => (store.items[a].seen || 0) - (store.items[b].seen || 0));
            for (const id of ids.slice(0, ids.length - maxItems)) delete store.items[id];
        }
        return store;
    }

    /**
     * Averages for every window, each with its coverage.
     *
     * @returns {Object<string, {im: number|null, bz: number|null, coverage: number, buckets: number}>}
     *   coverage: buckets with any data / buckets in the window (0..1)
     */
    function averages(store, itemId, now) {
        const rec = store.items[String(itemId)];
        const out = {};

        for (const w of WINDOWS) {
            const res = RES[w.res];
            const total = Math.round(w.ms / res.ms);
            const oldest = Math.floor(now / res.ms) - total + 1;
            const buckets = rec ? (rec[w.res] || []).filter((b) => b[0] >= oldest) : [];

            let imSum = 0;
            let imN = 0;
            let bzSum = 0;
            let bzN = 0;
            let filled = 0;
            for (const b of buckets) {
                const im = b[1];
                const bz = b[2];
                if (im !== null || bz !== null) filled += 1;
                if (im !== null) {
                    imSum += im;
                    imN += 1;
                }
                if (bz !== null) {
                    bzSum += bz;
                    bzN += 1;
                }
            }

            out[w.key] = {
                im: imN ? Math.round(imSum / imN) : null,
                bz: bzN ? Math.round(bzSum / bzN) : null,
                coverage: total ? filled / total : 0,
                buckets: total,
            };
        }
        return out;
    }

    /**
     * Points for a graph over one window: [{t, im, bz}] oldest first, plus the
     * market value line as [{t, mv}].
     */
    function series(store, itemId, now, windowKey) {
        const w = WINDOWS.find((x) => x.key === windowKey) || WINDOWS[2];
        const res = RES[w.res];
        const total = Math.round(w.ms / res.ms);
        const oldest = Math.floor(now / res.ms) - total + 1;
        const rec = store.items[String(itemId)];

        const points = rec
            ? (rec[w.res] || [])
                  .filter((b) => b[0] >= oldest)
                  .map((b) => ({ t: b[0] * res.ms, im: b[1], bz: b[2] }))
            : [];

        const oldestDay = Math.floor((now - w.ms) / DAY_MS);
        const mv = rec ? (rec.mv || []).filter((b) => b[0] >= oldestDay).map((b) => ({ t: b[0] * DAY_MS, mv: b[1] })) : [];

        return { from: now - w.ms, to: now, points, mv, step: res.ms };
    }

    /**
     * Two copies of the history, one from storage and one from this tab, as
     * one. Every tab keeps its own copy and saves the whole thing, so without
     * this the selling tab's inventory items and the bazaar tab's samples
     * overwrite each other. Per item: buckets are the union by bucket number;
     * where both have a bucket, each column keeps the value backed by more
     * samples (coarse buckets) or the local one (5-minute buckets, where the
     * last sample wins and this tab's is the one it just took); `seen` is the
     * later. Neither input is changed.
     */
    function mergeHistory(stored, local) {
        const a = readHistory(stored);
        const b = readHistory(local);
        const out = emptyHistory();

        const ids = new Set([...Object.keys(a.items), ...Object.keys(b.items)]);
        for (const id of ids) {
            const ra = a.items[id];
            const rb = b.items[id];
            if (!ra || !rb) {
                out.items[id] = cloneRec(ra || rb);
                continue;
            }
            const rec = { m5: [], h1: [], h6: [], mv: [], seen: Math.max(Number(ra.seen) || 0, Number(rb.seen) || 0) };
            rec.m5 = mergeBuckets(ra.m5, rb.m5, mergeLast);
            rec.h1 = mergeBuckets(ra.h1, rb.h1, mergeAvg);
            rec.h6 = mergeBuckets(ra.h6, rb.h6, mergeAvg);
            rec.mv = mergeBuckets(ra.mv, rb.mv, (x, y) => [y[0], y[1]]);
            out.items[id] = rec;
        }
        return out;
    }

    function cloneRec(rec) {
        return {
            m5: (rec.m5 || []).map((b) => [...b]),
            h1: (rec.h1 || []).map((b) => [...b]),
            h6: (rec.h6 || []).map((b) => [...b]),
            mv: (rec.mv || []).map((b) => [...b]),
            seen: Number(rec.seen) || 0,
        };
    }

    /** Union by bucket number, ascending; `both(stored, local)` where both have one. */
    function mergeBuckets(stored, local, both) {
        const byN = new Map();
        for (const b of stored || []) if (Array.isArray(b)) byN.set(b[0], [...b]);
        for (const b of local || []) {
            if (!Array.isArray(b)) continue;
            const s = byN.get(b[0]);
            byN.set(b[0], s ? both(s, [...b]) : [...b]);
        }
        return [...byN.values()].sort((x, y) => x[0] - y[0]);
    }

    /** 5-minute bucket: a column this tab has wins; a column it lacks comes from storage. */
    function mergeLast(s, l) {
        const col = (i) => (l[i] !== null && l[i] !== undefined ? l[i] : s[i] ?? null);
        return [l[0], col(1), col(2)];
    }

    /** Averaged bucket: per column, the value backed by more samples (ties to this tab). */
    function mergeAvg(s, l) {
        const pick = (vi, ci) => {
            const sc = Number(s[ci]) || 0;
            const lc = Number(l[ci]) || 0;
            return lc >= sc ? [l[vi] ?? null, lc] : [s[vi] ?? null, sc];
        };
        const im = pick(1, 3);
        const bz = pick(2, 4);
        return [l[0], im[0], bz[0], im[1], bz[1]];
    }

    /** How much of the window has data, as words: "40% of 24h". */
    function coverageText(cov, windowKey) {
        const pct = Math.round((Number(cov) || 0) * 100);
        return pct + '% of ' + windowKey;
    }

    /* ===== src/api/torn.js ===== */
    /*
     * Thin wrappers over the Torn endpoints this tool uses. Every one of these
     * works with a Public access key, except fetchInventory: reading your own
     * inventory needs Limited access, and only the selling page calls it, with
     * the separate key that page keeps.
     */

    /** Torn's access levels, lowest first. Public is all the overlay needs. */
    const ACCESS_PUBLIC = 1;
    const ACCESS_LIMITED = 3;

    /** "Access level of this key is not high enough". */
    const TORN_ERROR_ACCESS_LEVEL = 16;

    const ACCESS_LEVEL_NAMES = {
        1: 'Public',
        2: 'Minimal',
        3: 'Limited',
        4: 'Full',
    };

    /**
     * The full item database. Public key.
     *
     * Read from v2 (`/v2/torn/items`), where an item no NPC will buy has
     * `value.sell_price: null` - the game's "Sell: N/A". That null is the whole
     * point: an item without an NPC sell price must never be priced as if an NPC
     * would pay for it. v1 (`torn?selections=items`) is the fallback if v2 fails.
     *
     * Returned in the v1 shape ({ "<id>": { name, sell_price, market_value } })
     * so buildItemIndex has one input format.
     */
    async function fetchItems(client) {
        try {
            return await fetchItemsV2(client);
        } catch (error) {
            // A dead key, a rate limit or an IP block fails v1 the same way; do
            // not ask twice. Anything else (a v2 shape change, an unknown
            // selection) falls back.
            const code = error && Number(error.code);
            if (KEY_DEAD_CODES.has(code) || code === TORN_ERROR_RATE_LIMIT || code === TORN_ERROR_IP_BLOCK) {
                throw error;
            }
        }

        const data = await client.get('torn', { selections: 'items' });

        if (!data || !data.items) {
            throw new Error('Torn API returned no item database.');
        }

        return data.items;
    }

    /**
     * What an NPC shop in Torn pays for an item, and which shop.
     *
     * Neither API field is trustworthy alone; each lies differently. Captured
     * live, 2026-09-24, against the game's own "Sell:" line:
     *
     *   item                sell_price  shops                                game
     *   Beretta M9          1300        [Torn  Big Al's       sell 1300]     $1,300
     *   Companion Script    12000000    []                                   N/A
     *   Stick of Dynamite   null        [China General Store  sell 37500]    N/A
     *   Pillow              150         [UAE sell 75, Torn Big Al's sell 150] $150
     *
     * Foreign shops' "sell" is a filler of 75% of their buy price (Dynamite
     * 50,000 -> 37,500; Printing Paper 75,000 -> 56,250) - and nobody can sell
     * abroad anyway: items are bought abroad and sold in Torn. So an item has
     * an NPC buyer only when BOTH hold:
     *
     *   - `sell_price` is a positive number (rules out Dynamite & co.), and
     *   - a shop in Torn lists a positive sell price (rules out the Companion
     *     Scripts and anything sold only abroad).
     *
     * The price is that Torn shop's (preferring the one matching `sell_price`).
     * A payload from before `shops` existed falls back to a vendor in Torn.
     *
     * @returns {{price: number|null, shop: string|null}}
     */
    function npcSaleFromValue(value) {
        const v = value || {};
        const none = { price: null, shop: null };
        const listed = Number(v.sell_price);

        if (!Number.isFinite(listed) || listed <= 0) return none;

        if (Array.isArray(v.shops)) {
            const torn = [];
            for (const s of v.shops) {
                const price = Number(s && s.sell_price);
                if (s && s.country === 'Torn' && Number.isFinite(price) && price > 0) {
                    torn.push({ price, shop: s.shop || null });
                }
            }
            if (!torn.length) return none;
            return torn.find((t) => t.price === listed) || torn.reduce((a, b) => (b.price > a.price ? b : a));
        }

        if (v.vendor && v.vendor.country === 'Torn') {
            return { price: listed, shop: v.vendor.name || null };
        }

        return none;
    }

    /** v2 item list -> v1-shaped map. Follows `_metadata.links.next` if paged. */
    async function fetchItemsV2(client) {
        const out = {};
        let params = { sort: 'ASC' };

        for (let page = 0; page < 20; page += 1) {
            const data = await client.get('v2/torn/items', params);

            if (!data || !Array.isArray(data.items)) {
                throw new Error('Torn API v2 returned no item list.');
            }

            for (const item of data.items) {
                if (!item || !Number.isFinite(Number(item.id))) continue;
                const value = item.value || {};
                const npc = npcSaleFromValue(value);

                out[String(item.id)] = {
                    name: item.name,
                    type: item.type || null,
                    // null = "Sell: N/A": no NPC shop buys it.
                    sell_price: npc.price,
                    npc_shop: npc.shop,
                    buy_price: value.buy_price ?? null,
                    market_value: value.market_price ?? 0,
                    circulation: item.circulation ?? 0,
                };
            }

            const next = data._metadata && data._metadata.links && data._metadata.links.next;
            if (!next) break;

            const nextUrl = new URL(next);
            params = Object.fromEntries(nextUrl.searchParams);
            delete params.key;
        }

        if (Object.keys(out).length === 0) {
            throw new Error('Torn API v2 returned an empty item list.');
        }

        return out;
    }

    /**
     * City shop inventories, used to build the NPC-sellable allowlist.
     *
     * The selection is `cityshops` and the response key is `cityshops`. An
     * earlier version of this file asked for `shops` and read `data.shops`, which
     * meant the call silently produced nothing, every item came back unverified,
     * and the panel reported "no opportunities" on a page full of them.
     *
     * `shops` is still accepted as a fallback in case the payload is ever served
     * under that key, but a response with neither throws rather than degrading
     * quietly.
     */
    async function fetchShops(client) {
        const data = await client.get('torn', { selections: 'cityshops' });

        const shops = data && (data.cityshops || data.shops);

        if (!shops) {
            throw new Error(
                'Torn API returned no city shop data (expected "cityshops").',
            );
        }

        return shops;
    }

    /**
     * What the current key can actually do.
     *
     * Used only to warn the user when they have pasted in a key with more access
     * than this tool needs. Written so that an unexpected payload shape means
     * "cannot tell" rather than a false alarm or a crash.
     *
     * @returns {{level: number|null, name: string|null}}
     */
    async function fetchKeyAccess(client) {
        try {
            const data = await client.get('key', { selections: 'info' });

            const level = Number(data && data.access_level);
            const name =
                (data && data.access_type) ||
                ACCESS_LEVEL_NAMES[level] ||
                null;

            return {
                level: Number.isFinite(level) ? level : null,
                name,
            };
        } catch {
            // The check is advisory. If it fails, say nothing rather than
            // blocking a key that is probably fine.
            return { level: null, name: null };
        }
    }

    /**
     * Item Market listings for one item: GET /v2/market/{id}/itemmarket.
     *
     * Public key. "Globally cached selection" - Torn serves everyone the same
     * snapshot and refreshes it no faster than `cache_delay` seconds (30 in every
     * observed response), so asking again before cache_timestamp + cache_delay
     * returns the same rows and only spends quota. The caller uses `nextAt` to
     * avoid that.
     *
     * The response names no seller and no listing id: a row is a price and an
     * amount. So an Item Market hit links to the item, never to a seller.
     *
     * @returns {Promise<{listings: Array<{price: number, amount: number}>,
     *   averagePrice: number|null, cacheTimestamp: number|null, nextAt: number,
     *   total: number}>} cacheTimestamp and nextAt in ms
     */
    async function fetchItemMarket(
        client,
        itemId,
        { limit = 20, offset = 0, now = Date.now() } = {},
    ) {
        const data = await client.get(
            'v2/market/' + encodeURIComponent(String(itemId)) + '/itemmarket',
            { limit, offset },
        );

        const market = (data && data.itemmarket) || {};
        const raw = Array.isArray(market.listings) ? market.listings : [];

        const cacheTs = Number(market.cache_timestamp);
        const cacheDelay = Number(market.cache_delay);
        const cacheTimestamp = Number.isFinite(cacheTs) && cacheTs > 0
            ? cacheTs * 1000
            : null;
        const delayMs = (Number.isFinite(cacheDelay) && cacheDelay > 0
            ? cacheDelay
            : 30) * 1000;

        const average = Number(market.item && market.item.average_price);

        return {
            listings: raw
                .map((l) => ({
                    price: Number(l && l.price) || 0,
                    amount: Number(l && (l.amount ?? l.quantity)) || 0,
                }))
                .filter((l) => l.price > 0 && l.amount > 0),
            averagePrice: Number.isFinite(average) && average > 0 ? average : null,
            cacheTimestamp,
            nextAt: (cacheTimestamp || now) + delayMs,
            total: Number(data && data._metadata && data._metadata.total) || raw.length,
        };
    }

    /**
     * A player's public presence: Online / Idle / Offline and where they are.
     * Accepts the v2 `/user/{id}/profile` shape ({ profile: {...} }) and the v1
     * `user/{id}?selections=profile` shape (fields at the top level).
     *
     * @returns {{name, online, lastActionAt, state, description}|null}
     */
    function parseUserPresence(data) {
        const p = (data && (data.profile || data)) || {};
        const la = p.last_action || {};
        const st = p.status || {};

        const online = ['Online', 'Idle', 'Offline'].includes(la.status) ? la.status : null;
        const seconds = Number(la.timestamp);

        if (!online && !st.state) return null;

        return {
            name: typeof p.name === 'string' ? p.name : null,
            online,
            lastActionAt: Number.isFinite(seconds) && seconds > 0 ? seconds * 1000 : null,
            state: typeof st.state === 'string' ? st.state : null,
            description: typeof st.description === 'string' ? st.description : null,
        };
    }

    /**
     * The public status of one player - the owner of the bazaar being viewed.
     * Public data (what their profile shows anyone); a Public key can read it.
     * Tries v2 first, then v1; a dead key or rate limit is not retried.
     */
    async function fetchUserPresence(client, userId) {
        const id = String(userId).replace(/\D/g, '');
        if (!id) return null;

        try {
            return parseUserPresence(await client.get('v2/user/' + id + '/profile'));
        } catch (error) {
            const code = error && error.code;
            if (
                code === TORN_ERROR_RATE_LIMIT ||
                code === TORN_ERROR_IP_BLOCK ||
                KEY_DEAD_CODES.has(code)
            ) {
                throw error;
            }
            return parseUserPresence(await client.get('user/' + id, { selections: 'profile' }));
        }
    }

    /** "Wrong fields" and "Incorrect category": a parameter Torn did not accept. */
    const TORN_ERROR_WRONG_FIELDS = 4;
    const TORN_ERROR_INCORRECT_CATEGORY = 21;

    /**
     * The `cat` values /v2/user/inventory accepts: TornInventoryItemType in
     * Torn's published OpenAPI spec (@types/torn-api, components/schemas).
     */
    const TORN_INVENTORY_CATEGORIES = [
        'Collectible', 'Clothing', 'Other', 'Tool', 'Melee', 'Defensive',
        'Material', 'Car', 'Primary', 'Secondary', 'Book', 'Special',
        'Supply Pack', 'Temporary', 'Enhancer', 'Artifact', 'Flower', 'Booster',
        'Medical', 'Candy', 'Jewelry', 'Alcohol', 'Plushie', 'Drug', 'Energy Drink',
    ];

    /** Torn refused the request for want of a (valid) `cat`. */
    function isCategoryError(error) {
        const code = Number(error && error.code);
        if (code === TORN_ERROR_INCORRECT_CATEGORY || code === TORN_ERROR_WRONG_FIELDS) return true;
        return /categor/i.test(String((error && error.message) || ''));
    }

    /** Every page of one inventory request (with or without a category). */
    async function fetchInventoryPages(client, params, limit) {
        const out = [];
        let offset = 0;

        for (let page = 0; page < 40; page += 1) {
            let data;
            try {
                data = await client.get('v2/user/inventory', { ...params, limit, offset });
            } catch (error) {
                if (error && Number(error.code) === TORN_ERROR_ACCESS_LEVEL) {
                    throw new TornApiError('This key cannot read your inventory: it needs Limited access.', {
                        code: TORN_ERROR_ACCESS_LEVEL,
                    });
                }
                throw error;
            }

            out.push(...parseInventoryPage(data));

            const next = nextInventoryOffset(data);
            if (next === null || next <= offset) break;
            offset = next;
        }

        return out;
    }

    /**
     * Your own inventory: GET /v2/user/inventory, paged with limit/offset.
     * Needs a LIMITED key; Torn caches it for about an hour per category.
     * Only the selling page calls this, with that page's own key. Error 16
     * (access level too low) is reported as such, never retried.
     *
     * The spec says `cat` is optional, but Torn has been seen to answer
     * "Incorrect category" without it. So: ask once without a category; if that
     * is refused as a category or field error, ask once per category instead
     * (25 calls, each paged, all through the shared limiter) and merge. A
     * category Torn no longer knows is skipped, never fatal.
     *
     * @returns {Promise<Array>} rows from parseInventoryPage, every page
     */
    async function fetchInventory(client, { limit = 250, categories = TORN_INVENTORY_CATEGORIES } = {}) {
        try {
            return await fetchInventoryPages(client, {}, limit);
        } catch (error) {
            if (!isCategoryError(error)) throw error;
        }

        const out = [];
        for (const cat of categories) {
            try {
                out.push(...(await fetchInventoryPages(client, { cat }, limit)));
            } catch (error) {
                if (!isCategoryError(error)) throw error;
            }
        }
        return out;
    }

    /* ===== src/sources/route.js ===== */
    /*
     * Which Torn page are we on? Pure string work, so it is testable.
     *
     * V1 ran both scanners on every page under `@match .../*`, which is why it
     * lit up on the Items page and in city shops. Here exactly one scanner runs,
     * and on an unrecognised page nothing runs at all.
     */

    const PAGE_BAZAAR = 'bazaar';
    const PAGE_ITEM_MARKET = 'itemmarket';
    const PAGE_NONE = null;

    /**
     * @param {string} href - normally location.href
     * @returns {'bazaar'|'itemmarket'|null}
     */
    function detectPage(href) {
        if (typeof href !== 'string' || !href) return PAGE_NONE;

        const url = href.toLowerCase();

        // Item Market 2.0 lives behind page.php?sid=ItemMarket; imarket.php is
        // the older path and still redirects for some users.
        if (url.includes('sid=itemmarket') || url.includes('/imarket.php')) {
            return PAGE_ITEM_MARKET;
        }

        // Own bazaar and other players' bazaars, new path and legacy query form.
        if (url.includes('/bazaar.php') || url.includes('page=bazaar')) {
            return PAGE_BAZAAR;
        }

        return PAGE_NONE;
    }

    /**
     * Deep link to an item's Item Market page.
     *
     * Used by the panel's navigate button. One click, one navigation - the script
     * never buys anything and never chains a second request off the same click.
     */
    function itemMarketUrl(itemId, itemName) {
        const params = new URLSearchParams({
            itemID: String(itemId),
            itemName: String(itemName || ''),
        });

        return (
            'https://www.torn.com/page.php?sid=ItemMarket#/market/view=search&' +
            params.toString()
        );
    }

    function queryOf(href) {
        try {
            return new URL(href).searchParams;
        } catch {
            return new URLSearchParams();
        }
    }

    /**
     * Whose bazaar is this? `bazaar.php?userId=123`. Null for your own bazaar
     * (no userId) or anything unparseable - a sighting with no seller is simply
     * remembered without one.
     */
    function bazaarOwnerId(href) {
        if (detectPage(href) !== PAGE_BAZAAR) return null;

        const id = queryOf(href).get('userId') || queryOf(href).get('userid');
        return id && /^\d+$/.test(id) ? id : null;
    }

    /**
     * The listing a feed link asked us to point at: `ttItem` / `ttPrice`, which
     * bazaarUrl() in core/feed.js writes. Highlighting it is reading and marking
     * the page the user opened, which is allowed; nothing is clicked or filled.
     */
    function bazaarTarget(href) {
        if (detectPage(href) !== PAGE_BAZAAR) return null;

        const q = queryOf(href);
        const itemId = q.get('ttItem');
        const price = Number(q.get('ttPrice'));

        if (!itemId || !/^\d+$/.test(itemId)) return null;

        return {
            itemId,
            price: Number.isFinite(price) && price > 0 ? price : null,
        };
    }

    /**
     * Your OWN bazaar's add-listings (#/add) and manage-listings (#/manage)
     * pages: bazaar.php with no userId, and that hash. Anything else - another
     * player's bazaar, your own storefront - is null. The hash changes without a
     * page load, so callers re-check on hashchange.
     *
     * @returns {'add'|'manage'|null}
     */
    function ownBazaarPage(href) {
        if (typeof href !== 'string' || !href) return null;
        if (detectPage(href) !== PAGE_BAZAAR) return null;
        if (bazaarOwnerId(href)) return null;

        const hash = (href.split('#')[1] || '').toLowerCase().replace(/^\/+/, '').split(/[?&]/)[0];
        if (hash === 'add' || hash.startsWith('add/')) return 'add';
        if (hash === 'manage' || hash.startsWith('manage/')) return 'manage';
        return null;
    }

    /*
     * The selling page (Traders) in its own tab: Torn's home page with a marker the script
     * recognises, and covers with the page. The page itself is one the user
     * opened; the script draws over it and reads only the API.
     */
    const TRADERS_PAGE_PARAM = 'ttv2';
    const TRADERS_PAGE_VALUE = 'traders';

    function tradersPageUrl() {
        return 'https://www.torn.com/index.php?' + TRADERS_PAGE_PARAM + '=' + TRADERS_PAGE_VALUE;
    }

    function isTradersPageUrl(href) {
        return queryOf(href).get(TRADERS_PAGE_PARAM) === TRADERS_PAGE_VALUE;
    }

    /* ===== src/sources/dom/detect.js ===== */
    /*
     * Finding the listing cards on the page.
     *
     * This is the part that has to work, so it uses two strategies and prefers
     * whichever actually finds cards:
     *
     *   1. Image-anchored. Every listing carries an item image whose path holds
     *      the item id (/images/items/206/large.png). Starting there and climbing
     *      to the card is cheap and precise.
     *
     *   2. Content-shaped. Walk the document for elements whose text contains a
     *      price AND "in stock", that are visible and card-sized, then climb to
     *      the smallest ancestor that looks like a whole card (price + stock +
     *      image + plausible dimensions).
     *
     * Strategy 2 is deliberately the same approach as the script that is known to
     * work on live Torn pages. It is slower, so it runs only when strategy 1
     * finds nothing - which keeps the fast path fast without betting the whole
     * feature on it.
     */

    const ITEM_IMAGE_SELECTOR =
        'img[src*="/images/items/"], img[srcset*="/images/items/"]';

    const ITEM_IMAGE_ID_RE = /\/images\/items\/(\d+)\//;

    /** Known card containers, tightest first. */
    const CARD_SELECTOR = [
        '[class*="itemTile"]',
        '[data-testid="item-description"]',
        '[class*="itemDescription"]',
        '[class*="sellerRow"]',
        '[class*="listItem"]',
    ].join(', ');

    const PRICE_RE = /\$\s*[\d,]+/;
    const STOCK_RE = /in\s+stock|in\s+total/i;

    const MAX_CLIMB = 8;

    /** The item id from an image path, or null if it is not an item image. */
    function itemIdFromImage(img) {
        if (!img || typeof img.getAttribute !== 'function') return null;

        const src = img.getAttribute('src') || img.getAttribute('srcset') || '';
        const match = src.match(ITEM_IMAGE_ID_RE);

        return match ? match[1] : null;
    }

    function isVisible(el) {
        if (!el || typeof window === 'undefined') return true;

        const style = window.getComputedStyle(el);
        if (style.display === 'none' || style.visibility === 'hidden') return false;

        const rect = el.getBoundingClientRect();
        return rect.width > 0 && rect.height > 0;
    }

    function boxOf(el) {
        if (!el || typeof el.getBoundingClientRect !== 'function') {
            return { width: 0, height: 0 };
        }
        return el.getBoundingClientRect();
    }

    function countItemImages(el) {
        try {
            return el.querySelectorAll(ITEM_IMAGE_SELECTOR).length;
        } catch {
            return 0;
        }
    }

    /**
     * Climb from an item image to the element representing ONE listing.
     *
     * The guard that matters: the moment an ancestor contains more than one item
     * image we have climbed into a container holding several listings and must
     * stop. Without it, one card's name gets paired with another card's price -
     * which is the oldest bug in this project.
     */
    function cardFromImage(img) {
        const preferred = img.closest ? img.closest(CARD_SELECTOR) : null;
        if (preferred && countItemImages(preferred) === 1) return preferred;

        let node = img.parentElement;
        let best = null;

        for (let depth = 0; depth < MAX_CLIMB && node; depth += 1) {
            if (countItemImages(node) > 1) break;

            best = node;

            const text = node.textContent || '';
            if (node.querySelector('[aria-label^="Buy"]') || PRICE_RE.test(text)) {
                return node;
            }

            node = node.parentElement;
        }

        return best;
    }

    /** Climb from a price-bearing element to something card-shaped. */
    function cardFromContent(el) {
        let node = el;

        for (let depth = 0; depth < MAX_CLIMB && node; depth += 1) {
            const text = node.textContent || '';
            const box = boxOf(node);

            if (
                PRICE_RE.test(text) &&
                STOCK_RE.test(text) &&
                node.querySelector('img') &&
                box.width >= 150 &&
                box.width <= 600 &&
                box.height >= 60 &&
                box.height <= 400
            ) {
                return node;
            }

            node = node.parentElement;
        }

        return null;
    }

    function dedupe(cards) {
        const seen = new Set();
        const out = [];

        for (const card of cards) {
            if (!card || seen.has(card)) continue;
            seen.add(card);
            out.push(card);
        }

        return out;
    }

    /** Strategy 1: anchored on item images. */
    function findByImage(root) {
        let images;
        try {
            images = Array.from(root.querySelectorAll(ITEM_IMAGE_SELECTOR));
        } catch {
            return { cards: [], images: 0 };
        }

        const cards = dedupe(images.map(cardFromImage).filter(Boolean));

        return { cards, images: images.length };
    }

    /** Strategy 2: shaped like a listing card. */
    function findByContent(root) {
        const candidates = [];

        let all;
        try {
            all = root.querySelectorAll('body *');
        } catch {
            return [];
        }

        for (const el of all) {
            const text = el.textContent || '';

            if (!text || text.length > 500) continue;
            if (!PRICE_RE.test(text)) continue;
            if (!STOCK_RE.test(text)) continue;
            if (!isVisible(el)) continue;

            const box = boxOf(el);
            if (box.width < 120 || box.height < 60) continue;

            candidates.push(el);
        }

        return dedupe(candidates.map(cardFromContent).filter(Boolean));
    }

    /**
     * Find every listing card on the page.
     *
     * @returns {{cards: Element[], strategy: string, images: number}}
     */
    function findCards(root) {
        if (!root) return { cards: [], strategy: 'none', images: 0 };

        const byImage = findByImage(root);
        if (byImage.cards.length > 0) {
            return {
                cards: byImage.cards,
                strategy: 'image',
                images: byImage.images,
            };
        }

        const byContent = findByContent(root);

        return {
            cards: byContent,
            strategy: byContent.length > 0 ? 'content' : 'none',
            images: byImage.images,
        };
    }

    /* ===== src/sources/dom/scan.js ===== */
    /*
     * Reading one listing card into numbers.
     *
     * Extraction order, most reliable first:
     *
     *   1. Torn's own buy-control ARIA label, which states everything outright:
     *        "Buy item Hammer, $100, 1 in total."
     *   2. The item image path, which carries the item id: /images/items/1/
     *   3. Text parsing, as a fallback: the first price, and "( N in stock)".
     *
     * Steps 1 and 2 were read off live Torn markup, so where they apply there is
     * no guessing at all. Step 3 exists because a layout that lacks both still
     * needs to work, and it is the approach already proven on live pages.
     */





    /** "Buy item Hammer, $100, 1 in total." */
    const BUY_LABEL_FULL_RE =
        /^buy item\s+(.+?),\s*\$([\d,]+(?:\.\d+)?),\s*([\d,]+)\s*in total/i;

    /** "Buy: Xanax" */
    const BUY_LABEL_NAME_RE = /^buy(?:\s+item)?:?\s+(.+?)\.?$/i;

    const BUY_CONTROL_SELECTOR =
        '[aria-label^="Buy item"], [aria-label^="Buy:"]';

    /** "( 5,931 in stock)" - a market-wide total, NOT stock at this price. */
    const IN_STOCK_RE = /\(?\s*([\d,]+)\s*in\s+stock/i;

    /** "1,805 available" - one seller's stock, which IS at this price. */
    const AVAILABLE_RE = /([\d,]+)\s*available/i;

    /** Every money figure in a block of text, in order. */
    const ALL_PRICES_RE = /\$\s*[\d,]+(?:\.\d+)?/g;

    /** Name cells, when the image alt is missing. */
    const NAME_SELECTOR = '[class*="name___"], [class*="itemName"], .name';

    /**
     * Parse Torn's buy-control ARIA label.
     * @returns {{name: string, price: number|null, qty: number|null}|null}
     */
    function parseBuyLabel(label) {
        if (typeof label !== 'string' || !label.trim()) return null;

        const text = label.trim();

        const full = text.match(BUY_LABEL_FULL_RE);
        if (full) {
            const price = parseMoney(full[2]);
            const qty = parseQuantity(full[3]);

            return {
                name: full[1].trim(),
                price: Number.isFinite(price) && price > 0 ? price : null,
                qty: Number.isFinite(qty) && qty > 0 ? qty : null,
            };
        }

        const bare = text.match(BUY_LABEL_NAME_RE);
        if (bare) return { name: bare[1].trim(), price: null, qty: null };

        return null;
    }

    /**
     * An element's OWN text: its direct text nodes, joined - never its
     * children's. This is a stricter form of "read leaves".
     *
     * A leaf-element rule misses a price that shares its element with a badge:
     * <p>$838,745<span>1%</span></p> has a child, so it is not a leaf, and its
     * full text "$838,7451%" reads as $8,387,451. Own text is "$838,745". It
     * also rejoins what React splits: {'$'}{price} renders two text nodes.
     */
    function ownText(node) {
        let out = '';
        for (const child of node.childNodes || []) {
            if (child.nodeType === 3) out += child.nodeValue;
        }
        return out.replace(/\s+/g, ' ').trim();
    }

    function textOf(node) {
        if (!node) return '';
        return (node.textContent || '').trim();
    }

    /** The item name Torn shows on this card. */
    function nameFromCard(card) {
        const img = card.querySelector('img[alt]');
        const alt = img ? (img.getAttribute('alt') || '').trim() : '';
        if (alt) return alt;

        const named = card.querySelector(NAME_SELECTOR);
        const text = textOf(named);

        return text && text.length < 80 ? text : '';
    }

    /** Catalogue lookup: by id where possible, by name only as a fallback. */
    function resolveItem(card, index, buy) {
        const img = card.querySelector(ITEM_IMAGE_SELECTOR);
        const id = itemIdFromImage(img);

        if (id) {
            const byId = findItemById(index, id);
            if (byId) return byId;
        }

        const name = (buy && buy.name) || nameFromCard(card);
        return findItemByName(index, name);
    }

    /*
     * A bazaar item the viewer cannot buy: Torn's $1 "Dollar Sale" lock. A $1
     * listing is open only to a random few percent of players (by ID); for
     * everyone else the card shows a red padlock, rendered as an element whose
     * class starts with isBlockedForBuying___. There is no seller-set lock, and
     * neither the Torn API nor TornW3B carries a lock flag - the page is the only
     * source, so the page is what is checked. Same selector TornTools uses for
     * its identical "cheaper than the NPC" highlight.
     *
     * Never inferred from a missing price: a card can lack a readable price for
     * other reasons, and that is reported as noPrice, not as locked.
     */
    const LOCKED_SELECTOR = '[class*="isBlockedForBuying"]';

    /** Is this card (or the bazaar item tile around it) locked for the viewer? */
    function isLockedCard(card) {
        if (!card || typeof card.querySelector !== 'function') return false;
        if (card.matches && card.matches(LOCKED_SELECTOR)) return true;
        if (card.querySelector(LOCKED_SELECTOR)) return true;

        // The card found may be the description inside a bazaar tile, with the
        // padlock drawn elsewhere in the tile.
        const tile = card.closest && card.closest('[class*="item___"]');
        return Boolean(tile && tile !== card && tile.querySelector(LOCKED_SELECTOR));
    }

    /**
     * Read one card.
     * @returns {object|null}
     */
    function readCard(card, index, pageType) {
        // Locked first: never priced, never highlighted, whatever price it shows.
        if (isLockedCard(card)) return { skipped: 'locked' };

        const buyNode = card.querySelector(BUY_CONTROL_SELECTOR);
        const buy = buyNode
            ? parseBuyLabel(buyNode.getAttribute('aria-label'))
            : null;

        const item = resolveItem(card, index, buy);
        if (!item) return { skipped: 'noItem' };

        let marketTotal = null;

        const text = card.textContent || '';

        /*
         * Read LEAF elements, never the row's concatenated text.
         *
         * React emits no whitespace between sibling nodes, so a seller row's
         * textContent is "BCS605$6,9727 availableBUY". The price then parses as
         * $69,727 instead of $6,972 - wildly above any exit price, so the row is
         * judged unprofitable and never highlights, from a number that was never
         * on screen. Each leaf holds exactly one value, so reading leaves removes
         * the ambiguity instead of guessing at it.
         */
        const leaves = [];
        for (const node of card.querySelectorAll('*')) {
            const t = ownText(node);
            if (t) leaves.push(t);
        }

        const priceLeaf = leaves.find((t) => /^\$\s*[\d,]+(?:\.\d+)?$/.test(t));
        const qtyLeaf = leaves.find((t) => /^[\d,]+\s*available$/i.test(t));

        let price = buy && buy.price;
        let priceAssumed = false;

        if (!Number.isFinite(price) || price <= 0) {
            if (priceLeaf) {
                // A leaf that is nothing but a price is unambiguous.
                price = parseMoney(priceLeaf);
                priceAssumed = false;
            } else {
                /*
                 * No dedicated price cell. Reading from text is only a guess when
                 * there is more than one money figure to choose between; with
                 * exactly one, it is the price.
                 */
                const found = text.match(ALL_PRICES_RE) || [];

                price = found.length > 0 ? parseMoney(found[0]) : null;
                priceAssumed = found.length > 1;
            }
        }

        if (!Number.isFinite(price) || price <= 0) return { skipped: 'noPrice' };

        /*
         * Quantity, and crucially WHETHER IT IS AVAILABLE AT THIS PRICE.
         *
         * A category tile reports the market-wide total across every seller
         * ("694,057 in total", "5,931 in stock") while showing only the CHEAPEST
         * price. Multiplying the two is nonsense: of 694,057 Gasoline, only 1,805
         * are at $424 - the next seller wants $520. Doing that produced a
         * confident "+$3.58m" for a trade that does not exist.
         *
         * A seller row ("1,805 available") is the one case where the quantity
         * really is available at the stated price.
         */
        let qty = null;
        let qtyAtPrice = false;
        let qtyAssumed = false;

        if (qtyLeaf) {
            qty = parseQuantity(qtyLeaf);
            qtyAtPrice = Number.isFinite(qty) && qty > 0;
        } else {
            const available = text.match(AVAILABLE_RE);
            if (available) {
                qty = parseQuantity(available[1]);
                qtyAtPrice = Number.isFinite(qty) && qty > 0;
            }
        }

        /*
         * On a BAZAAR, "(390 in stock)" is this one seller's stock, all at the
         * one price shown - a bazaar has a single price per item. Only on the
         * Item Market's category tiles is "in stock" a market-wide total. Reading
         * it as a total everywhere left every bazaar row "qty unknown".
         */
        if (!qtyAtPrice && pageType === 'bazaar' && !(buy && buy.qty)) {
            const inStock = leaves
                .map((t) => t.match(IN_STOCK_RE))
                .find(Boolean) || text.match(IN_STOCK_RE);

            if (inStock) {
                qty = parseQuantity(inStock[1]);
                qtyAtPrice = Number.isFinite(qty) && qty > 0;
            }
        }

        if (!qtyAtPrice) {
            // Market-wide totals are context, never a multiplier.
            const total = buy && buy.qty ? buy.qty : null;
            const inStock = text.match(IN_STOCK_RE);

            marketTotal =
                total || (inStock ? parseQuantity(inStock[1]) : null) || null;

            qty = 1;
            qtyAssumed = true;
        }

        return {
            el: card,
            buyEl: buyNode || null,
            itemId: item.id,
            name: item.name,
            item,
            listingPrice: price,
            priceAssumed,
            qty,
            qtyAtPrice,
            qtyAssumed,
            marketTotal,
            source: pageType,
        };
    }

    /**
     * Read every listing on the current page.
     *
     * @param {string} pageType - from detectPage()
     * @param {Document|Element} root
     * @param {object} ctx
     * @param {object} ctx.index - item index from buildItemIndex()
     * @returns {{listings: Array, diagnostics: object}}
     */
    function scanDom(pageType, root, { index } = {}) {
        const diagnostics = {
            pageType,
            strategy: 'none',
            images: 0,
            cards: 0,
            fromAria: 0,
            noItem: 0,
            noPrice: 0,
            locked: 0,
            priceAssumed: 0,
            qtyAssumed: 0,
            listings: 0,
        };

        if (!root || !index) return { listings: [], diagnostics };

        const found = findCards(root);

        diagnostics.strategy = found.strategy;
        diagnostics.images = found.images;
        diagnostics.cards = found.cards.length;

        const listings = [];

        for (const card of found.cards) {
            const result = readCard(card, index, pageType);

            if (!result || result.skipped) {
                if (result && result.skipped === 'noItem') diagnostics.noItem += 1;
                if (result && result.skipped === 'noPrice') diagnostics.noPrice += 1;
                if (result && result.skipped === 'locked') diagnostics.locked += 1;
                continue;
            }

            if (!result.priceAssumed && !result.qtyAssumed) {
                diagnostics.fromAria += 1;
            }
            if (result.priceAssumed) diagnostics.priceAssumed += 1;
            if (result.qtyAssumed) diagnostics.qtyAssumed += 1;

            listings.push(result);
        }

        diagnostics.listings = listings.length;

        return { listings, diagnostics };
    }

    /* ===== src/sources/dom/ownbazaar.js ===== */
    /*
     * Reading the rows of YOUR OWN bazaar's add-listings and manage-listings
     * pages. Selectors come from a working 2026 price-filler script for these
     * pages (the real markup has not been captured here, so the Tampermonkey
     * menu has a diagnostics readout saying what was found):
     *
     *   #/add     ul.items-cont li.clearfix, name in div.title-wrap div.name-wrap
     *   #/manage  div[data-testid="sortable-item"] or div[class*="row___"]
     *             (a virtualised list: rows mount and unmount as you scroll)
     *
     * The item id comes from the item image path (/images/items/{id}/), as the
     * market scanner does. Only the page you are viewing is read; nothing is
     * clicked, filled in or listed for you.
     */




    const OWN_BAZAAR_ROW_SELECTORS = {
        add: 'ul.items-cont li.clearfix',
        manage: 'div[data-testid="sortable-item"], div[class*="row___"]',
    };

    const OWN_BAZAAR_NAME_SELECTORS = {
        add: 'div.title-wrap div.name-wrap',
        manage: 'div[class*="item___"] div[class*="desc___"], div[class*="name___"], div[class*="title___"]',
    };

    /** Where the price tag goes in a row: after the name. */
    const OWN_BAZAAR_TAG_CLASS = 'ttv2-bztag';

    function cleanText(node) {
        return ((node && node.textContent) || '').replace(/\s+/g, ' ').trim();
    }

    /**
     * Read every row on the page.
     *
     * @param {'add'|'manage'} which
     * @param {Document|Element} root
     * @param {object} index - item index
     * @returns {{rows: Array<{el, nameEl, itemId, name, item}>, diagnostics: object}}
     */
    function scanOwnBazaar(which, root, index) {
        const diagnostics = { page: which, rows: 0, withImage: 0, identified: 0, noItem: 0 };
        const rows = [];
        if (!root || !index || !OWN_BAZAAR_ROW_SELECTORS[which]) return { rows, diagnostics };

        const seen = new Set();
        for (const el of root.querySelectorAll(OWN_BAZAAR_ROW_SELECTORS[which])) {
            // The manage selectors can both match the same row.
            if (seen.has(el) || (el.closest && el.closest('#ttv2-host'))) continue;
            seen.add(el);
            diagnostics.rows += 1;

            const img = el.querySelector(ITEM_IMAGE_SELECTOR) || el.querySelector('img');
            const id = img ? itemIdFromImage(img) : null;
            if (id) diagnostics.withImage += 1;

            const nameEl = el.querySelector(OWN_BAZAAR_NAME_SELECTORS[which]);
            const nameText = cleanText(nameEl).replace(/\s*(x|×)\s*\d[\d,]*\s*$/i, '');
            const alt = img ? (img.getAttribute('alt') || '').trim() : '';

            const item =
                (id && findItemById(index, id)) ||
                findItemByName(index, nameText) ||
                findItemByName(index, alt) ||
                null;

            if (!item) {
                diagnostics.noItem += 1;
                continue;
            }

            diagnostics.identified += 1;
            rows.push({ el, nameEl: nameEl || el, itemId: item.id, name: item.name, item });
        }

        return { rows, diagnostics };
    }

    /**
     * The tag element in a row, created if missing. Text is set by the caller.
     * Paint-only: a span AFTER the name element (never inside it, so the name
     * still reads as the name on the next scan); never a form field, never a
     * click on Torn's controls. The row's item id is kept on the tag, so a
     * click reads the item of the row as it is NOW: #/manage is a virtualised
     * list whose row elements are reused for other items as you scroll.
     */
    function ensureRowTag(row, doc = document) {
        let tag = row.el.querySelector('.' + OWN_BAZAAR_TAG_CLASS);
        if (!tag) {
            tag = doc.createElement('span');
            tag.className = OWN_BAZAAR_TAG_CLASS;
            const nameEl = row.nameEl && row.nameEl !== row.el ? row.nameEl : null;
            if (nameEl && nameEl.parentNode) nameEl.parentNode.insertBefore(tag, nameEl.nextSibling);
            else row.el.appendChild(tag);
        }
        if (tag.dataset.itemId !== String(row.itemId)) tag.dataset.itemId = String(row.itemId);
        return tag;
    }

    function removeRowTags(root = document) {
        for (const t of root.querySelectorAll('.' + OWN_BAZAAR_TAG_CLASS)) t.remove();
    }

    /* ===== src/sources/dom/owner.js ===== */
    /*
     * The bazaar owner banner, captured live 2026-09-24:
     *
     *   <div class="msg right-round messageContent___cdSrs">
     *     <a href="profiles.php?XID=4254715">DixieNormousss's</a> bazaar,
     *     favorited by <b>3</b> citizens, is currently <span class="bold">open.</span>
     *   </div>
     *
     * The same profile link also sits in a (usually hidden) dropdown menu, in a
     * listItem___ wrapper - that one is skipped.
     *
     * Paint-only: a badge is added after the name. Nothing is clicked or read
     * beyond this banner.
     */

    const OWNER_BADGE_CLASS = 'ttv2-owner';

    /** The owner's name link inside the banner, or null. */
    function findOwnerLink(root, ownerId) {
        const id = String(ownerId || '').replace(/\D/g, '');
        if (!id || !root) return null;

        const links = root.querySelectorAll('a[href*="XID=' + id + '"]');
        for (const a of links) {
            const href = a.getAttribute('href') || '';
            // XID=42 must not match XID=4254715.
            if (!new RegExp('XID=' + id + '(?!\\d)').test(href)) continue;
            if (a.closest('[class*="listItem"]')) continue;
            if (a.closest('[class*="messageContent"], .msg')) return a;
        }
        return null;
    }

    /** true = open, false = closed, null = the banner does not say. */
    function readBazaarOpen(root, ownerId) {
        const link = findOwnerLink(root, ownerId);
        if (!link) return null;

        const banner = link.closest('[class*="messageContent"], .msg');
        const text = ((banner && banner.textContent) || '').replace(/\s+/g, ' ');

        if (/currently\s+closed/i.test(text)) return false;
        if (/currently\s+open/i.test(text)) return true;
        return null;
    }

    /** "just now", "4m ago", "3h ago", "2d ago". */
    function agoText(ms, now = Date.now()) {
        if (!Number.isFinite(ms)) return '';
        const s = Math.max(0, Math.round((now - ms) / 1000));
        if (s < 60) return 'just now';
        if (s < 3600) return Math.floor(s / 60) + 'm ago';
        if (s < 86400) return Math.floor(s / 3600) + 'h ago';
        return Math.floor(s / 86400) + 'd ago';
    }

    /**
     * The badge's words, shared with the panel line.
     * @returns {{level: 'online'|'idle'|'offline'|'unknown', text: string}}
     */
    function presenceText(presence, now = Date.now()) {
        if (!presence || !presence.online) return { level: 'unknown', text: 'status unknown' };

        const level = presence.online.toLowerCase();
        const parts = [presence.online];

        if (presence.online !== 'Online' && presence.lastActionAt) {
            parts.push(agoText(presence.lastActionAt, now));
        }

        // Anything but "Okay" matters: travelling, abroad, hospital, jail.
        if (presence.state && presence.state !== 'Okay') {
            parts.push(presence.description || presence.state);
        }

        return { level, text: parts.join(' · ') };
    }

    /**
     * The short form for a deal row, where space is tight: "Offline 3h ago",
     * "Online · Hospital". The full presenceText() goes in the tooltip.
     * @returns {{level: string, text: string, title: string}}
     */
    function presenceShort(presence, now = Date.now()) {
        const full = presenceText(presence, now);
        if (full.level === 'unknown') return { ...full, title: full.text };

        let text = presence.online;
        if (presence.online !== 'Online' && presence.lastActionAt) {
            text += ' ' + agoText(presence.lastActionAt, now);
        }
        if (presence.state && presence.state !== 'Okay') text += ' · ' + presence.state;

        return { level: full.level, text, title: full.text };
    }

    /**
     * One word for a row: "Online", "Idle", "Offline 3h", or the state when it
     * is not Okay ("Traveling", "Hospital"). The full presenceText() goes in the
     * tooltip. Rows have no room for more, and a word with a dot reads faster.
     * @returns {{level: string, text: string, title: string}}
     */
    function presenceWord(presence, now = Date.now()) {
        const full = presenceText(presence, now);
        if (full.level === 'unknown') return { level: 'unknown', text: 'Unknown', title: full.text };

        let text = presence.online;
        if (presence.state && presence.state !== 'Okay') {
            text = presence.state;
        } else if (presence.online !== 'Online' && presence.lastActionAt) {
            text += ' ' + agoText(presence.lastActionAt, now).replace(' ago', '').replace('just now', 'now');
        }
        return { level: full.level, text, title: full.text };
    }

    /** Put (or refresh) the badge after the owner's name. Returns true if shown. */
    function renderOwnerBadge(root, ownerId, presence, now = Date.now()) {
        const link = findOwnerLink(root, ownerId);
        if (!link) return false;

        let badge = link.nextElementSibling;
        if (!badge || !badge.classList.contains(OWNER_BADGE_CLASS)) {
            badge = link.ownerDocument.createElement('span');
            badge.className = OWNER_BADGE_CLASS;
            link.insertAdjacentElement('afterend', badge);
        }

        const { level, text } = presenceText(presence, now);
        if (badge.dataset.level !== level) badge.dataset.level = level;
        if (badge.textContent !== text) badge.textContent = text;
        badge.title = 'Bazaar owner status (Torn API)';
        return true;
    }

    function removeOwnerBadges(root) {
        for (const b of root.querySelectorAll('.' + OWNER_BADGE_CLASS)) b.remove();
    }

    /* ===== src/ui/styles.js ===== */
    /*
     * All CSS for the script, in one place.
     *
     * The row marker is the important part. It is a pure `box-shadow: inset`,
     * which paints INSIDE the row's existing box: it adds no element, occupies no
     * space, and shifts nothing. That is what stops it covering the Buy button,
     * which is what V1's absolutely-positioned badge did.
     *
     * `!important` appears only on the marker's own box-shadow and tint, because
     * Torn's row styles set box-shadow themselves. It is deliberately not used on
     * `outline`, and the marker never touches `position`.
     *
     * Design rules the panel and the selling page share (see README):
     *   font Arial; sizes 11px (uppercase labels only), 12px (secondary), 13px
     *   (body), 15px bold (the key money number); line-height 1.4; spacing in
     *   4/8/12/16px; money right-aligned in tabular figures; colours only from
     *   the tokens below; a Torn-style striped title bar.
     */

    const UI_PREFIX = 'ttv2';

    /*
     * Colour tokens, shared by the panel and the selling page. Torn's own panel
     * colour is used for the background where Torn defines it (dark mode);
     * everything else is fixed so the text stays readable on it.
     */
    const TOKENS_CSS = `
        --bg: var(--default-bg-panel-color, #2e2e2e);
        --row: #2b2b2b;
        --line: #444;
        --text: #ddd;
        --muted: #999;
        --profit: #99cc00;
        --offer: #74c0fc;
        --warn: #e0a000;
        --bad: #d83500;
        --on-profit: #1b1b1b;
        --title: repeating-linear-gradient(90deg, #242424 0 2px, #2e2e2e 0 4px);
    `;

    /*
     * Two stylesheets, deliberately apart.
     *
     * PAGE_CSS marks Torn's own item cards, so it must live in the page.
     * PANEL_CSS styles the panel, which lives in a shadow root: Torn's page CSS
     * cannot reach in (it had been restyling our headings to giant type), and
     * ours cannot leak out.
     */
    const PAGE_CSS = `
    .ttv2-hit {
        position: relative !important;

        box-shadow:
            inset 0 0 0 3px #35d35a,
            inset 0 0 0 9999px rgba(53, 211, 90, 0.16) !important;

        transition: box-shadow 0.15s ease;
    }

    /*
     * The profit label, drawn as a pseudo-element from a data attribute.
     *
     * pointer-events: none is the important line: it means this can never
     * intercept a click, so it cannot block Torn's Buy button no matter where it
     * lands. That was the original complaint about V1, and it is fixed by making
     * the label unclickable rather than by removing it.
     */
    .ttv2-hit.ttv2-hit::after {
        /*
         * Every declaration here is load-bearing, and all of it was worked out
         * against a live Torn page rather than guessed.
         *
         * - The doubled class and !important on 'content': Torn defines ::after
         *   on its own item tiles at equal specificity and wins on document
         *   order, so the plain rule computed to content: "" and the label
         *   silently never appeared.
         * - The width/height/inset resets: overriding 'content' alone leaves
         *   Torn's geometry in place, which clipped the label to an 8px sliver.
         * - The chip background: white text alone was invisible against the
         *   tile's artwork.
         */
        content: attr(data-ttv2-profit) !important;

        display: block !important;
        position: absolute !important;
        top: 0 !important;
        right: 0 !important;
        left: auto !important;
        bottom: auto !important;

        width: auto !important;
        height: auto !important;
        min-width: 0 !important;
        max-width: 100% !important;
        margin: 0 !important;
        padding: 1px 4px !important;
        transform: none !important;

        overflow: visible !important;
        white-space: nowrap !important;
        opacity: 1 !important;
        visibility: visible !important;
        z-index: 2147483000 !important;

        background: rgba(10, 40, 16, 0.92) !important;
        border: 1px solid #35d35a !important;
        border-radius: 0 0 0 5px !important;

        color: #7ee08f !important;
        font: 800 11px/14px Arial, Helvetica, sans-serif !important;

        /* Cannot intercept a click, so it can never block Torn's Buy button. */
        pointer-events: none !important;
    }

    /* The listing a feed link was opened for. Paint-only, like .ttv2-hit. */
    .ttv2-target {
        box-shadow:
            inset 0 0 0 3px #ffd24a,
            inset 0 0 0 9999px rgba(255, 210, 74, 0.14) !important;
    }

    .ttv2-hit-top {
        box-shadow:
            inset 0 0 0 3px #7ee08f,
            inset 0 0 0 9999px rgba(126, 224, 143, 0.24) !important;
    }

    /* Bazaar owner status, right after their name in the page banner. */
    .ttv2-owner {
        display: inline-block;
        margin: 0 4px 0 8px;
        padding: 0 8px;
        border-radius: 9px;
        font: bold 12px/18px Arial, Helvetica, sans-serif;
        color: #ddd;
        background: rgba(0, 0, 0, 0.35);
        white-space: nowrap;
        vertical-align: middle;
    }

    .ttv2-owner::before {
        content: "";
        display: inline-block;
        width: 8px;
        height: 8px;
        margin-right: 4px;
        border-radius: 50%;
        background: #999;
        vertical-align: 0;
    }

    .ttv2-owner[data-level="online"]::before { background: #99cc00; }
    .ttv2-owner[data-level="idle"]::before { background: #e0a000; }
    .ttv2-owner[data-level="offline"]::before { background: #999; }

    /*
     * Your own bazaar's add / manage rows: the current asking prices, after the
     * item name. Text only; nothing is filled in or clicked.
     */
    .ttv2-bztag {
        display: inline-block;
        margin-left: 8px;
        padding: 0 8px;
        border: 1px solid #444;
        border-radius: 4px;
        font: 12px/20px Arial, Helvetica, sans-serif;
        font-variant-numeric: tabular-nums;
        color: #ddd;
        background: #2b2b2b;
        white-space: nowrap;
        vertical-align: middle;
        cursor: pointer;
    }

    .ttv2-bztag:hover,
    .ttv2-bztag[data-selected="true"] {
        border-color: #99cc00;
    }

    .ttv2-bztag b {
        color: #74c0fc;
        font-weight: bold;
    }
    `;

    const PANEL_CSS = `
    /* Nothing from the page is inherited into the panel. */
    :host {
        all: initial;
    }

    .ttv2-panel {
    ${TOKENS_CSS}
        position: fixed;
        right: 16px;
        bottom: 16px;
        z-index: 2147483000;
        width: 430px;
        max-width: calc(100vw - 16px);
        /* Fits its content; the list scrolls beyond this. */
        max-height: min(75vh, 720px);
        min-height: 220px;
        display: flex;
        flex-direction: column;
        background: var(--bg);
        color: var(--text);
        border: 1px solid var(--line);
        border-radius: 4px;
        box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
        font: 13px/1.4 Arial, Helvetica, sans-serif;
        text-align: left;
        overflow: hidden;
    }

    .ttv2-panel *,
    .ttv2-panel *::before,
    .ttv2-panel *::after {
        box-sizing: border-box;
    }

    .ttv2-panel a {
        color: var(--offer);
        text-decoration: none;
    }

    .ttv2-panel a:hover {
        text-decoration: underline;
    }

    .ttv2-panel b,
    .ttv2-panel strong {
        font-weight: bold;
    }

    .ttv2-panel button {
        font: bold 12px/1 Arial, Helvetica, sans-serif;
        height: 28px;
        padding: 0 12px;
        color: var(--text);
        background: var(--line);
        border: 1px solid var(--line);
        border-radius: 4px;
        cursor: pointer;
        white-space: nowrap;
    }

    .ttv2-panel button:hover:not(:disabled) {
        border-color: var(--muted);
    }

    .ttv2-panel button:disabled {
        opacity: 0.5;
        cursor: default;
    }

    .ttv2-panel button:focus-visible,
    .ttv2-panel input:focus-visible,
    .ttv2-panel summary:focus-visible {
        outline: 2px solid var(--profit);
        outline-offset: 1px;
    }

    .ttv2-panel button.ttv2-primary {
        color: var(--on-profit);
        background: var(--profit);
        border-color: var(--profit);
    }

    .ttv2-panel button.ttv2-link {
        height: auto;
        padding: 0;
        background: none;
        border: 0;
        color: var(--offer);
        font-weight: normal;
        font-size: 12px;
    }

    .ttv2-panel button.ttv2-link:hover:not(:disabled) {
        text-decoration: underline;
    }

    .ttv2-panel input[type="text"] {
        font: 13px/1.4 Arial, Helvetica, sans-serif;
        height: 28px;
        color: var(--text);
        background: var(--row);
        border: 1px solid var(--line);
        border-radius: 4px;
        padding: 0 8px;
        width: 100%;
    }

    .ttv2-panel input[type="checkbox"] {
        accent-color: var(--profit);
        margin: 3px 0 0;
    }

    .ttv2-money {
        font-variant-numeric: tabular-nums;
        text-align: right;
        white-space: nowrap;
    }

    .ttv2-label {
        font-size: 11px;
        font-weight: bold;
        letter-spacing: 0.5px;
        text-transform: uppercase;
        color: var(--muted);
    }

    /* ---------------------------------------------------------------- header */

    .ttv2-head {
        display: flex;
        align-items: center;
        gap: 4px;
        height: 30px;
        padding: 0 4px 0 12px;
        background: var(--title);
        border-bottom: 1px solid var(--line);
        cursor: move;
        user-select: none;
        flex: 0 0 auto;
        position: relative;
    }

    .ttv2-title {
        flex: 1;
        min-width: 0;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        font-size: 13px;
        font-weight: bold;
        letter-spacing: 1px;
        color: #fff;
        text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.65);
    }

    .ttv2-mini {
        margin-left: 8px;
        color: var(--profit);
        letter-spacing: 0;
        font-variant-numeric: tabular-nums;
    }

    .ttv2-panel button.ttv2-icon {
        width: 24px;
        height: 24px;
        padding: 0;
        font-size: 15px;
        line-height: 22px;
        text-align: center;
        background: transparent;
        border-color: transparent;
        color: var(--text);
    }

    .ttv2-panel button.ttv2-icon:hover:not(:disabled) {
        background: rgba(255, 255, 255, 0.08);
        border-color: transparent;
    }

    .ttv2-panel button.ttv2-icon[aria-pressed="true"] {
        color: var(--profit);
    }

    .ttv2-panel button.ttv2-back {
        display: none;
        margin-left: -8px;
    }

    .ttv2-on-settings button.ttv2-back {
        display: inline-block;
    }

    .ttv2-panel button.ttv2-scan {
        height: 24px;
        padding: 0 12px;
        color: var(--on-profit);
        background: var(--profit);
        border-color: var(--profit);
    }

    .ttv2-panel button.ttv2-sell {
        height: 24px;
        padding: 0 8px;
        background: transparent;
        border-color: var(--offer);
        color: var(--offer);
    }

    .ttv2-scanning button.ttv2-scan {
        animation: ttv2-pulse 0.8s ease-out;
    }

    @keyframes ttv2-pulse {
        0% { box-shadow: 0 0 0 0 rgba(153, 204, 0, 0.7); }
        100% { box-shadow: 0 0 0 8px rgba(153, 204, 0, 0); }
    }

    .ttv2-sweep {
        position: absolute;
        left: 0;
        bottom: -1px;
        height: 2px;
        width: 30%;
        background: linear-gradient(90deg, transparent, var(--profit), transparent);
        opacity: 0;
        pointer-events: none;
    }

    .ttv2-scanning .ttv2-sweep {
        animation: ttv2-sweep 0.8s ease-in-out;
    }

    @keyframes ttv2-sweep {
        0% { left: -30%; opacity: 1; }
        100% { left: 100%; opacity: 1; }
    }

    .ttv2-spin {
        animation: ttv2-spin 0.9s linear infinite;
    }

    @keyframes ttv2-spin {
        to { transform: rotate(360deg); }
    }

    /* -------------------------------------------------------------- collapsed */

    .ttv2-panel.ttv2-collapsed {
        min-height: 0;
    }

    .ttv2-collapsed .ttv2-body {
        display: none;
    }

    .ttv2-collapsed .ttv2-head {
        border-bottom: 0;
        cursor: pointer;
    }

    /* ------------------------------------------------------------ status bar */

    .ttv2-body {
        flex: 1;
        min-height: 0;
        display: flex;
        flex-direction: column;
    }

    .ttv2-bar {
        display: flex;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        border-bottom: 1px solid var(--line);
        font-size: 12px;
        flex: 0 0 auto;
    }

    .ttv2-bar-left {
        flex: 1;
        min-width: 0;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        font-weight: bold;
        font-variant-numeric: tabular-nums;
    }

    .ttv2-bar.ttv2-warn .ttv2-bar-left {
        color: var(--warn);
        font-weight: normal;
    }

    .ttv2-bar.ttv2-error .ttv2-bar-left {
        color: var(--bad);
        font-weight: normal;
    }

    .ttv2-bar-right {
        color: var(--muted);
        white-space: nowrap;
    }

    .ttv2-dot {
        display: inline-block;
        width: 8px;
        height: 8px;
        margin-right: 4px;
        border-radius: 50%;
        background: var(--muted);
        vertical-align: 0;
    }

    .ttv2-dot-live { background: var(--profit); }
    .ttv2-dot-warn { background: var(--warn); }
    .ttv2-dot-other { background: var(--offer); }

    /* Seller of the bazaar you are on. */
    .ttv2-seller {
        display: none;
        padding: 8px 12px;
        font-size: 12px;
        color: var(--muted);
        border-bottom: 1px solid var(--line);
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        flex: 0 0 auto;
    }

    .ttv2-seller.ttv2-shown {
        display: block;
    }

    .ttv2-seller b {
        color: var(--text);
    }

    .ttv2-seller .ttv2-closed {
        margin-left: 8px;
        color: var(--bad);
        font-weight: bold;
    }

    /* ------------------------------------------------------------------ pages */

    .ttv2-page {
        flex: 1;
        min-height: 0;
        display: flex;
        flex-direction: column;
    }

    .ttv2-page-settings,
    .ttv2-on-settings .ttv2-page-list {
        display: none;
    }

    .ttv2-on-settings .ttv2-page-settings {
        display: flex;
        overflow-y: auto;
        padding: 12px;
        gap: 16px;
    }

    /* ------------------------------------------------------------------ chips */

    .ttv2-chips {
        display: flex;
        flex-wrap: nowrap;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        border-bottom: 1px solid var(--line);
        flex: 0 0 auto;
        overflow: hidden;
    }

    .ttv2-chips-gap {
        flex: 1;
    }

    .ttv2-panel button.ttv2-chip {
        height: 24px;
        padding: 0 8px;
        border-radius: 12px;
        font-weight: normal;
        background: transparent;
        border-color: var(--line);
        color: var(--muted);
    }

    .ttv2-panel button.ttv2-chip[aria-pressed="true"] {
        color: var(--text);
        border-color: var(--profit);
        background: rgba(153, 204, 0, 0.12);
    }

    .ttv2-panel button.ttv2-chip-set {
        color: var(--text);
        border-color: var(--muted);
    }

    .ttv2-panel input.ttv2-chip-input {
        width: 96px;
        height: 24px;
        padding: 0 8px;
        border-radius: 12px;
        font-size: 12px;
    }

    /* ------------------------------------------------------------------- tabs */

    .ttv2-tabs {
        display: flex;
        align-items: center;
        gap: 4px;
        padding: 8px 12px 0;
        border-bottom: 1px solid var(--line);
        flex: 0 0 auto;
    }

    .ttv2-panel button.ttv2-tab {
        height: 28px;
        border-radius: 4px 4px 0 0;
        border-bottom: 0;
        background: transparent;
        color: var(--muted);
        font-weight: normal;
    }

    .ttv2-panel button.ttv2-tab.ttv2-tab-on {
        background: var(--row);
        color: var(--text);
        font-weight: bold;
        box-shadow: inset 0 2px 0 var(--profit);
    }

    .ttv2-credit {
        margin-left: auto;
        padding-bottom: 8px;
        color: var(--muted);
        font-size: 12px;
        white-space: nowrap;
    }

    /* ------------------------------------------------------------------- list */

    .ttv2-list {
        flex: 1;
        min-height: 0;
        overflow-y: auto;
        padding: 8px 12px;
    }

    .ttv2-cols {
        display: grid;
        grid-template-columns: minmax(0, 1fr) 96px;
        gap: 8px;
        padding: 0 12px 4px;
    }

    .ttv2-cols .ttv2-money {
        color: var(--muted);
    }

    /*
     * One deal, two lines:
     *   Xanax ×390                                   +$11,255
     *   Bazaar · Garrett89 ● Offline 3h · Buy $838,745 · 40s     [Go]
     */
    .ttv2-row {
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        grid-template-rows: auto auto;
        align-items: start;
        column-gap: 8px;
        row-gap: 4px;
        padding: 8px 12px;
        margin-bottom: 8px;
        background: var(--row);
        border: 1px solid var(--line);
        border-radius: 4px;
    }

    .ttv2-row.ttv2-onpage {
        border-color: var(--profit);
    }

    .ttv2-row-name {
        min-width: 0;
        font-weight: bold;
        color: var(--text);
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    .ttv2-row-name .ttv2-qty {
        margin-left: 4px;
        font-weight: normal;
        color: var(--muted);
        font-variant-numeric: tabular-nums;
    }

    .ttv2-row-profit {
        font-size: 15px;
        font-weight: bold;
        color: var(--profit);
        min-width: 96px;
    }

    .ttv2-row-profit .ttv2-per {
        display: block;
        font-size: 12px;
        font-weight: normal;
        color: var(--muted);
    }

    .ttv2-row-details {
        align-self: center;
    }

    .ttv2-row-details {
        min-width: 0;
        font-size: 12px;
        color: var(--muted);
        overflow-wrap: anywhere;
        font-variant-numeric: tabular-nums;
    }

    .ttv2-row-details b {
        color: var(--text);
        font-weight: normal;
    }

    .ttv2-row-details .ttv2-guess {
        color: var(--warn);
        cursor: help;
    }

    /* "● Online" / "● Offline 3h" - an 8px dot and a word. */
    .ttv2-status::before {
        content: "";
        display: inline-block;
        width: 8px;
        height: 8px;
        margin: 0 4px 0 4px;
        border-radius: 50%;
        background: var(--muted);
        vertical-align: 0;
    }

    .ttv2-status[data-level="online"]::before { background: var(--profit); }
    .ttv2-status[data-level="idle"]::before { background: var(--warn); }
    .ttv2-status[data-level="unknown"]::before {
        background: transparent;
        border: 1px solid var(--muted);
    }

    .ttv2-panel button.ttv2-go {
        justify-self: end;
        min-width: 40px;
        padding: 0 8px;
    }

    .ttv2-empty {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 12px;
        padding: 24px 16px;
        text-align: center;
    }

    .ttv2-empty-text {
        color: var(--muted);
        max-width: 320px;
    }

    /* --------------------------------------------------------- my bazaar view */

    .ttv2-bzlist {
        padding: 8px 12px;
        border-bottom: 1px solid var(--line);
        flex: 0 0 auto;
        max-height: 40%;
        overflow-y: auto;
    }

    .ttv2-bzrow {
        display: grid;
        grid-template-columns: minmax(0, 1fr) 96px 96px;
        gap: 8px;
        align-items: center;
        width: 100%;
        height: auto;
        padding: 4px 8px;
        margin-bottom: 4px;
        text-align: left;
        font-weight: normal;
        background: transparent;
        border-color: transparent;
    }

    .ttv2-panel button.ttv2-bzrow {
        height: auto;
        padding: 4px 8px;
        font-weight: normal;
        font-size: 13px;
        background: transparent;
        border-color: transparent;
    }

    .ttv2-panel button.ttv2-bzrow[aria-pressed="true"] {
        background: var(--row);
        border-color: var(--line);
    }

    .ttv2-bzrow .ttv2-name {
        min-width: 0;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
        color: var(--text);
    }

    .ttv2-bzrow .ttv2-money {
        color: var(--offer);
    }

    .ttv2-bzdetail {
        flex: 1;
        min-height: 0;
        overflow-y: auto;
        padding: 12px;
        display: flex;
        flex-direction: column;
        gap: 8px;
    }

    .ttv2-bzdetail h3 {
        margin: 0;
        font-size: 13px;
        font-weight: bold;
    }

    .ttv2-avg {
        width: 100%;
        border-collapse: collapse;
        font-size: 12px;
    }

    .ttv2-avg th,
    .ttv2-avg td {
        padding: 4px 8px;
        border-top: 1px solid var(--line);
        text-align: left;
        white-space: nowrap;
    }

    .ttv2-avg th {
        color: var(--muted);
        font-weight: normal;
    }

    .ttv2-avg td.ttv2-money,
    .ttv2-avg th.ttv2-money {
        text-align: right;
    }

    .ttv2-avg .ttv2-none {
        color: var(--muted);
    }

    .ttv2-graph {
        width: 100%;
        height: 96px;
        display: block;
        background: var(--row);
        border: 1px solid var(--line);
        border-radius: 4px;
    }

    .ttv2-graph-keys {
        display: flex;
        gap: 12px;
        font-size: 12px;
        color: var(--muted);
    }

    .ttv2-graph-keys .ttv2-key-im { color: var(--offer); }
    .ttv2-graph-keys .ttv2-key-bz { color: var(--profit); }
    .ttv2-graph-keys .ttv2-key-mv { color: var(--warn); }

    .ttv2-windows {
        display: flex;
        gap: 4px;
    }

    .ttv2-panel button.ttv2-window {
        height: 24px;
        padding: 0 8px;
        font-weight: normal;
        background: transparent;
    }

    .ttv2-panel button.ttv2-window[aria-pressed="true"] {
        background: var(--row);
        border-color: var(--muted);
        font-weight: bold;
    }

    .ttv2-note {
        color: var(--muted);
        font-size: 12px;
    }

    /* --------------------------------------------------------------- settings */

    .ttv2-section {
        display: flex;
        flex-direction: column;
        gap: 8px;
    }

    .ttv2-h {
        margin: 0;
        padding: 0;
        font-size: 11px;
        font-weight: bold;
        text-transform: uppercase;
        letter-spacing: 0.5px;
        color: var(--muted);
    }

    .ttv2-check {
        display: flex;
        align-items: flex-start;
        gap: 8px;
        cursor: pointer;
    }

    .ttv2-check-label {
        color: var(--text);
    }

    .ttv2-sub {
        display: block;
        color: var(--muted);
        font-size: 12px;
    }

    .ttv2-inline {
        display: flex;
        gap: 8px;
        align-items: center;
    }

    .ttv2-inline input {
        flex: 1;
        min-width: 0;
    }

    .ttv2-masked {
        -webkit-text-security: disc;
    }

    .ttv2-keystate {
        font-size: 12px;
        color: var(--muted);
    }

    .ttv2-keystate.ttv2-ok { color: var(--profit); }
    .ttv2-keystate.ttv2-bad { color: var(--bad); }

    .ttv2-tos-box {
        border: 1px solid var(--line);
        border-radius: 4px;
        padding: 8px;
        background: var(--row);
    }

    .ttv2-tos-box summary {
        cursor: pointer;
        color: var(--text);
        font-size: 12px;
    }

    .ttv2-tos {
        width: 100%;
        margin-top: 8px;
        border-collapse: collapse;
        font-size: 12px;
        color: var(--text);
    }

    .ttv2-tos th,
    .ttv2-tos td {
        text-align: left;
        vertical-align: top;
        padding: 4px;
        border-top: 1px solid var(--line);
    }

    .ttv2-tos th {
        width: 36%;
        color: var(--muted);
        font-weight: normal;
    }
    `;

    /** Inject the page (card marker) stylesheet once. */
    function injectStyles(doc = document) {
        const id = UI_PREFIX + '-styles';
        if (doc.getElementById(id)) return;

        const style = doc.createElement('style');
        style.id = id;
        style.textContent = PAGE_CSS;

        (doc.head || doc.documentElement).appendChild(style);
    }

    /** A <style> for the panel's shadow root. */
    function panelStyleElement(doc = document) {
        const style = doc.createElement('style');
        style.textContent = PANEL_CSS;
        return style;
    }

    /* ===== src/ui/graph.js ===== */
    /*
     * A small SVG line graph of recorded asking prices, built as DOM nodes
     * (never innerHTML). Two lines - the lowest Item Market ask and the lowest
     * bazaar ask - and Torn's daily market value as a dashed step line. Gaps in
     * the record stay gaps: a line is broken where a bucket has no data, so the
     * picture never pretends to know more than was recorded.
     */

    const SVG_NS = 'http://www.w3.org/2000/svg';

    function svgEl(tag, attrs = {}) {
        const node = document.createElementNS(SVG_NS, tag);
        for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, String(v));
        return node;
    }

    /** The smallest spacing between points: the bucket width, when `step` is not given. */
    function inferStep(points) {
        let min = 0;
        for (let i = 1; i < points.length; i += 1) {
            const gap = points[i].t - points[i - 1].t;
            if (gap > 0 && (!min || gap < min)) min = gap;
        }
        return min;
    }

    /**
     * @param {object} data - from core/history.js series(): { from, to, points, mv, step }
     * @param {object} [opts] - { width, height, colors: { im, bz, mv } }
     * @returns {SVGElement}
     */
    function renderPriceGraph(data, opts = {}) {
        const width = opts.width || 400;
        const height = opts.height || 96;
        const pad = { l: 8, r: 8, t: 8, b: 8 };
        const colors = { im: '#74c0fc', bz: '#99cc00', mv: '#e0a000', ...(opts.colors || {}) };

        const svg = svgEl('svg', {
            viewBox: '0 0 ' + width + ' ' + height,
            preserveAspectRatio: 'none',
            class: 'ttv2-graph',
            role: 'img',
        });

        const values = [];
        for (const p of data.points || []) {
            if (p.im !== null && p.im !== undefined) values.push(p.im);
            if (p.bz !== null && p.bz !== undefined) values.push(p.bz);
        }
        for (const m of data.mv || []) if (m.mv) values.push(m.mv);

        if (values.length < 1) {
            const t = svgEl('text', { x: width / 2, y: height / 2 + 4, 'text-anchor': 'middle', fill: '#999', 'font-size': 12, 'font-family': 'Arial' });
            t.textContent = 'Nothing recorded yet';
            svg.appendChild(t);
            return svg;
        }

        let min = Math.min(...values);
        let max = Math.max(...values);
        if (min === max) {
            min *= 0.95;
            max *= 1.05;
        }
        const span = data.to - data.from || 1;
        const x = (t) => pad.l + ((t - data.from) / span) * (width - pad.l - pad.r);
        const y = (v) => height - pad.b - ((v - min) / (max - min)) * (height - pad.t - pad.b);

        // A bucket with nothing recorded is simply absent from the points, so a
        // jump of more than one bucket between neighbours is a gap too.
        const step = Number(data.step) || inferStep(data.points || []);

        const line = (key, color, dashed) => {
            let d = '';
            let pen = false;
            let run = 0;
            const lone = [];
            let prev = null;
            let prevT = null;
            for (const p of data.points || []) {
                const v = p[key];
                if (v === null || v === undefined) {
                    if (run === 1 && prev) lone.push(prev);
                    pen = false;
                    run = 0;
                    continue;
                }
                if (pen && step && prevT !== null && p.t - prevT > step * 1.5) {
                    if (run === 1 && prev) lone.push(prev);
                    pen = false;
                    run = 0;
                }
                d += (pen ? ' L' : ' M') + x(p.t).toFixed(1) + ' ' + y(v).toFixed(1);
                pen = true;
                run += 1;
                prev = { cx: x(p.t), cy: y(v) };
                prevT = p.t;
            }
            if (run === 1 && prev) lone.push(prev);
            if (!d) return;
            const attrs = { d: d.trim(), fill: 'none', stroke: color, 'stroke-width': 1.5, 'vector-effect': 'non-scaling-stroke' };
            if (dashed) attrs['stroke-dasharray'] = '4 3';
            svg.appendChild(svgEl('path', attrs));
            // A sample with no neighbour would be an invisible zero-length line.
            for (const c of lone) svg.appendChild(svgEl('circle', { cx: c.cx.toFixed(1), cy: c.cy.toFixed(1), r: 2, fill: color }));
        };

        line('im', colors.im, false);
        line('bz', colors.bz, false);

        // Market value: one value a day, drawn as steps to the next day.
        const mv = (data.mv || []).filter((m) => m.mv);
        if (mv.length) {
            let d = '';
            for (let i = 0; i < mv.length; i += 1) {
                const start = Math.max(mv[i].t, data.from);
                const end = i + 1 < mv.length ? mv[i + 1].t : data.to;
                d += (d ? ' L' : 'M') + x(start).toFixed(1) + ' ' + y(mv[i].mv).toFixed(1);
                d += ' L' + x(Math.min(end, data.to)).toFixed(1) + ' ' + y(mv[i].mv).toFixed(1);
            }
            svg.appendChild(svgEl('path', { d, fill: 'none', stroke: colors.mv, 'stroke-width': 1, 'stroke-dasharray': '4 3', 'vector-effect': 'non-scaling-stroke' }));
        }

        return svg;
    }

    /* ===== src/ui/panel.js ===== */
    /*
     * The panel: a floating window with three pages.
     *
     *   header      Torn-style title bar: Sell, Scan, refresh, settings, collapse
     *   status bar  ONE line: "5 deals · +$5.18m"  ...  "● live · 12s"
     *   list        sell-to chips, Bazaars / Item Market tabs, ranked deals
     *   my bazaar   on your own bazaar's add / manage pages: what each item is
     *               going for now, and what the script has recorded
     *   settings    replaces the list (Back or Esc returns)
     *
     * Every button has one job and shows its state. Nothing goes on Torn's item
     * cards beyond one class; every number lives here. All text goes in through
     * textContent - names from Torn or TornW3B never touch innerHTML. The panel
     * is in a shadow root (see mount()).
     */








    /** "last update 2m ago" turns the status amber after this. */
    const PANEL_STALE_MS = 60000;

    const TORN_API_KEY_URL = 'https://www.torn.com/preferences.php#tab=api';

    /** Info messages ("Ready.") clear themselves; warnings and errors stay. */
    const INFO_STATUS_MS = 6000;

    function el(tag, props = {}, children = []) {
        const node = document.createElement(tag);

        for (const [key, value] of Object.entries(props)) {
            if (key === 'class') node.className = value;
            else if (key === 'text') node.textContent = value;
            else if (key.startsWith('on') && typeof value === 'function') {
                node.addEventListener(key.slice(2).toLowerCase(), value);
            } else if (value !== null && value !== undefined) {
                node.setAttribute(key, String(value));
            }
        }

        for (const child of [].concat(children)) {
            if (child === null || child === undefined || child === false) continue;
            node.appendChild(typeof child === 'string' ? document.createTextNode(child) : child);
        }

        return node;
    }

    /**
     * Wrap a click handler so a thrown error lands in the panel.
     *
     * Without this an exception inside a handler is swallowed by the event loop
     * and the button simply appears dead - which is exactly how the first report
     * of "clicking Scan does nothing" arrived. A visible error is worth far more
     * than a tidy console.
     */
    function guarded(panel, label, fn) {
        return (...args) => {
            try {
                const result = fn(...args);
                if (result && typeof result.catch === 'function') {
                    result.catch((error) => {
                        panel.setStatus(label + ' failed: ' + describeError(error), 'error');
                    });
                }
                return result;
            } catch (error) {
                panel.setStatus(label + ' failed: ' + describeError(error), 'error');
                return undefined;
            }
        };
    }

    function describeError(error) {
        if (!error) return 'unknown error';
        return String(error.message || error);
    }

    /** Keys typed into these belong to the page (or our fields), not the hotkey. */
    const TEXT_INPUT_TYPES = new Set([
        '', 'text', 'search', 'email', 'number', 'password', 'tel', 'url',
    ]);

    function isTypingTarget(event) {
        // composedPath() sees into shadow roots, so our own inputs count too.
        const path = typeof event.composedPath === 'function' ? event.composedPath() : [];
        const node = path[0] || event.target;
        if (!node || node.nodeType !== 1) return false;

        if (node.isContentEditable) return true;
        const tag = node.tagName;
        if (tag === 'TEXTAREA' || tag === 'SELECT') return true;
        if (tag === 'INPUT') {
            return TEXT_INPUT_TYPES.has(String(node.getAttribute('type') || '').toLowerCase());
        }
        return false;
    }

    /** Long enough to see, short enough not to get in the way. */
    const SCAN_ANIMATION_MS = 800;

    /** A current asking price: "$30", "none" when nothing is listed, null until asked. */
    function priceText(entry) {
        if (!entry) return null;
        return entry.price > 0 ? formatMoney(entry.price) : 'none';
    }

    class Panel {
        /**
         * @param {object} handlers
         * @param {function} handlers.onScan           - refresh everything now
         * @param {function} handlers.onScanPage       - re-read this page now
         * @param {function} handlers.onNavigate       - (row) => void
         * @param {function} handlers.onSettingsChange - (partialSettings) => void
         * @param {function} handlers.onViewChange     - ('bazaar'|'itemmarket')
         * @param {function} handlers.onSaveKey        - (key) => Promise<void>
         * @param {function} handlers.onForgetKey
         * @param {function} handlers.onClearCache
         * @param {function} handlers.onRevealKey      - () => stored key
         * @param {function} handlers.onOpenSelling    - open the selling page
         * @param {function} handlers.onSelectBazaarItem - (itemId) => void
         * @param {function} handlers.onBazaarWindow   - ('24h'|'7d'|'30d') => void
         */
        constructor(handlers = {}) {
            this.handlers = handlers;
            this.state = {
                rows: [],
                summary: { count: 0, totalProfit: 0, cashRequired: 0 },
                status: { text: '', level: 'info', at: 0 },
                settings: {},
                diagnostics: null,
                lastScanAt: null,
                busy: false,
                tab: 'bazaar',
                counts: {},
                live: null,
                bazaar: null,
            };

            this.page = 'list';
            this.hasKey = false;
            this.root = null;
            this.ticker = null;
        }

        /* ------------------------------------------------------------ mount */

        mount(parent = document.body) {
            if (this.root) return this.root;

            /* ---- header ---- */

            this.backBtn = el('button', {
                type: 'button',
                class: 'ttv2-icon ttv2-back',
                title: 'Back (Esc)',
                'aria-label': 'Back',
                text: '←',
                onclick: () => this.showPage(this.homePage()),
            });

            this.titleEl = el('div', { class: 'ttv2-title' });
            this.titleTextEl = el('span', { text: 'NPC Arbitrage' });
            // Shown only while collapsed: the headline, so a collapsed panel
            // still answers "is there anything to buy?".
            this.miniEl = el('span', { class: 'ttv2-mini' });
            this.titleEl.appendChild(this.titleTextEl);
            this.titleEl.appendChild(this.miniEl);

            // The selling page: its own tab, for the items you hold.
            this.sellBtn = el('button', {
                type: 'button',
                class: 'ttv2-sell',
                title: 'Open the selling page in a new tab',
                text: 'Sell',
                onclick: guarded(this, 'Sell', () => this.handlers.onOpenSelling && this.handlers.onOpenSelling()),
            });

            // Re-reads the listings on this page right away - no requests, so
            // it can be pressed as often as you like. The refresh is ↻.
            this.scanBtn = el('button', {
                type: 'button',
                class: 'ttv2-scan',
                title: 'Scan this page now',
                'aria-label': 'Scan this page now',
                text: 'Scan',
                onclick: guarded(this, 'Scan', () => {
                    if (!this.hasKey) {
                        this.showPage('settings', { focusKey: true });
                        return undefined;
                    }
                    return this.handlers.onScanPage ? this.handlers.onScanPage() : undefined;
                }),
            });

            this.refreshBtn = el('button', {
                type: 'button',
                class: 'ttv2-icon',
                title: 'Refresh now',
                'aria-label': 'Refresh now',
                text: '↻',
                onclick: guarded(this, 'Refresh', () => {
                    if (!this.hasKey) {
                        this.showPage('settings', { focusKey: true });
                        return undefined;
                    }
                    return this.handlers.onScan ? this.handlers.onScan() : undefined;
                }),
            });

            this.settingsBtn = el('button', {
                type: 'button',
                class: 'ttv2-icon',
                title: 'Settings',
                'aria-label': 'Settings',
                'aria-pressed': 'false',
                text: '⚙',
                onclick: () => this.showPage(this.page === 'settings' ? this.homePage() : 'settings'),
            });

            this.collapseBtn = el('button', {
                type: 'button',
                class: 'ttv2-icon',
                title: 'Collapse (`)',
                'aria-label': 'Collapse',
                text: '–',
                onclick: () => this.setCollapsed(!this.collapsed, { save: true }),
            });

            // A thin line that sweeps under the header on every visible scan, so
            // you can see a scan happened even when nothing on the list changed.
            this.sweepEl = el('div', { class: 'ttv2-sweep', 'aria-hidden': 'true' });

            this.headEl = el('div', { class: 'ttv2-head' }, [
                this.backBtn,
                this.titleEl,
                this.sellBtn,
                this.scanBtn,
                this.refreshBtn,
                this.settingsBtn,
                this.collapseBtn,
                this.sweepEl,
            ]);

            /* ---- status bar ---- */

            this.barLeft = el('span', { class: 'ttv2-bar-left' });
            this.barRight = el('span', { class: 'ttv2-bar-right' });
            this.barEl = el('div', { class: 'ttv2-bar' }, [this.barLeft, this.barRight]);

            /* ---- list page ---- */

            this.chipsEl = el('div', { class: 'ttv2-chips' });
            this.buildChips();

            this.tabBtns = {};
            this.tabsEl = el('div', { class: 'ttv2-tabs' });
            for (const [key, label] of [
                ['bazaar', 'Bazaars'],
                ['itemmarket', 'Item Market'],
            ]) {
                const btn = el('button', {
                    type: 'button',
                    class: 'ttv2-tab',
                    text: label,
                    onclick: () => this.handlers.onViewChange && this.handlers.onViewChange(key),
                });
                btn.dataset.label = label;
                this.tabBtns[key] = btn;
                this.tabsEl.appendChild(btn);
            }

            // Where bazaar data comes from, on the tab it feeds.
            this.creditEl = el('span', { class: 'ttv2-credit' }, [
                el('a', {
                    href: W3B_SITE_URL,
                    target: '_blank',
                    rel: 'noopener noreferrer',
                    title: 'Bazaar prices come from TornW3B',
                    text: 'via TornW3B',
                }),
                ' · ',
                el('a', {
                    href: W3B_TERMS_URL,
                    target: '_blank',
                    rel: 'noopener noreferrer',
                    text: 'terms',
                }),
            ]);
            this.tabsEl.appendChild(this.creditEl);

            this.colsEl = el('div', { class: 'ttv2-cols' }, [
                el('span', { class: 'ttv2-label', text: 'Deal' }),
                el('span', { class: 'ttv2-label ttv2-money', text: 'Profit' }),
            ]);

            this.listEl = el('div', { class: 'ttv2-list' });

            // Whose bazaar this is, and whether they are around. Bazaar pages only.
            this.sellerEl = el('div', { class: 'ttv2-seller' });

            this.listPage = el('div', { class: 'ttv2-page ttv2-page-list' }, [
                this.sellerEl,
                this.chipsEl,
                this.tabsEl,
                this.listEl,
            ]);

            /* ---- my bazaar page ---- */

            this.bzListEl = el('div', { class: 'ttv2-bzlist' });
            this.bzDetailEl = el('div', { class: 'ttv2-bzdetail' });
            this.bazaarPage = el('div', { class: 'ttv2-page ttv2-page-bazaar' }, [this.bzListEl, this.bzDetailEl]);
            this.bazaarPage.style.display = 'none';

            /* ---- settings page ---- */

            this.settingsPage = el('div', { class: 'ttv2-page ttv2-page-settings' });
            this.buildSettings();

            this.bodyEl = el('div', { class: 'ttv2-body' }, [
                this.barEl,
                this.listPage,
                this.bazaarPage,
                this.settingsPage,
            ]);

            this.root = el('div', { class: 'ttv2-panel' }, [this.headEl, this.bodyEl]);

            // Esc closes an open chip editor, then Settings.
            this.root.addEventListener('keydown', (event) => {
                if (event.key !== 'Escape') return;
                if (this.closeChipEditor()) return;
                if (this.page === 'settings') this.showPage(this.homePage());
            });

            this.enableDrag(this.headEl);

            /*
             * The panel lives in a shadow root. Torn's stylesheet cannot reach
             * into it - it had been turning our section headings into giant
             * type - and nothing of ours leaks onto Torn's page.
             */
            this.host = document.createElement('div');
            this.host.id = 'ttv2-host';
            this.shadow = this.host.attachShadow({ mode: 'open' });
            this.shadow.appendChild(panelStyleElement(document));
            this.shadow.appendChild(this.root);
            parent.appendChild(this.host);

            window.addEventListener('resize', () => this.clampIntoView());

            this.showPage('list');

            // Every second: row ages and the refresh countdown are the "is this
            // still live?" signal.
            this.ticker = setInterval(() => this.refreshAges(), 1000);

            return this.root;
        }

        /* ------------------------------------------------------------ pages */

        /** The page Back returns to: My bazaar on your own bazaar, else the list. */
        homePage() {
            return this.state.bazaar ? 'mybazaar' : 'list';
        }

        /**
         * Switch pages. Settings REPLACES the list, at the same panel size - it
         * never stacks on top of it.
         */
        showPage(page, { focusKey = false } = {}) {
            this.page = page === 'settings' ? 'settings' : page === 'mybazaar' ? 'mybazaar' : 'list';
            if (!this.root) return;

            const settings = this.page === 'settings';

            /*
             * Keep the panel's height steady across the switch: Settings may be
             * shorter or taller than the list (it scrolls), and a panel that
             * jumps in size on every click is the kind of jumpiness this
             * redesign is meant to remove.
             */
            if (settings && !this.root.classList.contains('ttv2-on-settings')) {
                const h = this.root.getBoundingClientRect().height + 'px';
                this.root.style.minHeight = h;
                this.root.style.height = h;
            } else if (!settings) {
                this.root.style.minHeight = '';
                this.root.style.height = '';
            }

            this.root.classList.toggle('ttv2-on-settings', settings);
            this.listPage.style.display = this.page === 'list' ? '' : 'none';
            this.bazaarPage.style.display = this.page === 'mybazaar' ? '' : 'none';
            this.settingsBtn.setAttribute('aria-pressed', String(settings));
            this.titleTextEl.textContent = settings ? 'Settings' : this.page === 'mybazaar' ? 'My bazaar' : 'NPC Arbitrage';

            // Opening a page from a collapsed panel should show it.
            if (this.collapsed) this.setCollapsed(false, { save: true });

            if (settings && focusKey && this.keyInput) {
                setTimeout(() => this.keyInput.focus(), 0);
            }
        }

        openSettings({ focusKey = false } = {}) {
            this.showPage('settings', { focusKey });
        }

        /* ------------------------------------------------------------ chips */

        /**
         * Always-visible filters. "Sell to" answers the one question that
         * matters, with one click and no menu; the money filters open a tiny
         * editor in place.
         */
        buildChips() {
            const toggle = (key, label, title) => {
                const chip = el('button', {
                    type: 'button',
                    class: 'ttv2-chip',
                    title,
                    'aria-pressed': 'false',
                    text: label,
                    onclick: () => {
                        const on = chip.getAttribute('aria-pressed') !== 'true';
                        chip.setAttribute('aria-pressed', String(on));
                        this.emitSettings({ [key]: on });
                    },
                });
                chip.dataset.key = key;
                return chip;
            };

            this.chipNpc = toggle('sellToNpc', 'NPC', 'Listings under the NPC sell price. Guaranteed, no tax.');
            this.chipBazaar = toggle('resaleBazaar', 'My bazaar', 'Listings under value, to relist in your bazaar.');
            this.chipMarket = toggle('resaleMarket', 'Market', 'Listings under value, to resell on the Item Market.');

            this.chipMin = this.valueChip(
                'minTotalProfit',
                (v) => 'Min ' + formatMoneyShort(v || 0),
                'Hide deals below this total profit',
            );
            this.chipCash = this.valueChip(
                'cashOnHand',
                (v) => (v ? 'Cash ' + formatMoneyShort(v) : 'Cash: any'),
                'Show only what this cash can buy',
            );

            this.chipsEl.appendChild(this.chipNpc);
            this.chipsEl.appendChild(this.chipBazaar);
            this.chipsEl.appendChild(this.chipMarket);
            this.chipsEl.appendChild(el('span', { class: 'ttv2-chips-gap' }));
            this.chipsEl.appendChild(this.chipMin);
            this.chipsEl.appendChild(this.chipCash);
        }

        /**
         * A chip showing a number; click it to edit in place (Enter / Esc).
         * Anything the editor cannot read keeps the old value and says so:
         * a cash figure that silently became "no cap" showed every deal as
         * affordable.
         */
        valueChip(key, label, title) {
            const chip = el('button', {
                type: 'button',
                class: 'ttv2-chip ttv2-chip-value',
                title,
            });
            chip.dataset.key = key;
            chip.labelFor = label;
            chip.textContent = label(null);

            chip.addEventListener('click', () => {
                this.closeChipEditor();

                const input = el('input', {
                    type: 'text',
                    inputmode: 'numeric',
                    class: 'ttv2-chip-input',
                    placeholder: key === 'cashOnHand' ? 'any' : '0',
                    'aria-label': title,
                });
                const current = this.state.settings[key];
                input.value = current === null || current === undefined ? '' : String(current);

                const commit = () => {
                    const raw = input.value.trim();
                    this.closeChipEditor();

                    if (!raw) {
                        if (/must be a number/.test(this.state.status.text)) this.setStatus('');
                        this.emitSettings({ [key]: key === 'cashOnHand' ? null : 0 });
                        return;
                    }
                    const value = parseMoneyInput(raw);
                    if (value === null || value < 0) {
                        this.setStatus(
                            (key === 'cashOnHand' ? 'Cash' : 'Min') + ' must be a number like 1234567 or 1.5m.',
                            'error',
                        );
                        return;
                    }
                    // A good value clears the complaint about a bad one.
                    if (/must be a number/.test(this.state.status.text)) this.setStatus('');
                    this.emitSettings({ [key]: key === 'cashOnHand' && value === 0 ? null : value });
                };

                input.addEventListener('keydown', (event) => {
                    if (event.key === 'Enter') commit();
                    if (event.key === 'Escape') {
                        event.stopPropagation();
                        this.closeChipEditor();
                    }
                });
                input.addEventListener('blur', () => {
                    if (this.chipEditor && this.chipEditor.input === input) commit();
                });

                chip.style.display = 'none';
                chip.parentNode.insertBefore(input, chip.nextSibling);
                this.chipEditor = { chip, input };
                input.focus();
                input.select();
            });

            return chip;
        }

        /** @returns {boolean} true if an editor was open */
        closeChipEditor() {
            const editor = this.chipEditor;
            if (!editor) return false;

            this.chipEditor = null;
            editor.chip.style.display = '';
            if (editor.input.parentNode) editor.input.parentNode.removeChild(editor.input);
            return true;
        }

        /* --------------------------------------------------------- settings */

        /**
         * Settings, top to bottom: the key (with Torn's required disclosure
         * right under it), watching, and links. Maintenance (re-download item
         * data, reset panel position, scan diagnostics) is in the Tampermonkey
         * menu, out of the way. The selling page keeps its own settings.
         */
        buildSettings() {
            const section = (title, children) =>
                el('section', { class: 'ttv2-section' }, [
                    el('h3', { class: 'ttv2-h', text: title }),
                    ...children,
                ]);

            const note = (text) => el('div', { class: 'ttv2-note', text });

            /* ---- API key ---- */

            /*
             * NOT type="password": Chrome would treat it as a login form, offer
             * to save it, and autofill over it. Masking is CSS. And the saved key
             * is not kept in the field - a value in an <input> is readable by any
             * script with the panel's shadow root - Show fetches it, Hide removes it.
             */
            this.keyInput = el('input', {
                type: 'text',
                class: 'ttv2-masked ttv2-key',
                placeholder: 'Public API key',
                autocomplete: 'off',
                autocapitalize: 'off',
                autocorrect: 'off',
                spellcheck: 'false',
                'data-lpignore': 'true',
                'data-1p-ignore': 'true',
            });

            this.keyRevealed = false;
            const showBtn = el('button', {
                type: 'button',
                text: 'Show',
                onclick: () => {
                    const hidden = this.keyInput.classList.toggle('ttv2-masked');
                    showBtn.textContent = hidden ? 'Show' : 'Hide';

                    if (!hidden && !this.keyInput.value && this.handlers.onRevealKey) {
                        this.keyInput.value = this.handlers.onRevealKey() || '';
                        this.keyRevealed = true;
                    } else if (hidden && this.keyRevealed) {
                        this.keyInput.value = '';
                        this.keyRevealed = false;
                    }
                },
            });

            const save = guarded(this, 'Save', () => {
                const key = this.keyInput.value.trim();
                return this.handlers.onSaveKey ? this.handlers.onSaveKey(key) : undefined;
            });

            this.keyInput.addEventListener('keydown', (event) => {
                if (event.key !== 'Enter') return;
                event.preventDefault();
                save();
            });

            const saveBtn = el('button', { type: 'button', class: 'ttv2-primary', text: 'Save', onclick: save });

            this.keyStateEl = el('div', { class: 'ttv2-keystate', text: 'No key saved.' });

            const keyHelp = el('div', { class: 'ttv2-note' }, [
                'A Public key is enough. Make one at ',
                el('a', {
                    href: TORN_API_KEY_URL,
                    target: '_blank',
                    rel: 'noopener noreferrer',
                    text: 'Torn › Settings › API Key',
                }),
                '.',
            ]);

            // Torn requires this where the key is entered; it stays right here.
            this.tosEl = el('details', { class: 'ttv2-tos-box', open: '' }, [
                el('summary', { text: 'Key use (Torn API terms)' }),
                this.buildTosTable(),
            ]);

            const forgetBtn = el('button', {
                type: 'button',
                class: 'ttv2-link',
                text: 'Forget key',
                onclick: () => this.handlers.onForgetKey && this.handlers.onForgetKey(),
            });

            this.settingsPage.appendChild(
                section('API key', [
                    el('div', { class: 'ttv2-inline' }, [this.keyInput, showBtn, saveBtn]),
                    this.keyStateEl,
                    keyHelp,
                    this.tosEl,
                    forgetBtn,
                ]),
            );

            /* ---- watching ---- */

            const check = (key, label, sub) => {
                const input = el('input', { type: 'checkbox' });
                input.addEventListener('change', () => this.emitSettings({ [key]: input.checked }));

                const row = el('label', { class: 'ttv2-check' }, [
                    input,
                    el('span', {}, [
                        el('span', { class: 'ttv2-check-label', text: label }),
                        sub,
                    ]),
                ]);
                return { input, row };
            };

            const im = check(
                'liveFeed',
                'Watch the Item Market anywhere',
                el('span', { class: 'ttv2-sub', text: 'One visible Torn tab, at most 30 API calls a minute.' }),
            );
            this.liveFeedInput = im.input;

            const w3bSub = el('span', { class: 'ttv2-sub' }, [
                'Bazaar prices from ',
                el('a', { href: W3B_SITE_URL, target: '_blank', rel: 'noopener noreferrer', text: 'weav3r.dev' }),
                ' (',
                el('a', { href: W3B_TERMS_URL, target: '_blank', rel: 'noopener noreferrer', text: 'terms' }),
                '). It gets item ids only, never your key.',
            ]);

            const bz = check('useW3b', 'Watch bazaars via TornW3B', w3bSub);
            this.useW3bInput = bz.input;

            this.settingsPage.appendChild(
                section('Watching', [im.row, bz.row, note('Nothing is bought, clicked or announced for you.')]),
            );

            /* ---- links ---- */

            const nt = check(
                'openInNewTab',
                'Open deals in a new tab',
                el('span', { class: 'ttv2-sub', text: 'Off: Go opens the listing in this tab.' }),
            );
            this.newTabInput = nt.input;

            this.settingsPage.appendChild(section('Links', [nt.row]));

            this.settingsPage.appendChild(
                section('Selling', [
                    note('The selling page has its own keys and settings.'),
                    el('button', {
                        type: 'button',
                        class: 'ttv2-link',
                        text: 'Open the selling page',
                        onclick: guarded(this, 'Sell', () => this.handlers.onOpenSelling && this.handlers.onOpenSelling()),
                    }),
                ]),
            );
        }

        /**
         * Torn's API Terms of Service require any tool that takes a key to state,
         * in this table form and where the key is entered, how it uses the key.
         */
        buildTosTable() {
            const rows = [
                ['Data storage', 'Only locally, in this browser'],
                ['Data sharing', 'Nobody'],
                ['Purpose of use', 'Competitive advantage: finding Bazaar and Item Market listings below NPC or market value'],
                ['Key storage & sharing', 'Stored locally / Not shared'],
                [
                    'Key access level',
                    'Public (torn: items, cityshops; market: itemmarket; key: info; user: profile, for bazaar owners\' public status)',
                ],
                [
                    'Other services',
                    'TornW3B (weav3r.dev) for bazaar prices. It receives item ids only, never your key.',
                ],
            ];

            const table = el('table', { class: 'ttv2-tos' });
            for (const [k, v] of rows) {
                table.appendChild(el('tr', {}, [el('th', { text: k }), el('td', { text: v })]));
            }

            return el('div', {}, [table]);
        }

        /**
         * Reflect key status without ever showing the key itself.
         * @param {object} info - { hasKey, accessName, overScoped }
         */
        setKeyState({ hasKey, accessName, overScoped }) {
            const had = this.hasKey;
            this.hasKey = Boolean(hasKey);
            if (!this.keyStateEl) return;

            // Terms expanded while there is no key; folded (still one click
            // away, right under the field) once one is saved.
            if (this.tosEl && had !== this.hasKey) this.tosEl.open = !this.hasKey;

            this.keyStateEl.classList.remove('ttv2-ok', 'ttv2-bad');

            if (!hasKey) {
                this.keyStateEl.textContent = 'No key saved.';
                return;
            }

            if (overScoped) {
                this.keyStateEl.textContent =
                    'Saved. This key has ' + (accessName || 'more than Public') + ' access; Public is enough.';
                this.keyStateEl.classList.add('ttv2-bad');
                return;
            }

            this.keyStateEl.textContent = accessName ? 'Saved · ' + accessName + ' access.' : 'Saved.';
            this.keyStateEl.classList.add('ttv2-ok');
        }

        emitSettings(partial) {
            this.state.settings = { ...this.state.settings, ...partial };
            this.syncChips();
            if (this.handlers.onSettingsChange) this.handlers.onSettingsChange(partial);
        }

        /* ------------------------------------------------------------- chrome */

        /**
         * Drag by the header; the position is remembered. A press that does not
         * move is a click: on a collapsed panel it expands it.
         */
        enableDrag(handle) {
            let start = null;

            handle.style.touchAction = 'none';

            handle.addEventListener('pointerdown', (event) => {
                if (event.button !== 0) return;
                if (event.target.closest && event.target.closest('button, a, input')) return;

                const rect = this.root.getBoundingClientRect();
                start = { x: event.clientX, y: event.clientY, left: rect.left, top: rect.top, moved: false };
                handle.setPointerCapture(event.pointerId);
            });

            handle.addEventListener('pointermove', (event) => {
                if (!start) return;

                const dx = event.clientX - start.x;
                const dy = event.clientY - start.y;
                if (!start.moved && Math.abs(dx) + Math.abs(dy) < 4) return;

                start.moved = true;
                this.placeAt(start.left + dx, start.top + dy);
            });

            const end = (event) => {
                if (!start) return;
                const { moved } = start;
                start = null;

                if (handle.hasPointerCapture && handle.hasPointerCapture(event.pointerId)) {
                    handle.releasePointerCapture(event.pointerId);
                }

                if (moved) {
                    const rect = this.root.getBoundingClientRect();
                    this.emitSettings({ panelPos: { left: Math.round(rect.left), top: Math.round(rect.top) } });
                } else if (this.collapsed) {
                    this.setCollapsed(false, { save: true });
                }
            };

            handle.addEventListener('pointerup', end);
            handle.addEventListener('pointercancel', end);
        }

        /** Put the panel's top-left corner here, kept fully on screen. */
        placeAt(left, top) {
            const rect = this.root.getBoundingClientRect();
            const maxLeft = Math.max(0, window.innerWidth - rect.width);
            const maxTop = Math.max(0, window.innerHeight - Math.min(rect.height, 60));

            this.root.style.left = Math.min(Math.max(0, left), maxLeft) + 'px';
            this.root.style.top = Math.min(Math.max(0, top), maxTop) + 'px';
            this.root.style.right = 'auto';
            this.root.style.bottom = 'auto';
        }

        /** Restore a saved position, or the default bottom-right corner. */
        applyPosition(pos) {
            if (!this.root) return;

            if (pos && Number.isFinite(pos.left) && Number.isFinite(pos.top)) {
                this.placeAt(pos.left, pos.top);
                return;
            }

            this.root.style.left = '';
            this.root.style.top = '';
            this.root.style.right = '';
            this.root.style.bottom = '';
        }

        clampIntoView() {
            if (!this.root || !this.root.style.left) return;
            const rect = this.root.getBoundingClientRect();
            this.placeAt(rect.left, rect.top);
        }

        setCollapsed(collapsed, { save = false } = {}) {
            this.collapsed = Boolean(collapsed);
            if (!this.root) return;

            this.root.classList.toggle('ttv2-collapsed', this.collapsed);
            this.collapseBtn.textContent = this.collapsed ? '+' : '–';
            this.collapseBtn.setAttribute('aria-label', this.collapsed ? 'Expand' : 'Collapse');
            this.collapseBtn.title = (this.collapsed ? 'Expand' : 'Collapse') + ' (`)';

            this.renderBar();
            this.clampIntoView();

            if (save && this.handlers.onSettingsChange) {
                this.handlers.onSettingsChange({ collapsed: this.collapsed });
            }
        }

        toggleCollapsed() {
            this.setCollapsed(!this.collapsed, { save: true });
        }

        /**
         * The bazaar owner line. null hides it.
         * @param {{name: string|null, level: string, text: string, closed: boolean}|null} info
         */
        setSeller(info) {
            if (!this.sellerEl) return;
            this.sellerEl.textContent = '';
            this.sellerEl.classList.toggle('ttv2-shown', Boolean(info));
            if (!info) return;

            this.sellerEl.appendChild(document.createTextNode('Seller: '));
            this.sellerEl.appendChild(el('b', { text: info.name || 'this bazaar' }));
            this.sellerEl.appendChild(this.statusWord(info.level, info.text));
            if (info.closed) {
                this.sellerEl.appendChild(el('span', { class: 'ttv2-closed', text: 'Bazaar closed' }));
            }
            this.sellerEl.title = this.sellerEl.textContent;
        }

        /**
         * ` shows and hides the panel, from anywhere on the page - except while
         * typing (chat, search, quantity boxes, our own fields), and never with
         * Ctrl / Alt / Cmd held.
         */
        enableHotkey(target = document) {
            if (this.hotkeyHandler) return;
            this.hotkeyHandler = (event) => {
                if (event.key !== '`' || event.repeat) return;
                if (event.ctrlKey || event.altKey || event.metaKey) return;
                if (isTypingTarget(event)) return;
                if (!this.root) return;
                event.preventDefault();
                this.setCollapsed(!this.collapsed, { save: true });
            };
            this.hotkeyTarget = target;
            target.addEventListener('keydown', this.hotkeyHandler);
        }

        /**
         * Play the scan animation: the Scan button pulses and a line sweeps
         * under the header. Restarts if a scan lands mid-animation.
         *
         * @param {string} [message] - result line for the status bar
         */
        showScan(message) {
            if (!this.root) return;

            this.root.classList.remove('ttv2-scanning');
            // Force a reflow so the CSS animation starts over.
            void this.root.offsetWidth;
            this.root.classList.add('ttv2-scanning');

            clearTimeout(this.scanTimer);
            this.scanTimer = setTimeout(() => {
                if (this.root) this.root.classList.remove('ttv2-scanning');
            }, SCAN_ANIMATION_MS);

            if (message) this.setStatus(message);
        }

        setBusy(busy) {
            this.state.busy = Boolean(busy);
            if (!this.refreshBtn) return;

            this.refreshBtn.disabled = this.state.busy;
            this.refreshBtn.classList.toggle('ttv2-spin', this.state.busy);
            this.refreshBtn.title = this.state.busy ? 'Refreshing' : 'Refresh now';
            this.renderBar();
        }

        /**
         * A message for the status line. Info clears itself after a few seconds
         * and gives the line back to the summary; warnings and errors stay until
         * replaced.
         */
        setStatus(text, level = 'info') {
            this.state.status = { text: text || '', level, at: Date.now() };
            this.renderBar();
        }

        applySettings(settings) {
            this.state.settings = { ...this.state.settings, ...settings };
            if (!this.root) return;

            this.syncChips();

            if (this.liveFeedInput && settings.liveFeed !== undefined) {
                this.liveFeedInput.checked = Boolean(settings.liveFeed);
            }
            if (this.useW3bInput && settings.useW3b !== undefined) {
                this.useW3bInput.checked = Boolean(settings.useW3b);
            }
            if (this.newTabInput && settings.openInNewTab !== undefined) {
                this.newTabInput.checked = settings.openInNewTab !== false;
            }
            if (settings.collapsed !== undefined) this.setCollapsed(settings.collapsed);
            if (settings.panelPos !== undefined) this.applyPosition(settings.panelPos);
        }

        syncChips() {
            const s = this.state.settings;
            if (!this.chipNpc) return;

            this.chipNpc.setAttribute('aria-pressed', String(s.sellToNpc !== false));
            this.chipBazaar.setAttribute('aria-pressed', String(Boolean(s.resaleBazaar)));
            this.chipMarket.setAttribute('aria-pressed', String(Boolean(s.resaleMarket)));
            this.chipMin.textContent = this.chipMin.labelFor(s.minTotalProfit);
            this.chipCash.textContent = this.chipCash.labelFor(s.cashOnHand);
            this.chipCash.classList.toggle('ttv2-chip-set', Boolean(s.cashOnHand));
            this.chipMin.classList.toggle('ttv2-chip-set', Number(s.minTotalProfit) > 1);
        }

        /* ------------------------------------------------------------ render */

        render(view) {
            Object.assign(this.state, view);
            if (!this.root) return;

            this.listEl.textContent = '';

            const rows = this.state.rows || [];

            if (rows.length === 0) {
                this.listEl.appendChild(this.renderEmpty());
            } else {
                this.listEl.appendChild(this.colsEl);
                rows.forEach((row) => {
                    this.listEl.appendChild(this.renderRow(row));
                });
            }

            this.renderTabs();
            this.refreshAges();
        }

        renderTabs() {
            const tab = this.state.tab || 'bazaar';
            const counts = this.state.counts || {};

            for (const [key, btn] of Object.entries(this.tabBtns || {})) {
                const on = key === tab;
                btn.classList.toggle('ttv2-tab-on', on);
                btn.setAttribute('aria-selected', String(on));
                btn.textContent = btn.dataset.label + (counts[key] ? ' (' + counts[key] + ')' : '');
            }

            if (this.creditEl) {
                const live = this.state.live;
                this.creditEl.style.display = tab === 'bazaar' && live && live.w3b ? '' : 'none';
            }
        }

        /**
         * The one status line. Left: this list's deals and total - or a message.
         * Right: whether watching is live, and when it next refreshes.
         */
        renderBar() {
            if (!this.barEl) return;

            const now = Date.now();
            const st = this.state.status || {};
            const summary = this.state.summary || { count: 0, totalProfit: 0 };
            const headline =
                (summary.count === 1 ? '1 deal' : summary.count + ' deals') +
                ' · +' + formatMoneyShort(summary.totalProfit);

            const showMessage =
                st.text &&
                (st.level !== 'info' || this.state.busy || now - st.at < INFO_STATUS_MS);

            this.barLeft.textContent = showMessage ? st.text : headline;
            this.barLeft.title = showMessage
                ? st.text
                : summary.capped
                  ? 'Total for what your cash buys, best deals first'
                  : '';
            this.barEl.classList.toggle('ttv2-warn', showMessage && st.level === 'warn');
            this.barEl.classList.toggle('ttv2-error', showMessage && st.level === 'error');

            // Collapsed: the headline rides in the header.
            this.miniEl.textContent = this.collapsed ? '· ' + headline : '';

            /* ---- liveness ---- */
            const live = this.state.live;
            let dot = 'off';
            let text = 'watching off';
            let title = 'Watching is off. Turn it on under Settings.';

            if (live && live.enabled) {
                if (!live.itemMarket) {
                    dot = 'warn';
                    text = 'needs key';
                    title = 'Add a Public API key under Settings.';
                } else if (live.leading) {
                    dot = live.lastError ? 'warn' : 'live';
                    const secs = live.nextRefreshAt
                        ? Math.max(0, Math.ceil((live.nextRefreshAt - now) / 1000))
                        : null;
                    text = 'live' + (secs !== null ? ' · ' + secs + 's' : '');
                    title = live.lastError || 'Refreshes every 30 seconds.';
                } else {
                    dot = 'other';
                    text = 'live in another tab';
                    title = 'Another visible Torn tab is watching. Results show here too.';
                }
            }

            this.barRight.textContent = '';
            this.barRight.appendChild(el('span', { class: 'ttv2-dot ttv2-dot-' + dot }));
            this.barRight.appendChild(document.createTextNode(text));
            this.barRight.title = title;
        }

        /**
         * An empty list says why, and offers the one thing that would help -
         * never a dead end.
         */
        renderEmpty() {
            const d = this.state.diagnostics;
            const live = this.state.live;
            const tab = this.state.tab;

            const box = (text, label, fn) => {
                const children = [el('div', { class: 'ttv2-empty-text', text })];
                if (label) {
                    children.push(
                        el('button', { type: 'button', class: 'ttv2-primary', text: label, onclick: fn }),
                    );
                }
                return el('div', { class: 'ttv2-empty' }, children);
            };

            if (!this.hasKey) {
                return box('Add a Public API key to start.', 'Add key', () =>
                    this.showPage('settings', { focusKey: true }),
                );
            }

            if (!d && tab === 'bazaar' && live && !live.w3b) {
                return box('Bazaar watching is off.', 'Turn it on', () =>
                    this.emitSettings({ useW3b: true, liveFeed: true }),
                );
            }

            if (!d && live && !live.enabled) {
                return box('Watching is off. Only this page is scanned.', 'Turn it on', () =>
                    this.emitSettings({ liveFeed: true }),
                );
            }

            const s = this.state.settings;

            if (s.sellToNpc === false && !s.resaleBazaar && !s.resaleMarket) {
                return box('Pick where to sell first.', 'Sell to NPC', () =>
                    this.emitSettings({ sellToNpc: true }),
                );
            }

            const why = this.filterReason();
            if (why) return box(why.text, why.label, why.fn);

            return box(this.emptyReason(), 'Refresh now', () =>
                this.handlers.onScan && this.handlers.onScan(),
            );
        }

        /**
         * An empty list because of Cash / Min, said plainly - with the return
         * the two together demand. $1m cash and a $1m Min means doubling your
         * money, which almost never happens, and the list must say so rather
         * than look broken.
         */
        filterReason() {
            const s = this.state.settings || {};
            const h = this.state.hidden || {};
            const cash = Number(s.cashOnHand) || 0;
            const min = Number(s.minTotalProfit) || 0;
            const lines = [];

            if (h.cash) {
                lines.push(
                    h.cash + (h.cash === 1 ? ' deal' : ' deals') + ' hidden: ' +
                        formatMoneyShort(cash) + ' cash cannot buy enough.',
                );
            }
            if (h.min) {
                lines.push(
                    h.min + (h.min === 1 ? ' deal makes' : ' deals make') + ' less than your Min of ' +
                        formatMoneyShort(min) + '.',
                );
            }
            if (cash > 0 && min > 1 && min / cash >= 0.2) {
                lines.push(
                    'A ' + formatMoneyShort(min) + ' Min on ' + formatMoneyShort(cash) + ' cash needs a ' +
                        Math.round((min / cash) * 100) + '% return.',
                );
            }
            if (!lines.length) return null;

            if (min > 1) {
                return { text: lines.join(' '), label: 'Set Min to $1', fn: () => this.emitSettings({ minTotalProfit: 1 }) };
            }
            return { text: lines.join(' '), label: 'Clear cash', fn: () => this.emitSettings({ cashOnHand: null }) };
        }

        emptyReason() {
            const d = this.state.diagnostics;
            const live = this.state.live;
            const tab = this.state.tab;

            if (!d) {
                if (live && live.enabled && live.leading) {
                    return tab === 'bazaar'
                        ? 'Watching bazaars. Nothing profitable right now.'
                        : 'Watching the Item Market. Nothing profitable right now.';
                }
                if (live && live.enabled) {
                    return 'Watching runs in another Torn tab. Results show here.';
                }
                return 'Nothing yet.';
            }

            if (d.images === 0) {
                return 'No item images found on this page.';
            }

            if (d.listings === 0 && d.cards > 0) {
                if (d.noItem === d.cards) {
                    return d.cards + ' listings found, none in the item database.';
                }
                return d.cards + ' listings found, no price readable.';
            }

            if (d.priceAssumed > 0) {
                return 'Nothing above Min. ' + d.priceAssumed + ' rows hidden: price guessed.';
            }

            return tab === 'bazaar'
                ? 'No bazaar deals right now.'
                : 'No Item Market deals right now.';
        }

        /**
         * One deal, two lines:
         *
         *     Xanax ×390                                       +$11,255
         *     $838,745 → NPC $850,000 · Garrett89 ● Offline 3h      40s
         *                                                          [Go]
         *
         * Everything goes in through textContent; names from Torn or TornW3B
         * never touch innerHTML.
         */
        renderRow(row) {
            const p = row.profit;
            const venue = VENUE_LABELS[p.venue] || p.venue;
            const known = row.qtyAtPrice !== false;

            /* ---- line 1: name ×qty, profit ---- */
            const name = el('div', { class: 'ttv2-row-name' }, [
                document.createTextNode(row.name),
                known && (p.affordableQty > 1 || p.affordableQty < p.qty)
                    ? el('span', {
                          class: 'ttv2-qty',
                          text: '×' + p.affordableQty.toLocaleString('en-US') +
                              (p.affordableQty < p.qty ? ' of ' + p.qty.toLocaleString('en-US') : ''),
                      })
                    : null,
            ]);

            // The age sits under the profit, so the details line keeps its room.
            const profit = el('div', {
                class: 'ttv2-row-profit ttv2-money',
                title: formatMoney(p.profitPerUnit) + ' each · ROI ' + formatPct(p.roi),
            }, [
                document.createTextNode('+' + formatMoney(known ? p.realizableProfit : p.profitPerUnit) + (known ? '' : ' each')),
                el('span', { class: 'ttv2-per' }, [row.el ? 'on this page' : el('span', { class: 'ttv2-age' })]),
            ]);

            /* ---- line 2: prices, seller, age ---- */
            const details = el('div', { class: 'ttv2-row-details' });
            const sep = () => document.createTextNode(' · ');

            details.appendChild(el('b', { text: formatMoney(p.listingPrice) }));
            if (row.priceAssumed) {
                details.appendChild(el('span', {
                    class: 'ttv2-guess',
                    title: 'More than one price on the card. The lowest was taken.',
                    text: '?',
                }));
            }
            details.appendChild(document.createTextNode(' → ' + venue + ' '));
            details.appendChild(el('b', { text: formatMoney(p.exitPrice) }));

            if (row.source === 'bazaar') {
                const statuses = this.state.statuses;
                const status = statuses && row.sellerId ? statuses.get(String(row.sellerId)) : null;
                const sellerName = row.sellerName || (status && status.name) || null;
                if (sellerName) {
                    details.appendChild(sep());
                    details.appendChild(el('b', { text: sellerName }));
                    if (status) {
                        const word = this.statusWord(status.level, status.text);
                        word.title = (sellerName ? sellerName + ': ' : '') + status.title;
                        details.appendChild(word);
                    }
                }
            }

            if (!known) {
                details.appendChild(sep());
                details.appendChild(el('span', {
                    class: 'ttv2-guess',
                    title: 'Torn shows only the cheapest price. Open the item for stock.',
                    text: 'qty unknown',
                }));
            }

            /* ---- the one action ---- */
            const go = el('button', {
                type: 'button',
                class: 'ttv2-go',
                title: row.el
                    ? 'Scroll to this listing'
                    : row.source === 'bazaar'
                      ? 'Open this bazaar'
                      : 'Open on the Item Market',
                text: row.el ? 'Show' : 'Go',
                onclick: () => this.handlers.onNavigate && this.handlers.onNavigate(row),
            });

            const rowEl = el('div', { class: 'ttv2-row' }, [name, profit, details, go]);
            rowEl.dataset.ttv2At = String(this.rowTime(row) || '');
            if (row.el) rowEl.classList.add('ttv2-onpage');

            return rowEl;
        }

        /** "● Online" for a player: an 8px dot and a word. */
        statusWord(level, text) {
            const word = el('span', { class: 'ttv2-status', text: text || '' });
            word.dataset.level = level || 'unknown';
            return word;
        }

        /** When the data behind a row was true - not when we last looked. */
        rowTime(row) {
            if (row.fromFeed) return row.dataAt;
            return row.seenAt || null;
        }

        refreshAges() {
            if (!this.root) return;

            const now = Date.now();

            // Just the age. Nothing is greyed out: a listing the latest refresh
            // did not confirm is removed, not faded.
            for (const rowEl of this.listEl.querySelectorAll('.ttv2-row')) {
                const at = Number(rowEl.dataset.ttv2At);
                const ageEl = rowEl.querySelector('.ttv2-age');
                const known = Number.isFinite(at) && at > 0;
                if (ageEl) ageEl.textContent = known ? formatAge(now - at).replace(' ago', '') : 'age unknown';
            }

            this.renderBar();
        }

        /* --------------------------------------------------------- my bazaar */

        /**
         * Your own bazaar's add / manage page: every item found in its rows,
         * what it is going for now, and the selected item's record.
         *
         * @param {object|null} view - null leaves the page (back to the list)
         *   items: [{itemId, name, im: {price, at}|null, bz: {price, at}|null}]
         *   selected: itemId | null
         *   marketValue: number | null
         *   averages: from core/history.js averages()
         *   series: from core/history.js series()
         *   windowKey: '24h' | '7d' | '30d'
         *   since: timestamp of the first record, or null
         *   diagnostics: { page, rows, identified }
         */
        renderMyBazaar(view) {
            this.state.bazaar = view;
            if (!this.root) return;

            if (!view) {
                if (this.page === 'mybazaar') this.showPage('list');
                return;
            }
            if (this.page === 'list') this.showPage('mybazaar');

            const list = this.bzListEl;
            list.textContent = '';

            if (!view.items.length) {
                list.appendChild(el('div', { class: 'ttv2-note', text: 'No items found on this page yet.' }));
            } else {
                list.appendChild(el('div', { class: 'ttv2-bzrow' }, [
                    el('span', { class: 'ttv2-label', text: 'Item' }),
                    el('span', { class: 'ttv2-label ttv2-money', text: 'Item Market' }),
                    el('span', { class: 'ttv2-label ttv2-money', text: 'Bazaars' }),
                ]));
                for (const it of view.items) {
                    const btn = el('button', {
                        type: 'button',
                        class: 'ttv2-bzrow',
                        'aria-pressed': String(it.itemId === view.selected),
                        title: 'Show averages and graph',
                        onclick: () => this.handlers.onSelectBazaarItem && this.handlers.onSelectBazaarItem(it.itemId),
                    }, [
                        el('span', { class: 'ttv2-name', text: it.name }),
                        el('span', { class: 'ttv2-money', text: priceText(it.im) || '…' }),
                        el('span', { class: 'ttv2-money', text: priceText(it.bz) || '…' }),
                    ]);
                    list.appendChild(btn);
                }
            }

            const detail = this.bzDetailEl;
            detail.textContent = '';
            const sel = view.items.find((i) => i.itemId === view.selected);
            if (!sel) {
                detail.appendChild(el('div', { class: 'ttv2-note', text: 'Lowest asking prices now. Pick an item for its record.' }));
                return;
            }

            detail.appendChild(el('h3', { text: sel.name }));

            const now = el('div', { class: 'ttv2-note' }, [
                'Lowest now: Item Market ',
                el('b', { text: priceText(sel.im) || 'unknown' }),
                sel.im && sel.im.at ? ' (' + formatAge(Date.now() - sel.im.at) + ')' : '',
                ', bazaars ',
                el('b', { text: priceText(sel.bz) || 'unknown' }),
                sel.bz && sel.bz.at ? ' (' + formatAge(Date.now() - sel.bz.at) + ')' : '',
                '.',
            ]);
            detail.appendChild(now);

            detail.appendChild(el('div', { class: 'ttv2-note' }, [
                'Market value ',
                el('b', { text: view.marketValue ? formatMoney(view.marketValue) : 'unknown' }),
                ' (Torn, daily sales average).',
            ]));

            /* averages */
            const table = el('table', { class: 'ttv2-avg' });
            table.appendChild(el('tr', {}, [
                el('th', { class: 'ttv2-label', text: 'Average' }),
                el('th', { class: 'ttv2-label ttv2-money', text: 'Item Market' }),
                el('th', { class: 'ttv2-label ttv2-money', text: 'Bazaars' }),
                el('th', { class: 'ttv2-label ttv2-money', text: 'Recorded' }),
            ]));
            const avgs = view.averages || {};
            for (const w of WINDOWS) {
                const a = avgs[w.key] || { im: null, bz: null, coverage: 0 };
                const none = a.coverage <= 0;
                table.appendChild(el('tr', {}, [
                    el('th', { text: w.label }),
                    el('td', { class: 'ttv2-money' + (a.im ? '' : ' ttv2-none'), text: a.im ? formatMoney(a.im) : 'no data' }),
                    el('td', { class: 'ttv2-money' + (a.bz ? '' : ' ttv2-none'), text: a.bz ? formatMoney(a.bz) : 'no data' }),
                    el('td', { class: 'ttv2-money' + (none ? ' ttv2-none' : ''), text: none ? '0%' : Math.round(a.coverage * 100) < 1 ? '<1%' : Math.round(a.coverage * 100) + '%' }),
                ]));
            }
            detail.appendChild(table);

            /* graph */
            const windows = el('div', { class: 'ttv2-windows' });
            for (const key of ['24h', '7d', '30d']) {
                windows.appendChild(el('button', {
                    type: 'button',
                    class: 'ttv2-window',
                    'aria-pressed': String(key === view.windowKey),
                    text: key,
                    onclick: () => this.handlers.onBazaarWindow && this.handlers.onBazaarWindow(key),
                }));
            }
            detail.appendChild(windows);

            if (view.series) detail.appendChild(renderPriceGraph(view.series, { width: 400, height: 96 }));
            detail.appendChild(el('div', { class: 'ttv2-graph-keys' }, [
                el('span', { class: 'ttv2-key-im', text: '— Item Market ask' }),
                el('span', { class: 'ttv2-key-bz', text: '— Bazaar ask' }),
                el('span', { class: 'ttv2-key-mv', text: '- - Market value' }),
            ]));

            const cov = avgs[view.windowKey] ? coverageText(avgs[view.windowKey].coverage, view.windowKey) : '0%';
            detail.appendChild(el('div', {
                class: 'ttv2-note',
                text: 'Asking prices this script recorded (' + cov + '). Sales are not published.',
            }));
        }

        destroy() {
            if (this.ticker) clearInterval(this.ticker);
            clearTimeout(this.scanTimer);
            if (this.hotkeyHandler && this.hotkeyTarget) {
                this.hotkeyTarget.removeEventListener('keydown', this.hotkeyHandler);
                this.hotkeyHandler = null;
            }
            if (this.host && this.host.parentNode) {
                this.host.parentNode.removeChild(this.host);
            }
            this.root = null;
        }
    }

    /* ===== src/ui/selling-page.js ===== */
    /*
     * The selling page: which trader pays most for each item you hold.
     *
     * Its own tab (index.php?ttv2=traders): a Torn page the user opened, drawn
     * over by the script. It reads only the API - your inventory with the
     * Limited key kept here (never the overlay's Public key), traders' prices
     * from TornExchange with the TornExchange key kept here - and never a Torn
     * page you are not on. Nothing is traded, listed or clicked for you.
     *
     * Every trader list is highest price first. "Online only" keeps only the
     * traders known to be online, still highest first. Clicking a trader offers
     * their Torn profile and their TornExchange price list. Names from Torn or
     * TornExchange only ever go in via textContent.
     */






    const SELLING_PAGE_DEFAULTS = {
        onlineOnly: false,
        /* Item order: 'item' = best single-item offer first; 'bundle' = qty x offer first. */
        sortBy: 'item',
        /* Profile and price-list links open a new tab. */
        linksNewTab: true,
    };

    function spEl(tag, props = {}, children = []) {
        const node = document.createElement(tag);
        for (const [key, value] of Object.entries(props)) {
            if (key === 'class') node.className = value;
            else if (key === 'text') node.textContent = value;
            else if (key.startsWith('on') && typeof value === 'function') {
                node.addEventListener(key.slice(2).toLowerCase(), value);
            } else if (value !== null && value !== undefined && value !== false) {
                node.setAttribute(key, String(value));
            }
        }
        for (const child of [].concat(children)) {
            if (child === null || child === undefined || child === false) continue;
            node.appendChild(typeof child === 'string' ? document.createTextNode(child) : child);
        }
        return node;
    }

    function spProfileUrl(id) {
        return 'https://www.torn.com/profiles.php?XID=' + encodeURIComponent(String(id));
    }

    /** A masked key field with Show / Save. The saved key is never left in the field. */
    function keyField(page, { placeholder, onSave, onReveal }) {
        const input = spEl('input', {
            type: 'text',
            class: 'sp-masked sp-key',
            placeholder,
            autocomplete: 'off',
            autocapitalize: 'off',
            autocorrect: 'off',
            spellcheck: 'false',
            'data-lpignore': 'true',
            'data-1p-ignore': 'true',
        });
        let revealed = false;
        const show = spEl('button', {
            type: 'button',
            class: 'sp-btn',
            text: 'Show',
            onclick: () => {
                const hidden = input.classList.toggle('sp-masked');
                show.textContent = hidden ? 'Show' : 'Hide';
                if (!hidden && !input.value && onReveal) {
                    input.value = onReveal() || '';
                    revealed = true;
                } else if (hidden && revealed) {
                    input.value = '';
                    revealed = false;
                }
            },
        });
        const save = () => {
            const key = input.value.trim();
            input.value = '';
            revealed = false;
            input.classList.add('sp-masked');
            show.textContent = 'Show';
            onSave(key);
        };
        input.addEventListener('keydown', (event) => {
            if (event.key !== 'Enter') return;
            event.preventDefault();
            save();
        });
        const saveBtn = spEl('button', { type: 'button', class: 'sp-btn sp-primary', text: 'Save', onclick: save });
        return { input, row: spEl('div', { class: 'sp-inline' }, [input, show, saveBtn]) };
    }

    class SellingPage {
        /**
         * @param {object} handlers
         *   onSaveKey(key), onForgetKey(), onRevealKey()
         *   onSaveTeKey(key), onForgetTeKey(), onRevealTeKey()
         *   onRefresh(), onPrefsChange(partial), onExpand(itemId)
         *   onOpenProfile(id), onOpenList(idOrName)
         */
        constructor(handlers = {}) {
            this.h = handlers;
            this.state = { rows: [], prefs: { ...SELLING_PAGE_DEFAULTS }, info: {}, expanded: new Set(), statuses: new Map() };
            this.view = 'list';
        }

        mount() {
            if (this.host) return;

            this.host = document.createElement('div');
            this.host.id = 'ttv2-sell-host';
            this.host.style.cssText = 'position:fixed;inset:0;z-index:2147482000;';
            const shadow = this.host.attachShadow({ mode: 'open' });
            shadow.appendChild(spEl('style', { text: SELLING_PAGE_CSS }));

            this.build();
            shadow.appendChild(this.root);
            document.documentElement.appendChild(this.host);

            // Torn's page underneath must not scroll behind this one.
            this.prevOverflow = document.documentElement.style.overflow;
            document.documentElement.style.overflow = 'hidden';

            this.keyHandler = (event) => {
                if (event.key === 'Escape' && this.view === 'settings') this.showView('list');
            };
            document.addEventListener('keydown', this.keyHandler);
            this.ticker = setInterval(() => this.renderBar(), 1000);
        }

        destroy() {
            if (this.keyHandler) document.removeEventListener('keydown', this.keyHandler);
            if (this.ticker) clearInterval(this.ticker);
            if (this.host && this.host.parentNode) this.host.parentNode.removeChild(this.host);
            document.documentElement.style.overflow = this.prevOverflow || '';
            this.host = null;
            this.root = null;
        }

        /* ------------------------------------------------------------ build */

        build() {
            const set = (partial) => this.h.onPrefsChange && this.h.onPrefsChange(partial);

            /* title bar */
            this.sortBtns = {};
            const sortBtn = (key, text, title) => {
                const btn = spEl('button', {
                    type: 'button',
                    class: 'sp-seg-btn',
                    'data-sort': key,
                    'aria-pressed': 'false',
                    title,
                    text,
                    onclick: () => set({ sortBy: key }),
                });
                this.sortBtns[key] = btn;
                return btn;
            };
            this.sortEl = spEl('div', { class: 'sp-seg', role: 'group', 'aria-label': 'Order items by' }, [
                sortBtn('item', 'Per item', 'Best offer for one, highest first'),
                sortBtn('bundle', 'Bundle', 'Quantity times best offer, highest first'),
            ]);
            this.onlineBtn = spEl('button', {
                type: 'button',
                class: 'sp-btn sp-toggle',
                'aria-pressed': 'false',
                title: 'Show only traders who are online',
                text: 'Online only',
                onclick: () => set({ onlineOnly: !this.state.prefs.onlineOnly }),
            });
            this.refreshBtn = spEl('button', {
                type: 'button',
                class: 'sp-icon',
                title: 'Refresh now',
                'aria-label': 'Refresh now',
                text: '↻',
                onclick: () => this.h.onRefresh && this.h.onRefresh(),
            });
            this.settingsBtn = spEl('button', {
                type: 'button',
                class: 'sp-icon',
                title: 'Settings',
                'aria-label': 'Settings',
                'aria-pressed': 'false',
                text: '⚙',
                onclick: () => this.showView(this.view === 'settings' ? 'list' : 'settings'),
            });
            this.backBtn = spEl('button', {
                type: 'button',
                class: 'sp-icon sp-back',
                title: 'Back (Esc)',
                'aria-label': 'Back',
                text: '←',
                onclick: () => this.showView('list'),
            });

            this.titleEl = spEl('h1', { text: 'Sell to traders' });
            this.toolsEl = spEl('div', { class: 'sp-tools' }, [this.sortEl, this.onlineBtn]);
            this.headEl = spEl('header', { class: 'sp-head' }, [
                this.backBtn,
                this.titleEl,
                spEl('span', { class: 'sp-grow' }),
                this.toolsEl,
                this.refreshBtn,
                this.settingsBtn,
            ]);

            /* status bar */
            this.barLeft = spEl('span', { class: 'sp-bar-left' });
            this.barRight = spEl('span', { class: 'sp-bar-right' });
            this.barEl = spEl('div', { class: 'sp-bar' }, [this.barLeft, this.barRight]);

            this.bannerEl = spEl('div', { class: 'sp-banner' });

            /* list */
            this.listEl = spEl('main', { class: 'sp-main' });

            /* settings */
            this.settingsEl = spEl('main', { class: 'sp-main sp-settings' });
            this.buildSettings();
            this.settingsEl.hidden = true;

            this.root = spEl('div', { class: 'sp-page' }, [
                this.headEl,
                this.barEl,
                this.bannerEl,
                this.listEl,
                this.settingsEl,
            ]);
        }

        buildSettings() {
            const section = (title, children) =>
                spEl('section', { class: 'sp-section' }, [spEl('h2', { class: 'sp-label', text: title }), ...children]);
            const note = (children) => spEl('div', { class: 'sp-note' }, children);

            /* Torn key (Limited) */
            const torn = keyField(this, {
                placeholder: 'Limited API key',
                onSave: (key) => this.h.onSaveKey && this.h.onSaveKey(key),
                onReveal: () => this.h.onRevealKey && this.h.onRevealKey(),
            });
            this.keyInput = torn.input;
            this.keyStateEl = spEl('div', { class: 'sp-keystate', text: 'No key saved.' });

            const tos = spEl('table', { class: 'sp-tos' });
            for (const [k, v] of [
                ['Data storage', 'Only locally, in this browser'],
                ['Data sharing', 'Nobody'],
                ['Purpose of use', 'Personal gain: pricing the items you hold against traders\' offers'],
                ['Key storage & sharing', 'Stored locally / Not shared'],
                [
                    'Key access level',
                    'Limited (user: inventory, your own items; torn: items, market values; user: profile, traders\' public status)',
                ],
                ['Other services', 'TornExchange (tornexchange.com), with the separate key below. This key never goes there.'],
            ]) {
                tos.appendChild(spEl('tr', {}, [spEl('th', { text: k }), spEl('td', { text: v })]));
            }
            this.tosEl = spEl('details', { class: 'sp-tos-box', open: '' }, [
                spEl('summary', { text: 'Key use (Torn API terms)' }),
                tos,
            ]);

            this.settingsEl.appendChild(
                section('Torn API key for this page', [
                    torn.row,
                    this.keyStateEl,
                    note([
                        'Limited access is needed to read your inventory. Make one at ',
                        spEl('a', { href: TORN_API_KEY_URL, target: '_blank', rel: 'noopener noreferrer', text: 'Torn › Settings › API Key' }),
                        '. Used on this page only.',
                    ]),
                    this.tosEl,
                    spEl('button', { type: 'button', class: 'sp-link', text: 'Forget key', onclick: () => this.h.onForgetKey && this.h.onForgetKey() }),
                ]),
            );

            /* TornExchange key */
            const te = keyField(this, {
                placeholder: 'TornExchange API key',
                onSave: (key) => this.h.onSaveTeKey && this.h.onSaveTeKey(key),
                onReveal: () => this.h.onRevealTeKey && this.h.onRevealTeKey(),
            });
            this.teKeyInput = te.input;
            this.teStateEl = spEl('div', { class: 'sp-keystate', text: 'No TornExchange key saved.' });

            this.settingsEl.appendChild(
                section('TornExchange API key', [
                    te.row,
                    this.teStateEl,
                    note([
                        'The API key from your ',
                        spEl('a', { href: TE_SITE_URL, target: '_blank', rel: 'noopener noreferrer', text: 'tornexchange.com' }),
                        ' account. Sent to tornexchange.com only, at most 6 calls a minute.',
                    ]),
                    spEl('button', { type: 'button', class: 'sp-link', text: 'Forget key', onclick: () => this.h.onForgetTeKey && this.h.onForgetTeKey() }),
                ]),
            );

            /* preferences */
            this.linksInput = spEl('input', { type: 'checkbox' });
            this.linksInput.addEventListener('change', () => this.h.onPrefsChange && this.h.onPrefsChange({ linksNewTab: this.linksInput.checked }));
            this.settingsEl.appendChild(
                section('Links', [
                    spEl('label', { class: 'sp-check' }, [this.linksInput, spEl('span', { text: 'Open links in a new tab' })]),
                ]),
            );
        }

        showView(view) {
            this.view = view === 'settings' ? 'settings' : 'list';
            if (!this.root) return;
            const settings = this.view === 'settings';
            this.settingsEl.hidden = !settings;
            this.listEl.hidden = settings;
            this.backBtn.hidden = !settings;
            this.settingsBtn.setAttribute('aria-pressed', String(settings));
            this.toolsEl.hidden = settings;
            this.titleEl.textContent = settings ? 'Settings' : 'Sell to traders';
            this.renderBanner();
        }

        openSettings() {
            this.showView('settings');
        }

        /* ----------------------------------------------------------- render */

        /**
         * @param {object} view
         *   rows       - buildSellingRows() output
         *   statuses   - Map traderId -> {level, text, title}
         *   prefs      - this page's preferences
         *   info       - { hasKey, keyAccess, keyError, hasTeKey, teError, teBadKey,
         *                  teWaitUntil, teAt, inventoryAt, loading, itemLists: Map }
         *   expanded   - Set of item ids whose traders are shown
         */
        render(view) {
            Object.assign(this.state, view);
            if (!this.root) return;

            const p = this.state.prefs;
            this.onlineBtn.setAttribute('aria-pressed', String(Boolean(p.onlineOnly)));
            const sortBy = p.sortBy === 'bundle' ? 'bundle' : 'item';
            for (const [key, btn] of Object.entries(this.sortBtns)) btn.setAttribute('aria-pressed', String(key === sortBy));
            this.linksInput.checked = p.linksNewTab !== false;

            this.renderKeyStates();
            this.renderBar();
            this.renderBanner();
            this.renderList();
        }

        renderKeyStates() {
            const info = this.state.info || {};

            this.keyStateEl.className = 'sp-keystate';
            if (!info.hasKey) {
                this.keyStateEl.textContent = 'No key saved.';
            } else if (info.keyError) {
                this.keyStateEl.textContent = info.keyError;
                this.keyStateEl.classList.add('sp-bad');
            } else {
                this.keyStateEl.textContent = 'Saved' + (info.keyAccess ? ' · ' + info.keyAccess + ' access' : '') + '.';
                this.keyStateEl.classList.add('sp-ok');
            }
            if (this.tosEl) this.tosEl.open = !info.hasKey;

            this.teStateEl.className = 'sp-keystate';
            if (!info.hasTeKey) {
                this.teStateEl.textContent = 'No TornExchange key saved.';
            } else if (info.teBadKey) {
                this.teStateEl.textContent = info.teError || 'TornExchange rejected this key.';
                this.teStateEl.classList.add('sp-bad');
            } else if (info.teAt) {
                this.teStateEl.textContent = 'Saved · prices ' + formatAge(Date.now() - info.teAt) + '.';
                this.teStateEl.classList.add('sp-ok');
            } else {
                this.teStateEl.textContent = info.teError || 'Saved.';
                if (info.teError) this.teStateEl.classList.add('sp-bad');
            }
        }

        renderBar() {
            if (!this.root) return;
            const rows = this.state.rows || [];
            const info = this.state.info || {};
            const withOffer = rows.filter((r) => r.total !== null);
            const total = withOffer.reduce((sum, r) => sum + r.total, 0);

            this.barLeft.textContent = info.loading
                ? 'Loading'
                : rows.length
                  ? rows.length + (rows.length === 1 ? ' item' : ' items') + ' · ' +
                    withOffer.length + ' with a buyer · ' + formatMoneyShort(total) + ' at best offers'
                  : '';

            const bits = [];
            if (info.inventoryAt) bits.push('inventory ' + formatAge(Date.now() - info.inventoryAt));
            if (info.teAt) bits.push('TE prices ' + formatAge(Date.now() - info.teAt));
            this.barRight.textContent = bits.join(' · ');
        }

        renderBanner() {
            const info = this.state.info || {};
            const b = this.bannerEl;
            b.textContent = '';
            b.className = 'sp-banner';

            const say = (text, level, label, fn) => {
                b.classList.add('sp-banner-on');
                if (level) b.classList.add('sp-banner-' + level);
                b.appendChild(spEl('span', { text }));
                if (label && this.view !== 'settings') b.appendChild(spEl('button', { type: 'button', class: 'sp-btn sp-primary', text: label, onclick: fn }));
            };
            const toSettings = () => this.showView('settings');

            if (!info.hasKey) {
                say('Add a Limited API key to read your inventory.', null, 'Add key', toSettings);
            } else if (info.keyError) {
                say(info.keyError, 'bad', 'Open Settings', toSettings);
            } else if (!info.hasTeKey) {
                say('Add your TornExchange API key to see traders.', null, 'Add key', toSettings);
            } else if (info.teBadKey) {
                say(info.teError || 'TornExchange rejected this key.', 'bad', 'Open Settings', toSettings);
            } else if (info.teWaitUntil && info.teWaitUntil > Date.now()) {
                say('TornExchange asked us to wait ' + formatAge(info.teWaitUntil - Date.now()).replace(' ago', '') + '.', 'warn');
            } else if (info.teError) {
                say(info.teError, 'warn');
            } else if (info.error) {
                say(info.error, 'bad');
            }
        }

        renderList() {
            const list = this.listEl;
            list.textContent = '';
            const rows = this.state.rows || [];
            const info = this.state.info || {};
            const p = this.state.prefs;

            if (!rows.length) {
                let text = 'Nothing to show yet.';
                if (info.loading) text = 'Loading your inventory.';
                else if (info.checkingOnline) text = 'Checking who\'s online…';
                else if (info.inventoryAt && p.onlineOnly) text = 'No online trader buys anything you hold.';
                else if (info.inventoryAt) text = 'Nothing sellable in your inventory.';
                list.appendChild(spEl('div', { class: 'sp-empty', text }));
                return;
            }

            const table = spEl('table', { class: 'sp-table' });
            table.appendChild(spEl('thead', {}, [
                spEl('tr', {}, [
                    spEl('th', { class: 'sp-label', text: 'Item' }),
                    spEl('th', { class: 'sp-label sp-money', text: 'Qty' }),
                    spEl('th', { class: 'sp-label sp-money', text: 'Best offer' }),
                    spEl('th', { class: 'sp-label', text: 'Trader' }),
                    spEl('th', { class: 'sp-label sp-money', text: 'Market value' }),
                    spEl('th', { class: 'sp-label sp-money', text: 'Traders avg' }),
                    spEl('th', { class: 'sp-label sp-money', text: 'Total' }),
                ]),
            ]));

            const body = spEl('tbody');
            for (const r of rows) {
                body.appendChild(this.renderRow(r));
                if (this.state.expanded.has(r.itemId)) body.appendChild(this.renderTraders(r));
            }
            table.appendChild(body);
            list.appendChild(table);
        }

        renderRow(r) {
            const open = this.state.expanded.has(r.itemId);
            const best = r.best;
            const tr = spEl('tr', {
                class: 'sp-row' + (open ? ' sp-open' : '') + (best ? '' : ' sp-nobuyer'),
                tabindex: '0',
                'aria-expanded': String(open),
                title: open ? 'Hide traders' : 'Show every trader who buys it',
                onclick: () => this.h.onExpand && this.h.onExpand(r.itemId),
                onkeydown: (event) => {
                    if (event.key === 'Enter' || event.key === ' ') {
                        event.preventDefault();
                        if (this.h.onExpand) this.h.onExpand(r.itemId);
                    }
                },
            }, [
                spEl('td', { class: 'sp-item', 'data-qty': r.qty.toLocaleString('en-US') }, [spEl('b', { text: r.name })]),
                spEl('td', { class: 'sp-money', text: r.qty.toLocaleString('en-US') }),
                spEl('td', { class: 'sp-money sp-offer', text: best ? formatMoney(best.trader.price) : '–' }),
                spEl('td', { class: 'sp-trader' }, best ? [spEl('b', { text: best.trader.name }), this.statusWord(best)] : [spEl('span', { class: 'sp-muted', text: 'No buyer on TE' })]),
                spEl('td', { class: 'sp-money', text: r.marketValue ? formatMoney(r.marketValue) : '–' }),
                spEl('td', { class: 'sp-money', title: r.avgPartial ? 'Top three buyers only' : 'All ' + r.buyers + ' buyers' }, [
                    document.createTextNode(r.tradersAvg ? formatMoney(r.tradersAvg) : '–'),
                    r.tradersAvg && r.avgPartial ? spEl('span', { class: 'sp-muted sp-small', text: ' top 3' }) : null,
                ]),
                spEl('td', { class: 'sp-money sp-total', text: r.total !== null ? formatMoney(r.total) : '–' }),
            ]);
            return tr;
        }

        /** Every trader who buys the item, highest first, with profile and list links. */
        renderTraders(r) {
            const info = this.state.info || {};
            const lists = info.itemLists || new Map();
            const st = lists.get(r.itemId) || {};
            const p = this.state.prefs;

            const box = spEl('div', { class: 'sp-traders' });

            if (st.loading) box.appendChild(spEl('div', { class: 'sp-note', text: 'Loading every buyer from TornExchange.' }));
            else if (st.error) box.appendChild(spEl('div', { class: 'sp-note sp-bad', text: st.error }));
            else if (r.avgPartial) box.appendChild(spEl('div', { class: 'sp-note', text: 'Top three buyers. The full list loads next.' }));

            if (!r.offers.length) {
                box.appendChild(spEl('div', { class: 'sp-note', text: p.onlineOnly ? 'No online trader buys this.' : 'No trader buys this.' }));
            }

            for (const o of r.offers) {
                const t = o.trader;
                const links = spEl('span', { class: 'sp-links' });
                if (t.id) {
                    const a = spEl('a', { class: 'sp-link', href: spProfileUrl(t.id), text: 'Profile' });
                    a.addEventListener('click', (event) => {
                        if (event.button !== 0 || event.ctrlKey || event.metaKey || event.shiftKey) return;
                        event.preventDefault();
                        if (this.h.onOpenProfile) this.h.onOpenProfile(t.id);
                    });
                    links.appendChild(a);
                }
                const list = spEl('a', {
                    class: 'sp-link',
                    href: TE_SITE_URL + '/prices/' + encodeURIComponent(String(t.id || t.name)) + '/',
                    text: 'TE list',
                });
                list.addEventListener('click', (event) => {
                    if (event.button !== 0 || event.ctrlKey || event.metaKey || event.shiftKey) return;
                    event.preventDefault();
                    if (this.h.onOpenList) this.h.onOpenList(t.id || t.name);
                });
                links.appendChild(list);

                box.appendChild(spEl('div', { class: 'sp-tr' }, [
                    spEl('span', { class: 'sp-tname' }, [spEl('b', { text: t.name }), this.statusWord(o)]),
                    spEl('span', { class: 'sp-money sp-offer', text: formatMoney(t.price) }),
                    spEl('span', { class: 'sp-money sp-muted', text: formatMoney(t.price * r.qty) }),
                    links,
                ]));
            }

            return spEl('tr', { class: 'sp-expanded' }, [spEl('td', { colspan: '7' }, [box])]);
        }

        /** "● Online" for a trader, from the known statuses. */
        statusWord(offer) {
            const t = offer.trader;
            const status = t.id && this.state.statuses ? this.state.statuses.get(String(t.id)) : null;
            const word = spEl('span', {
                class: 'sp-status',
                title: status ? t.name + ': ' + status.title : t.id ? 'Status not checked yet' : 'No Torn id on TornExchange',
                text: status ? status.text : t.id ? 'checking' : 'unknown',
            });
            word.dataset.level = status ? status.level : 'unknown';
            return word;
        }
    }

    const SELLING_PAGE_CSS = `
    :host { all: initial; }
    * { box-sizing: border-box; }
    .sp-page {
    ${TOKENS_CSS}
        position: absolute; inset: 0; display: flex; flex-direction: column;
        background: var(--bg); color: var(--text);
        font: 13px/1.4 Arial, Helvetica, sans-serif;
    }
    button, input { font: inherit; color: inherit; }
    a { color: var(--offer); text-decoration: none; }
    a:hover { text-decoration: underline; }
    b { font-weight: bold; }
    [hidden] { display: none !important; }
    .sp-grow { flex: 1; }
    .sp-muted { color: var(--muted); }
    .sp-bad { color: var(--bad); }
    .sp-ok { color: var(--profit); }
    .sp-small { font-size: 12px; }
    .sp-money { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
    .sp-label {
        font-size: 11px; font-weight: bold; letter-spacing: 0.5px; text-transform: uppercase; color: var(--muted);
    }

    .sp-head {
        display: flex; align-items: center; gap: 8px; height: 30px; flex: 0 0 auto;
        padding: 0 8px 0 16px; background: var(--title); border-bottom: 1px solid var(--line);
    }
    .sp-head h1 {
        margin: 0; font-size: 20px; font-weight: bold; letter-spacing: 1px; color: #fff;
        text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.65); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    }
    .sp-btn {
        height: 28px; padding: 0 12px; font-size: 12px; font-weight: bold; color: var(--text);
        background: var(--line); border: 1px solid var(--line); border-radius: 4px; cursor: pointer; white-space: nowrap;
    }
    .sp-btn:hover { border-color: var(--muted); }
    .sp-btn.sp-primary { color: var(--on-profit); background: var(--profit); border-color: var(--profit); }
    .sp-btn.sp-toggle { height: 24px; background: transparent; color: var(--muted); }
    .sp-btn.sp-toggle[aria-pressed="true"] { color: var(--text); border-color: var(--profit); background: rgba(153, 204, 0, 0.12); }
    .sp-tools { display: flex; align-items: center; gap: 8px; }
    .sp-seg { display: inline-flex; height: 24px; border: 1px solid var(--line); border-radius: 4px; overflow: hidden; }
    .sp-seg-btn {
        height: 22px; padding: 0 12px; font-size: 12px; font-weight: bold; color: var(--muted);
        background: transparent; border: 0; cursor: pointer; white-space: nowrap;
    }
    .sp-seg-btn + .sp-seg-btn { border-left: 1px solid var(--line); }
    .sp-seg-btn:hover { color: var(--text); }
    .sp-seg-btn[aria-pressed="true"] { color: var(--text); background: rgba(153, 204, 0, 0.12); box-shadow: inset 0 -2px 0 var(--profit); }
    .sp-icon {
        width: 24px; height: 24px; padding: 0; font-size: 15px; line-height: 22px; text-align: center;
        color: var(--text); background: transparent; border: 1px solid transparent; border-radius: 4px; cursor: pointer;
    }
    .sp-icon:hover { background: rgba(255, 255, 255, 0.08); }
    .sp-icon[aria-pressed="true"] { color: var(--profit); }
    button:focus-visible, input:focus-visible, .sp-row:focus-visible, summary:focus-visible {
        outline: 2px solid var(--profit); outline-offset: 1px;
    }

    .sp-bar {
        display: flex; align-items: center; gap: 8px; flex: 0 0 auto;
        padding: 8px 16px; border-bottom: 1px solid var(--line); font-size: 12px;
    }
    .sp-bar-left { flex: 1; min-width: 0; font-weight: bold; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
    .sp-bar-right { color: var(--muted); white-space: nowrap; }

    .sp-banner { display: none; align-items: center; gap: 12px; flex: 0 0 auto; padding: 8px 16px; border-bottom: 1px solid var(--line); background: var(--row); }
    .sp-banner-on { display: flex; }
    .sp-banner-warn { color: var(--warn); }
    .sp-banner-bad { color: var(--bad); }

    .sp-main { flex: 1; min-height: 0; overflow-y: auto; padding: 12px 16px 40px; }
    .sp-empty { padding: 40px 16px; text-align: center; color: var(--muted); }

    .sp-table { width: 100%; max-width: 1100px; margin: 0 auto; border-collapse: separate; border-spacing: 0; }
    .sp-table th {
        position: sticky; top: 0; z-index: 1; padding: 8px 12px; text-align: left;
        background: var(--bg); border-bottom: 1px solid var(--line);
    }
    .sp-table th.sp-money { text-align: right; }
    .sp-table td { padding: 8px 12px; border-bottom: 1px solid var(--line); vertical-align: middle; }
    .sp-row { cursor: pointer; }
    .sp-row:hover td { background: var(--row); }
    .sp-row.sp-open td { background: var(--row); border-bottom-color: transparent; }
    .sp-row.sp-nobuyer td { color: var(--muted); }
    .sp-offer { color: var(--offer); }
    .sp-total { font-size: 15px; font-weight: bold; color: var(--profit); }
    .sp-row.sp-nobuyer .sp-total { color: var(--muted); font-weight: normal; font-size: 13px; }
    .sp-trader { white-space: nowrap; }

    .sp-status { white-space: nowrap; }
    .sp-status::before {
        content: ""; display: inline-block; width: 8px; height: 8px; margin: 0 4px 0 8px;
        border-radius: 50%; background: var(--muted); vertical-align: 0;
    }
    .sp-status[data-level="online"]::before { background: var(--profit); }
    .sp-status[data-level="idle"]::before { background: var(--warn); }
    .sp-status[data-level="unknown"]::before { background: transparent; border: 1px solid var(--muted); }

    .sp-expanded > td { padding: 0 12px 12px; background: var(--row); }
    .sp-traders { display: flex; flex-direction: column; gap: 4px; padding: 8px 12px; border: 1px solid var(--line); border-radius: 4px; }
    .sp-tr { display: grid; grid-template-columns: minmax(0, 1fr) 120px 120px 130px; gap: 8px; align-items: center; padding: 4px 0; }
    .sp-tname { min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .sp-links { display: flex; gap: 12px; justify-content: flex-end; font-size: 12px; }
    .sp-note { font-size: 12px; color: var(--muted); }

    .sp-settings { display: flex; flex-direction: column; gap: 16px; max-width: 640px; margin: 0 auto; width: 100%; }
    .sp-section { display: flex; flex-direction: column; gap: 8px; }
    .sp-section h2 { margin: 0; }
    .sp-inline { display: flex; gap: 8px; align-items: center; }
    .sp-inline input { flex: 1; min-width: 0; }
    input.sp-key { height: 28px; padding: 0 8px; background: var(--row); border: 1px solid var(--line); border-radius: 4px; color: var(--text); }
    .sp-masked { -webkit-text-security: disc; }
    .sp-keystate { font-size: 12px; color: var(--muted); }
    .sp-keystate.sp-ok { color: var(--profit); }
    .sp-keystate.sp-bad { color: var(--bad); }
    .sp-link { background: none; border: 0; padding: 0; color: var(--offer); font-size: 12px; cursor: pointer; text-align: left; }
    .sp-link:hover { text-decoration: underline; }
    .sp-check { display: flex; gap: 8px; align-items: flex-start; cursor: pointer; }
    input[type="checkbox"] { accent-color: var(--profit); margin: 3px 0 0; }
    .sp-tos-box { border: 1px solid var(--line); border-radius: 4px; padding: 8px; background: var(--row); }
    .sp-tos-box summary { cursor: pointer; font-size: 12px; }
    .sp-tos { width: 100%; margin-top: 8px; border-collapse: collapse; font-size: 12px; }
    .sp-tos th, .sp-tos td { text-align: left; vertical-align: top; padding: 4px; border-top: 1px solid var(--line); }
    .sp-tos th { width: 36%; color: var(--muted); font-weight: normal; }

    @media (max-width: 700px) {
        .sp-head { flex-wrap: wrap; height: auto; min-height: 30px; padding: 4px 8px 4px 12px; row-gap: 4px; }
        .sp-head h1 { flex: 1; font-size: 15px; }
        .sp-grow { display: none; }
        .sp-tools { flex: 0 0 100%; order: 10; justify-content: space-between; padding-bottom: 4px; }
        .sp-bar, .sp-banner, .sp-main { padding-left: 12px; padding-right: 12px; }
        .sp-bar-right { display: none; }
        .sp-table, .sp-table tbody { display: block; }
        .sp-table thead { display: none; }
        .sp-row {
            display: grid; grid-template-columns: minmax(0, 1fr) auto; column-gap: 8px; row-gap: 4px;
            padding: 8px 12px; margin-bottom: 8px; background: var(--row); border: 1px solid var(--line); border-radius: 4px;
        }
        .sp-row.sp-open { margin-bottom: 0; border-radius: 4px 4px 0 0; }
        .sp-row td { display: block; padding: 0; border: 0; background: none !important; }
        .sp-row .sp-item { grid-column: 1; grid-row: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .sp-row .sp-item::after { content: " ×" attr(data-qty); color: var(--muted); font-weight: normal; }
        .sp-row td:nth-child(2) { display: none; }
        .sp-row .sp-total { grid-column: 2; grid-row: 1; }
        .sp-row .sp-trader { grid-column: 1; grid-row: 2; font-size: 12px; overflow: hidden; text-overflow: ellipsis; }
        .sp-row .sp-offer { grid-column: 2; grid-row: 2; font-size: 12px; }
        .sp-row td:nth-child(5), .sp-row td:nth-child(6) { grid-column: 1 / 3; font-size: 12px; color: var(--muted); text-align: left; }
        .sp-row td:nth-child(5)::before { content: "Value "; }
        .sp-row td:nth-child(6)::before { content: "Traders avg "; }
        .sp-expanded { display: block; margin-bottom: 8px; }
        .sp-expanded > td { display: block; padding: 0; border: 1px solid var(--line); border-top: 0; border-radius: 0 0 4px 4px; }
        .sp-traders { border: 0; }
        .sp-tr { grid-template-columns: minmax(0, 1fr) auto; }
        .sp-tr > .sp-money:nth-child(3) { display: none; }
        .sp-tr > .sp-links { grid-column: 1 / 3; justify-content: flex-start; }
    }
    `;

    /* ===== src/ui/overlay.js ===== */
    /*
     * Row marking.
     *
     * The entire contract: add one class, remove one class. No element is ever
     * appended into Torn's DOM, no inline style is ever set on a Torn element,
     * and `position` is never touched. The numbers live in the panel.
     *
     * The dataset flag exists so a re-mark after a Torn re-render is cheap. V1
     * had the same idea but its Clear only removed the class, never the flag, so
     * Scan -> Clear -> Scan found nothing forever. `clearMarks` here removes both,
     * and sweeps stale flags whose class is already gone.
     */

    const HIT_CLASS = 'ttv2-hit';
    const HIT_TOP_CLASS = 'ttv2-hit-top';

    /** dataset key `ttv2Hit` <-> attribute `data-ttv2-hit`. */
    const HIT_DATA_KEY = 'ttv2Hit';
    const HIT_DATA_ATTR = 'data-ttv2-hit';

    /** Holds the text the ::after label displays on the card. */
    const PROFIT_DATA_KEY = 'ttv2Profit';

    /** Rows ranked this high get the brighter stripe. */
    const TOP_HIT_COUNT = 3;

    function markRow(el, { top = false, label = '' } = {}) {
        if (!el || !el.classList) return;

        el.classList.add(HIT_CLASS);
        el.classList.toggle(HIT_TOP_CLASS, Boolean(top));
        el.dataset[HIT_DATA_KEY] = '1';

        // Read back by the ::after rule in styles.js.
        if (label) el.dataset[PROFIT_DATA_KEY] = label;
    }

    function unmarkRow(el) {
        if (!el || !el.classList) return;

        el.classList.remove(HIT_CLASS);
        el.classList.remove(HIT_TOP_CLASS);
        delete el.dataset[HIT_DATA_KEY];
        delete el.dataset[PROFIT_DATA_KEY];
    }

    /**
     * Mark a ranked set of rows, clearing anything previously marked.
     * @param {Array<object>} rankedRows - rows carrying an `el`
     */
    function markRows(rankedRows, root = document) {
        clearMarks(root);

        rankedRows.forEach((row, i) => {
            if (!row || !row.el) return;

            markRow(row.el, {
                top: i < TOP_HIT_COUNT,
                label: row.cardLabel || '',
            });
        });
    }

    /** Remove every marker AND every scan flag, so a rescan starts clean. */
    function clearMarks(root = document) {
        for (const el of root.querySelectorAll('.' + HIT_CLASS)) {
            unmarkRow(el);
        }

        // Sweep flags left behind on elements whose class was stripped by a
        // Torn re-render.
        for (const el of root.querySelectorAll('[' + HIT_DATA_ATTR + ']')) {
            unmarkRow(el);
        }
    }

    /** Scroll a marked row into view - the panel's action for on-page hits. */
    function revealRow(el) {
        if (!el || typeof el.scrollIntoView !== 'function') return;
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }

    const TARGET_CLASS = 'ttv2-target';

    /**
     * Point at the listing a feed link was opened for. Adds one class; scrolls
     * only the first time, so a re-render does not yank the page around.
     */
    function markTarget(el, scroll = false) {
        if (!el || !el.classList) return;

        for (const other of document.querySelectorAll('.' + TARGET_CLASS)) {
            if (other !== el) other.classList.remove(TARGET_CLASS);
        }

        el.classList.add(TARGET_CLASS);
        if (scroll) revealRow(el);
    }

    /* ===== src/feed/controller.js ===== */
    /*
     * Runs the live feed: decides whether this tab leads, and if it does, polls
     * TornW3B and the Torn API within budget and stores what it finds.
     *
     * Everything userscript-specific is injected (storage, clients, visibility),
     * so this is testable under node with fakes.
     *
     * Storage is the source of truth, not this object's memory. Every change is
     * load -> mutate -> save in one synchronous step, because a follower tab also
     * writes the feed (when the page it is viewing proves a row sold). Holding a
     * private copy and saving it later would silently undo that correction.
     *
     * What this never does, by design (see README "Rules compliance"):
     *   - request a torn.com page; only api.torn.com (Torn client) and
     *     weav3r.dev (W3B client, which never holds the key)
     *   - run while the tab is hidden, or raise any alert/notification
     *   - buy, click, or pre-fill anything
     */







    /** TornW3B's one-call summary: re-read on every 30s refresh. */
    const SUMMARY_INTERVAL_MS = REFRESH_MS;

    /**
     * Torn API requests the feed may spend per minute. Torn allows 100/min per
     * user across EVERY tool; this leaves most of it for TornTools, TornStats,
     * and the page scanner.
     */
    const FEED_TORN_PER_MINUTE = 30;

    /** Per tick, so one cycle stays short and reacts to the tab being hidden. */
    const MAX_W3B_FETCHES_PER_CYCLE = 8;
    const MAX_TORN_FETCHES_PER_CYCLE = 2;

    /** How many TornW3B candidates also get an Item Market check, and how often. */
    const CANDIDATE_MARKET_CHECKS = 5;
    const CANDIDATE_MARKET_INTERVAL_MS = 2 * 60 * 1000;

    /**
     * A live Item Market row is re-checked before it can expire: once its data
     * is this old it goes ahead of discovery. Younger rows are re-checked only
     * with spare budget. Torn serves the same snapshot for 30s anyway.
     */
    const LIVE_ROW_URGENT_MS = 55 * 1000;

    const FEED_STORE_KEY = 'feed';
    const FEED_LEADER_KEY = 'feedLeader';
    const FEED_RECHECK_KEY = 'feedRecheck';

    /** Set by Scan in any tab: the leader rebuilds everything at once. */
    const FEED_REFRESH_KEY = 'feedRefreshAt';

    class LiveFeed {
        /**
         * @param {object} deps
         * @param {string} deps.tabId
         * @param {object} deps.w3b          - W3bClient
         * @param {object} deps.torn         - TornApiClient
         * @param {function} deps.getIndex   - () => item index | null
         * @param {function} deps.getSettings
         * @param {function} deps.hasUsableKey
         * @param {function} deps.isVisible
         * @param {function} deps.load       - (key) => value
         * @param {function} deps.save       - (key, value) => void
         * @param {function} [deps.onChange] - feed changed
         * @param {function} [deps.isKeyDead] - (error) => boolean
         * @param {function} [deps.onKeyDead] - (error) => void
         * @param {function} [deps.now]
         * @param {function} [deps.onSummary] - (summary, now) => void, each TornW3B summary
         */
        constructor(deps) {
            this.d = deps;
            this.now = deps.now || (() => Date.now());

            this.leading = false;
            this.busy = false;
            this.lastSummaryAt = 0;
            this.candidates = [];
            this.sweep = [];
            this.sweepPos = 0;
            this.tornSpent = [];
            this.lastError = null;
            this.lastCycleAt = null;
            this.lastRefreshSeen = 0;
            this.cycleCount = 0;
            /** itemId -> when its "cheaper on the market too?" check last ran. */
            this.candidateCheckedAt = new Map();
        }

        /**
         * Scan: throw away everything and rebuild from fresh data now. Works from
         * any tab - the flag is shared, and whichever tab leads acts on it.
         */
        requestRefresh() {
            this.d.save(FEED_STORE_KEY, null);
            this.d.save(FEED_REFRESH_KEY, this.now());
            if (this.d.onChange) this.d.onChange();
        }

        /* ------------------------------------------------------ storage */

        readFeed() {
            return readFeedCacheEntry(this.d.load(FEED_STORE_KEY), this.now());
        }

        /** Load, mutate, save - in one synchronous step. */
        mutate(fn) {
            const feed = this.readFeed();
            fn(feed);
            this.d.save(FEED_STORE_KEY, makeFeedCacheEntry(feed, this.now()));
            if (this.d.onChange) this.d.onChange();
            return feed;
        }

        /** Ask the leader (whichever tab it is) to re-verify these items first. */
        requestRecheck(itemIds) {
            const queue = new Set(this.d.load(FEED_RECHECK_KEY) || []);
            for (const id of itemIds || []) queue.add(String(id));
            this.d.save(FEED_RECHECK_KEY, [...queue].slice(-50));
        }

        takeRechecks() {
            const queue = this.d.load(FEED_RECHECK_KEY) || [];
            if (queue.length) this.d.save(FEED_RECHECK_KEY, []);
            return queue.map(String);
        }

        /* ------------------------------------------------------- status */

        status() {
            const s = this.d.getSettings();
            return {
                enabled: Boolean(s.liveFeed),
                w3b: Boolean(s.liveFeed && s.useW3b),
                itemMarket: Boolean(s.liveFeed && this.d.hasUsableKey()),
                leading: this.leading,
                candidates: this.candidates.length,
                nextRefreshAt: this.lastSummaryAt ? this.lastSummaryAt + SUMMARY_INTERVAL_MS : null,
                lastCycleAt: this.lastCycleAt,
                lastError: this.lastError,
            };
        }

        /* --------------------------------------------------------- tick */

        /**
         * Called on a timer by every tab. Cheap when not leading.
         * @returns {Promise<void>}
         */
        async tick() {
            const settings = this.d.getSettings();
            const now = this.now();
            const visible = this.d.isVisible();

            const record = this.d.load(FEED_LEADER_KEY);

            if (!settings.liveFeed) {
                if (record && record.id === this.d.tabId) {
                    this.d.save(FEED_LEADER_KEY, { id: null, ts: 0 });
                }
                this.leading = false;
                return;
            }

            const decision = decideLeader(record, this.d.tabId, { now, visible });
            if (decision.write) this.d.save(FEED_LEADER_KEY, decision.write);
            this.leading = decision.lead;

            if (!decision.confirmed || this.busy) return;
            if (!this.d.getIndex()) return;

            this.busy = true;
            try {
                await this.cycle();
                this.lastCycleAt = this.now();
            } finally {
                this.busy = false;
            }
        }

        /** Stop as soon as the tab is hidden or the user switches the feed off. */
        stillAllowed() {
            return this.d.isVisible() && Boolean(this.d.getSettings().liveFeed);
        }

        async cycle() {
            const settings = this.d.getSettings();
            const index = this.d.getIndex();

            this.mutate((feed) => expireFeed(feed, this.now()));

            const refreshAt = Number(this.d.load(FEED_REFRESH_KEY)) || 0;
            if (refreshAt > this.lastRefreshSeen) {
                this.lastRefreshSeen = refreshAt;
                this.lastSummaryAt = 0;
            }

            const rechecks = this.takeRechecks();

            if (settings.useW3b) {
                await this.refreshSummary(index, settings);
                await this.refreshBazaars(rechecks);
            } else {
                this.candidates = [];
                // Opted out: forget what TornW3B told us.
                this.mutate((feed) => feed.bazaar.clear());
            }

            if (this.d.hasUsableKey()) {
                // Rebuilt when what counts as an exit changes (a chip), not just once.
                const sig = [
                    settings.sellToNpc !== false,
                    Boolean(settings.resaleMarket),
                    Boolean(settings.resaleBazaar),
                    Number(settings.cashOnHand) || 0,
                ].join('|');
                if (this.sweepSig === undefined) this.sweepSig = sig;
                if (!this.sweep.length || sig !== this.sweepSig) {
                    this.sweep = itemMarketSweepList(index, settings);
                    this.sweepSig = sig;
                    this.sweepPos = 0;
                }
                await this.refreshItemMarket(rechecks);
            }
        }

        async refreshSummary(index, settings) {
            if (this.now() - this.lastSummaryAt < SUMMARY_INTERVAL_MS) return;

            try {
                const summary = await fetchW3bSummary(this.d.w3b);
                this.lastSummaryAt = this.now();
                this.candidates = selectCandidates(summary, index, settings);
                this.lastError = null;
                if (this.d.onSummary) {
                    try {
                        this.d.onSummary(summary, this.lastSummaryAt);
                    } catch {
                        // A listener's failure is not the feed's.
                    }
                }

                /*
                 * The summary is authoritative about what is NOT a deal: if an
                 * item's cheapest bazaar price no longer beats its exit, none of
                 * its bazaar rows can. Drop them now rather than waiting out a TTL.
                 */
                const keep = new Set(this.candidates.map((c) => c.itemId));
                this.mutate((feed) => {
                    for (const id of [...feed.bazaar.keys()]) {
                        if (!keep.has(id)) feed.bazaar.delete(id);
                    }
                });
            } catch (error) {
                this.lastError = 'TornW3B: ' + ((error && error.message) || error);
            }
        }

        async refreshBazaars(rechecks) {
            const feedNow = this.readFeed();
            const byId = new Map(this.candidates.map((c) => [c.itemId, c]));

            const queue = [];
            for (const id of rechecks) if (byId.has(id)) queue.push(byId.get(id));
            for (const c of this.candidates) {
                if (!queue.includes(c) && bazaarDue(feedNow, c, this.now())) queue.push(c);
            }

            let fetched = 0;

            for (const candidate of queue) {
                if (fetched >= MAX_W3B_FETCHES_PER_CYCLE || !this.stillAllowed()) break;

                try {
                    const { listings } = await fetchW3bListings(
                        this.d.w3b,
                        candidate.itemId,
                    );
                    fetched += 1;

                    const rows = normalizeW3bListings(listings);
                    const at = this.now();
                    this.mutate((feed) =>
                        setBazaarSnapshot(feed, candidate.itemId, rows, at),
                    );
                } catch (error) {
                    this.lastError = 'TornW3B: ' + ((error && error.message) || error);
                    if (error && error.blocked) break;
                }
            }
        }

        tornBudgetLeft() {
            const t = this.now();
            this.tornSpent = this.tornSpent.filter((x) => t - x < 60000);
            return FEED_TORN_PER_MINUTE - this.tornSpent.length;
        }

        /**
         * Which Item Market items to fetch this cycle, in order. Pure planning,
         * exposed for tests.
         *
         * The Torn budget is small (30/min) and everything wants it: rows already
         * on the list must be re-checked before they expire, TornW3B candidates
         * may be cheaper on the market too, and discovery has to keep moving or
         * nothing new is ever found. 3.7 let re-checks and candidates take both
         * slots every cycle and gave discovery one slot every other cycle, then
         * ran out of budget before reaching it: the sweep starved. Now:
         *
         *   1. what a tab explicitly asked to re-check (a listing someone opened)
         *   2. live rows about to expire, oldest data first
         *   3. ONE sweep item, so discovery advances every cycle
         *   4. a top TornW3B candidate, at most every 2 minutes each
         *   5. more sweep items
         *   6. with spare budget, other live rows past Torn's 30s cache
         *
         * @returns {Array<string>} item ids, at most `slots` of them
         */
        planItemMarket(feedNow, rechecks, now, slots) {
            const order = [];
            const add = (id) => {
                if (order.length >= slots) return false;
                if (!order.includes(id) && itemMarketDue(feedNow, id, now)) order.push(id);
                return true;
            };

            for (const id of rechecks) add(id);

            const live = itemMarketLiveIds(feedNow, (id, price) => this.isMarketDeal(id, price))
                .map((id) => ({ id, at: feedNow.itemmarket.get(id).dataAt || 0 }))
                .sort((a, b) => a.at - b.at);
            for (const l of live) {
                if (now - l.at >= LIVE_ROW_URGENT_MS) add(l.id);
            }

            const takeSweep = (want) => {
                const len = this.sweep.length;
                let examined = 0;
                let taken = 0;
                while (len && examined < len && taken < want && order.length < slots) {
                    const id = this.sweep[(this.sweepPos + examined) % len];
                    examined += 1;
                    if (!order.includes(id) && itemMarketDue(feedNow, id, now)) {
                        order.push(id);
                        taken += 1;
                    }
                }
                // The cursor moves past what it LOOKED at, so an item still inside
                // its cache window cannot stall the sweep.
                if (len) this.sweepPos = (this.sweepPos + examined) % len;
            };

            takeSweep(1);

            for (const c of this.candidates.slice(0, CANDIDATE_MARKET_CHECKS)) {
                if (order.length >= slots) break;
                const last = this.candidateCheckedAt.get(c.itemId);
                if (last !== undefined && now - last < CANDIDATE_MARKET_INTERVAL_MS) continue;
                const before = order.length;
                add(c.itemId);
                if (order.length > before) this.candidateCheckedAt.set(c.itemId, now);
            }

            if (order.length < slots) takeSweep(slots - order.length);

            // Spare budget only: live rows past Torn's 30s cache, oldest first.
            for (const l of live) add(l.id);

            return order.slice(0, slots);
        }

        /** Does a listing at this price beat one of the chosen exits? */
        isMarketDeal(itemId, price) {
            const index = this.d.getIndex();
            const item = index && index.byId && index.byId.get(String(itemId));
            if (!item) return false;
            const best = bestVenue({
                listingPrice: price,
                exits: exitsFor(item, this.d.getSettings()),
                qty: 1,
            });
            return Boolean(best && best.profitPerUnit > 0);
        }

        async refreshItemMarket(rechecks) {
            const feedNow = this.readFeed();
            const now = this.now();
            this.cycleCount += 1;

            const slots = Math.min(MAX_TORN_FETCHES_PER_CYCLE, this.tornBudgetLeft());
            if (slots <= 0) return;

            const order = this.planItemMarket(feedNow, rechecks, now, slots);

            let fetched = 0;

            for (const id of order) {
                if (fetched >= MAX_TORN_FETCHES_PER_CYCLE) break;
                if (this.tornBudgetLeft() <= 0 || !this.stillAllowed()) break;

                this.tornSpent.push(this.now());
                fetched += 1;

                try {
                    const market = await fetchItemMarket(this.d.torn, id, {
                        now: this.now(),
                    });
                    const rows = normalizeItemMarketRows(market.listings);
                    const at = this.now();

                    this.mutate((feed) =>
                        setItemMarketSnapshot(feed, id, {
                            rows,
                            fetchedAt: at,
                            dataAt: market.cacheTimestamp,
                            nextAt: market.nextAt,
                            averagePrice: market.averagePrice,
                        }),
                    );
                } catch (error) {
                    this.lastError = 'Torn API: ' + ((error && error.message) || error);
                    if (error && this.d.onKeyDead && this.d.isKeyDead && this.d.isKeyDead(error)) {
                        this.d.onKeyDead(error);
                    }
                    break;
                }
            }
        }
    }

    /* ===== src/main.js ===== */
    /*
     * Wiring. This file is the only part of the codebase that knows it is a
     * userscript; core/ and api/ are plain modules that would move to a web app
     * untouched.
     *
     * Two entry points share it:
     *   - every Torn page: the overlay (deals below NPC / value, live from the
     *     API), the bazaar owner badge, and on your OWN bazaar's add / manage
     *     pages the pricing helper;
     *   - the selling page tab (index.php?ttv2=traders): its own keys, its own
     *     settings, its own requests. See bootSellingPage().
     */



























    const STORE_KEY = 'apiKey';
    const STORE_ITEMS = 'itemsCache';
    const STORE_NPC = 'npcCache';
    const STORE_MANUAL_NPC = 'npcManual';
    const STORE_SETTINGS = 'settings';
    const STORE_KEY_ACCESS = 'keyAccess';
    const STORE_API_WINDOW = 'apiWindow';
    const STORE_KEY_DEAD = 'keyDead';
    const STORE_OPENED = 'opened';

    /* The selling page's own keys, caches and preferences - never the overlay's. */
    const STORE_SELL_KEY = 'sellKey';
    const STORE_SELL_KEY_DEAD = 'sellKeyDead';
    const STORE_SELL_KEY_ACCESS = 'sellKeyAccess';
    const STORE_TE_KEY = 'teKey';
    const STORE_TE = 'teCache';
    const STORE_TE_STATE = 'teState';
    const STORE_TE_LISTS = 'teLists';
    const STORE_TE_IDS = 'teIds';
    const STORE_INVENTORY = 'inventory';
    const STORE_SELL_PREFS = 'sellingPage';

    /* Price history the script records itself, and TornW3B's latest summary. */
    const STORE_HISTORY = 'priceHistory';
    const STORE_W3B_SUMMARY = 'w3bSummary';

    const DEFAULT_SETTINGS = {
        /*
         * No floor by default. The list is already ranked by total profit, so
         * small hits sink to the bottom on their own - a threshold only makes
         * them vanish without saying so.
         */
        minTotalProfit: 1,
        cashOnHand: null,
        /*
         * Where you could sell what you buy. "Sell to NPC" is the job this tool
         * exists for: listings cheaper than an NPC shop's Sell price, which is
         * guaranteed and untaxed. The two resale exits compare against the
         * average value (Torn's "Value") and are groundwork for trading - off
         * by default, and never mixed into the NPC numbers.
         */
        sellToNpc: true,
        resaleBazaar: false,
        resaleMarket: false,

        /*
         * Watching: the market from ANY Torn page, not just the one you are on.
         * Runs in one visible tab only, polls the Torn API well inside the rate
         * limit, and never raises alerts - see README.
         */
        liveFeed: true,

        /*
         * TornW3B bazaar prices. ON by default: bazaar opportunities are the
         * point of the Bazaars list, and Torn has no per-listing bazaar data a
         * Public key can trust. Torn's API terms allow an automatic integration
         * when the tool's own terms cover it - the Settings disclosure names
         * TornW3B, says it receives item ids only, and links its terms. The key
         * never goes there. Untick to stop contacting it entirely.
         */
        useW3b: true,

        /*
         * Go opens a new tab (on), or goes there in this tab (off). A
         * preference, not a safety setting: either way it is one click, one
         * page load, and nothing is bought.
         */
        openInNewTab: true,

        /* Which list the panel shows when you are on neither market page. */
        viewTab: 'bazaar',
        collapsed: false,
        /* Where the panel was dragged to; null = bottom-right. */
        panelPos: null,
    };

    const RESCAN_DEBOUNCE_MS = 400;

    /*
     * The viewed bazaar's owner: one public-profile call when you open it, then
     * at most once per OWNER_REFRESH_MS while you stay. A failure waits a minute.
     */
    const OWNER_REFRESH_MS = 30000;
    const OWNER_RETRY_MS = 60000;

    /*
     * Online status for bazaar sellers on the list: the first SELLER_STATUS_MAX
     * while the Bazaars list is on screen. One public-profile call each, then
     * at most once per PRESENCE_REFRESH_MS while they stay listed - inside the
     * shared 70/min budget next to the feed's 30. Visible tab only.
     */
    const SELLER_STATUS_MAX = 10;
    const PRESENCE_REFRESH_MS = 60000;
    const PRESENCE_RETRY_MS = 120000;
    const PRESENCE_MAX_PENDING = 3;
    /* Players not on a list this long are forgotten. */
    const PRESENCE_FORGET_MS = 10 * 60 * 1000;

    /* A bazaar seen closed keeps its feed deals hidden this long (or until seen open). */
    const CLOSED_MEMORY_MS = 10 * 60 * 1000;

    const HREF_WATCH_MS = 250;
    const SCAN_BURST_MS = [0, 300, 700, 1200, 2000, 3000];

    /** How often every tab checks whether it should lead the live feed. */
    const FEED_TICK_MS = LEADER_HEARTBEAT_MS;

    /*
     * Item Market 2.0 and the bazaars re-render continuously, and a
     * MutationObserver on one container misses a re-render that replaces the
     * container itself. A slow poll alongside the observer is what makes the
     * highlights stay put in practice. It touches only the DOM already on screen
     * and makes no requests.
     */
    const POLL_INTERVAL_MS = 2500;

    /*
     * Your own bazaar's pricing helper: one Item Market call per item on screen,
     * at most one every BZ_FETCH_GAP_MS (6 a minute), each answer kept
     * BZ_IM_TTL_MS; a fresher snapshot the feed already holds is used instead of
     * a call. Bazaar prices come from the TornW3B summary the feed already
     * fetches; a per-item TornW3B call only when that summary is missing or old.
     */
    const BZ_FETCH_GAP_MS = 10000;
    const BZ_IM_TTL_MS = 120000;
    const BZ_SUMMARY_MAX_AGE_MS = 5 * 60 * 1000;
    const BZ_W3B_TTL_MS = 60000;
    /* History: one sample per item per 5 minutes from the summary; saved at most every 30s. */
    const HISTORY_SAMPLE_MS = 5 * 60 * 1000;
    const HISTORY_SAVE_MS = 30000;

    const app = {
        tabId: makeTabId(),
        index: null,
        feed: null,
        w3b: null,
        /*
         * Set when Torn says the key is invalid, disabled or paused. Nothing is
         * sent until the user saves a key again: Torn's docs warn that repeated
         * requests with an invalid key can earn a temporary IP ban, and the old
         * 2.5s poll retried a bad key forever.
         */
        keyDead: false,
        /* When each (item, price, qty) on THIS page load was first read. */
        pageFirstSeen: new Map(),
        pageHref: null,
        pageRows: [],
        /* { id, presence, fetchedAt, pending, retryAt, open } for the viewed bazaar. */
        owner: null,
        /* playerId -> { presence, fetchedAt, pending, retryAt, listedAt }: list sellers. */
        presence: new Map(),
        /* sellerId -> time until which their bazaar counts as closed. */
        closedSellers: new Map(),
        pageDiagnostics: null,
        targetShown: null,
        /* After a failed load, the automatic retry waits until this time. */
        retryLoadAt: 0,
        /* A tab the user clicked, until the page type next changes. */
        tabOverride: null,
        npcShops: new Map(),
        manualNpc: {},
        settings: { ...DEFAULT_SETTINGS },
        pageType: PAGE_NONE,
        panel: null,
        client: null,
        observer: null,
        observerTarget: null,
        lastScanAt: null,
        loading: false,
        /* Your own bazaar's add / manage page, while you are on it. */
        ownBazaar: null,
        bzRows: [],
        bzDiagnostics: null,
        /* itemId -> { im: {price, at}|null, bz: {price, at}|null, imAt, bzAt, pending } */
        bzPrices: new Map(),
        bzSelected: null,
        bzWindow: '24h',
        bzLastFetchAt: 0,
        /* The recorded price history, loaded once, saved on a timer. */
        history: null,
        historyDirty: false,
        historySavedAt: 0,
        historySampledAt: 0,
    };

    /**
     * Stored settings over the defaults, keeping only settings that still exist.
     * Removed settings (the Trader chip, among others) must not linger.
     */
    function loadSettings() {
        const stored = gmGet(STORE_SETTINGS, {}) || {};
        const out = { ...DEFAULT_SETTINGS };

        for (const key of Object.keys(DEFAULT_SETTINGS)) {
            if (Object.prototype.hasOwnProperty.call(stored, key)) out[key] = stored[key];
        }

        // The NPC switch was called compareNpc.
        if (stored.compareNpc === false && !('sellToNpc' in stored)) out.sellToNpc = false;
        if (out.viewTab !== 'bazaar' && out.viewTab !== 'itemmarket') out.viewTab = 'bazaar';

        return out;
    }

    /* ------------------------------------------------------------------ *
     * API key
     * ------------------------------------------------------------------ */

    function getStoredKey() {
        return gmGet(STORE_KEY, '') || '';
    }

    /** A key we may actually send: present, and not rejected by Torn. */
    function hasUsableKey() {
        return Boolean(getStoredKey()) && !app.keyDead;
    }

    function isKeyDeadError(error) {
        return Boolean(error && KEY_DEAD_CODES.has(Number(error.code)));
    }

    /** Torn rejected the key: stop using it until the user saves another. */
    function markKeyDead(error) {
        app.keyDead = true;
        gmSet(STORE_KEY_DEAD, true);

        app.panel.setStatus(
            'Torn rejected this key (' +
                redactKey((error && error.message) || 'invalid key', getStoredKey()) +
                '). Paste a new Public key.',
            'error',
        );
    }

    function looksLikeTornKey(key) {
        return /^[A-Za-z0-9]{16}$/.test(key);
    }

    function refreshKeyState() {
        const access = gmGet(STORE_KEY_ACCESS, null);

        app.panel.setKeyState({
            hasKey: Boolean(getStoredKey()),
            accessName: access && access.name,
            overScoped: Boolean(
                access && access.level !== null && access.level > ACCESS_PUBLIC,
            ),
        });
    }

    /**
     * Save a key pasted into the settings panel.
     *
     * The key is stored locally and used against api.torn.com. Nothing here, and
     * nothing anywhere else in this codebase, sends it to a server of ours -
     * there is no server of ours.
     */
    async function onSaveKey(key) {
        if (!key) {
            app.panel.setStatus('Paste a key first.', 'error');
            return;
        }

        // The TornExchange key is not a Torn key and must never reach Torn.
        if (key === getTeKey()) {
            app.panel.setStatus('That is the TornExchange key. Paste your Torn Public key.', 'error');
            return;
        }

        if (!looksLikeTornKey(key)) {
            app.panel.setStatus('Saved. Torn keys are 16 letters and digits; check it if calls fail.', 'warn');
        }

        gmSet(STORE_KEY, key);
        gmDel(STORE_KEY_ACCESS);
        gmDel(STORE_KEY_DEAD);
        app.keyDead = false;

        refreshKeyState();
        await onScan();
        refreshKeyState();

        // Key accepted: back to the list, which is now loading.
        if (!app.keyDead && app.index) app.panel.showPage(app.panel.homePage());
    }

    function onForgetKey() {
        gmDel(STORE_KEY);
        gmDel(STORE_KEY_ACCESS);
        gmDel(STORE_KEY_DEAD);
        app.keyDead = false;

        if (app.panel.keyInput) app.panel.keyInput.value = '';

        refreshKeyState();
        app.panel.setStatus('API key removed.');
    }

    function onClearCache() {
        gmDel(STORE_ITEMS);
        gmDel(STORE_NPC);

        app.index = null;
        app.npcShops = new Map();

        app.panel.setStatus('Re-downloading item data.');
        if (hasUsableKey()) onScan();
    }

    /**
     * Warn when the stored key has more access than this tool needs.
     * Advisory only - an inconclusive check says nothing.
     */
    async function checkKeyAccess() {
        let access = gmGet(STORE_KEY_ACCESS, null);

        if (!access) {
            access = await fetchKeyAccess(app.client);
            if (access && access.level !== null) gmSet(STORE_KEY_ACCESS, access);
        }

        refreshKeyState();

        if (access && access.level !== null && access.level > ACCESS_PUBLIC) {
            app.panel.setStatus(
                'This key has ' + (access.name || 'level ' + access.level) + ' access. Public is enough.',
                'warn',
            );
        }

        return access;
    }

    /* ------------------------------------------------------------------ *
     * Reference data
     * ------------------------------------------------------------------ */

    async function loadReferenceData() {
        const cachedItems = gmGet(STORE_ITEMS, null);

        if (isItemsCacheFresh(cachedItems)) {
            app.index = buildItemIndex(cachedItems.items);
            app.itemsFetchedAt = cachedItems.fetchedAt;
        } else {
            app.panel.setStatus('Downloading item database.');
            const raw = await fetchItems(app.client);
            const entry = makeItemsCacheEntry(raw);
            gmSet(STORE_ITEMS, entry);
            app.index = buildItemIndex(raw);
            app.itemsFetchedAt = entry.fetchedAt;
        }

        const cachedNpc = gmGet(STORE_NPC, null);

        if (isNpcCacheFresh(cachedNpc)) {
            app.npcShops = readNpcCacheEntry(cachedNpc);
        } else {
            app.panel.setStatus('Downloading shop inventories.');
            try {
                const shops = await fetchShops(app.client);
                const index = buildNpcShopIndex(shops);
                gmSet(STORE_NPC, makeNpcCacheEntry(index));
                app.npcShops = index;
            } catch (error) {
                /*
                 * Without shop data every item is "unverified" rather than
                 * silently treated as NPC-sellable, which is V1's mistake. But
                 * the user has to be TOLD: an empty panel that looks like "no
                 * opportunities" when it really means "could not verify anything"
                 * is the worst of both worlds.
                 */
                app.npcShops = new Map();
                app.shopLoadError =
                    (error && error.message) || 'shop data unavailable';
            }
        }

        app.manualNpc = gmGet(STORE_MANUAL_NPC, {}) || {};
    }

    /**
     * Keep market values current in a tab that stays open for hours. Another
     * tab may already have refreshed the shared cache; only fetch if it has not.
     */
    async function refreshItemsIfStale() {
        if (!app.index || app.loading || app.refreshingItems || !hasUsableKey()) return;
        if (app.itemsFetchedAt && Date.now() - app.itemsFetchedAt < ITEMS_TTL_MS) return;

        const cached = gmGet(STORE_ITEMS, null);
        if (isItemsCacheFresh(cached)) {
            if (cached.fetchedAt !== app.itemsFetchedAt) {
                app.index = buildItemIndex(cached.items);
                app.itemsFetchedAt = cached.fetchedAt;
            }
            return;
        }

        app.refreshingItems = true;
        try {
            const raw = await fetchItems(app.client);
            const entry = makeItemsCacheEntry(raw);
            gmSet(STORE_ITEMS, entry);
            app.index = buildItemIndex(raw);
            app.itemsFetchedAt = entry.fetchedAt;
        } catch (error) {
            if (isKeyDeadError(error)) markKeyDead(error);
            // Otherwise keep the old values and try again on a later tick.
            app.itemsFetchedAt = Date.now() - ITEMS_TTL_MS + 5 * 60 * 1000;
        } finally {
            app.refreshingItems = false;
        }
    }

    /* ------------------------------------------------------------------ *
     * Scanning
     * ------------------------------------------------------------------ */

    /** Turn raw page listings into priced opportunities. */
    function buildOpportunities(listings) {
        const rows = [];

        for (const listing of listings) {
            /*
             * Compare against BOTH exits and keep whichever pays more:
             *   - NPC sell price: guaranteed, no fee, but usually well under market
             *   - Market value:   resell on the Item Market, minus the 5% tax
             *
             * exitsFor() is shared with the live feed, so a listing is priced
             * the same whether it was read off this page or found elsewhere.
             */
            const npcShop = npcShopFor(listing.itemId, app.npcShops, app.manualNpc);

            const exits = exitsFor(listing.item, app.settings);
            if (Object.keys(exits).length === 0) continue;

            const profit = bestVenue({
                listingPrice: listing.listingPrice,
                exits,
                qty: listing.qty,
                cashOnHand: app.settings.cashOnHand,
            });

            rows.push({
                ...listing,
                profit,
                npcShop,
                npcVerified: npcShop !== null,
                /*
                 * What the green card itself shows. Deliberately short: a Torn
                 * item tile is about 123px wide, and the long form overflowed
                 * onto the neighbouring card. The full breakdown is in the panel.
                 */
                cardLabel:
                    '+' +
                    formatMoneyShort(
                        listing.qtyAtPrice
                            ? profit.totalProfit
                            : profit.profitPerUnit,
                    ) +
                    (listing.qtyAtPrice ? '' : '/ea'),
            });
        }

        return rows;
    }

    /**
     * When did THIS page first show this exact listing?
     *
     * The page does not live-update: a price on screen is as old as the moment
     * it rendered. Re-reading the same DOM every 2.5s must not make it younger.
     * The map resets whenever the URL changes (a new category, a new bazaar, a
     * reload), because that is when Torn fetched fresh data.
     */
    function stampSeen(listing, now) {
        const key =
            listing.itemId + '|' + listing.listingPrice + '|' + (listing.qty || 1);

        if (!app.pageFirstSeen.has(key)) app.pageFirstSeen.set(key, now);
        return app.pageFirstSeen.get(key);
    }

    /**
     * Current settings for the ranker. Whether a city shop STOCKS an item never
     * decides anything - an NPC buys whatever has a Sell price - so that filter
     * is always off.
     */
    function rankSettings(extra = {}) {
        return { ...app.settings, includeUnverifiedNpc: true, ...extra };
    }

    /** Read the page, fold it into memory, correct the feed, then render. */
    function rescan() {
        /*
         * Re-detect the page every scan.
         *
         * Torn navigates with pushState, which fires neither hashchange nor
         * popstate - so a bazaar kept being scanned as, and reported as, the Item
         * Market. Detection is a string test, so doing it every pass costs
         * nothing and removes a whole class of stale-state bugs.
         */
        const current = detectPage(location.href);
        if (current !== app.pageType) {
            app.pageType = current;
            // A new kind of page picks its own list again.
            app.tabOverride = null;
            clearMarks();
        }

        if (location.href !== app.pageHref) {
            app.pageHref = location.href;
            app.pageFirstSeen = new Map();
            app.targetShown = null;
        }

        updateOwner(Date.now());

        if (!app.index) return;

        // Your own bazaar's add / manage page: the pricing helper, not the scanner.
        const own = ownBazaarPage(location.href);
        if (own !== app.ownBazaar) {
            if (app.ownBazaar) removeRowTags(document);
            app.ownBazaar = own;
            app.bzRows = [];
            app.bzDiagnostics = null;
            if (!own) app.panel.renderMyBazaar(null);
        }
        if (own) {
            scanOwnBazaarPage(own);
            app.pageRows = [];
            app.pageDiagnostics = null;
            refreshView();
            return;
        }

        if (app.pageType === PAGE_NONE) {
            app.pageRows = [];
            app.pageDiagnostics = null;
            refreshView();
            return;
        }

        const { listings, diagnostics } = scanDom(app.pageType, document, {
            index: app.index,
            href: location.href,
        });

        const now = Date.now();
        const sellerId =
            app.pageType === PAGE_BAZAAR ? bazaarOwnerId(location.href) : null;

        for (const l of listings) {
            l.seenAt = stampSeen(l, now);
            l.source =
                app.pageType === PAGE_BAZAAR ? SOURCE_BAZAAR : SOURCE_ITEM_MARKET;
            l.sellerId = sellerId;
        }

        const priced = buildOpportunities(listings);

        // No limit here; only the markers and the panel are capped.
        const ranked = rankOpportunities(priced, rankSettings({ limit: 0 }));

        /*
         * Two-way correction between the page and the feed.
         *
         * The page overrules the feed: if it shows a higher price than a feed
         * row claims, that feed row has sold. And fresher feed data overrules
         * the page: Torn's page does not update itself and this script may not
         * reload it, so a listing that sold while you were looking is removed
         * once the 30s re-check proves it gone. Only live listings are shown.
         */
        const feed = readFeedCacheEntry(gmGet(FEED_STORE_KEY, null), now);

        if (listings.length) {
            const removed = reconcileWithPage(feed, {
                pageType: app.pageType,
                sellerId,
                listings,
            });
            if (removed > 0) gmSet(FEED_STORE_KEY, makeFeedCacheEntry(feed, now));
        }

        // A closed bazaar sells nothing, however cheap its listings look.
        const closedHere = Boolean(app.owner && app.owner.open === false);
        const live = closedHere
            ? []
            : ranked.filter((row) => !pageRowContradicted(feed, row));
        if (closedHere) clearMarks();

        // Ask the feed to keep re-checking what this page shows, every refresh.
        if (app.feed && live.length && now - (app.lastPageRecheckAt || 0) >= REFRESH_MS) {
            app.lastPageRecheckAt = now;
            app.feed.requestRecheck(live.slice(0, 10).map((r) => r.itemId));
        }

        markRows(live.slice(0, 100));
        showBazaarTarget(listings);

        app.lastScanAt = now;
        app.pageRows = live;
        app.pageDiagnostics = diagnostics;

        refreshView();
        attachObserver(listings);
    }

    /**
     * Arrived from a feed link: point at the listing it named.
     *
     * Reading and marking the page the user opened is allowed; nothing is
     * clicked, filled in, or bought. If the listing is visible at a different
     * price, say so - that is the listing having changed since TornW3B saw it.
     */
    function showBazaarTarget(listings) {
        const target = bazaarTarget(location.href);
        if (!target) return;

        const matches = listings.filter((l) => String(l.itemId) === target.itemId);
        if (!matches.length) return;

        const exact = target.price
            ? matches.find((l) => l.listingPrice <= target.price)
            : matches[0];

        const key = location.href;
        const firstTime = app.targetShown !== key;
        app.targetShown = key;

        if (exact) {
            markTarget(exact.el, firstTime);
            return;
        }

        if (firstTime) {
            app.panel.setStatus(
                'That listing is no longer at ' + formatMoneyShort(target.price) + ' here.',
                'warn',
            );
        }
    }

    /**
     * Everything the panel shows: this page, what you saw elsewhere, and the
     * live feed. Never reads the DOM, so the feed can re-render it whenever
     * another tab updates storage. Its only requests are the rate-limited seller
     * status lookups in updatePresence().
     */
    function refreshView() {
        if (!app.panel) return;

        const now = Date.now();
        const sellerHere =
            app.pageType === PAGE_BAZAAR ? bazaarOwnerId(location.href) : null;

        // Listings on the page you are viewing, by source - they win over any
        // remembered or remote copy of the same listing.
        const onPage = new Set(
            app.pageRows.map((r) => (r.source || app.pageType) + ':' + r.itemId),
        );

        const feed = readFeedCacheEntry(gmGet(FEED_STORE_KEY, null), now);
        const feedRows = app.index
            ? feedOpportunities(feed, app.index, app.settings, {
                  now,
                  npcShopFor: (id) => npcShopFor(id, app.npcShops, app.manualNpc),
                  itemMarketUrl,
              }).filter((r) => {
                  // The page you are on already shows these, with fresher numbers.
                  if (r.source === SOURCE_ITEM_MARKET) {
                      return !onPage.has(SOURCE_ITEM_MARKET + ':' + r.itemId);
                  }
                  if (isSellerClosed(r.sellerId, now)) return false;
                  return !(
                      r.sellerId === sellerHere &&
                      onPage.has(SOURCE_BAZAAR + ':' + r.itemId)
                  );
              })
            : [];

        /*
         * Two lists, never mixed. Arriving on a bazaar from the Item Market used
         * to leave the Item Market's opportunities on screen, which read as if
         * they were in this bazaar.
         */
        const all = app.pageRows.concat(feedRows);
        const lists = { bazaar: [], itemmarket: [] };
        for (const r of all) {
            lists[r.source === SOURCE_BAZAAR ? 'bazaar' : 'itemmarket'].push(r);
        }

        const bazaarRows = rankOpportunities(lists.bazaar, rankSettings());
        const marketRows = rankOpportunities(lists.itemmarket, rankSettings());

        const tab = activeTab();
        const shown = tab === 'bazaar' ? bazaarRows : marketRows;

        updatePresence(tab === 'bazaar' ? listedSellers(bazaarRows) : [], now);

        app.panel.render({
            rows: shown,
            tab,
            statuses: statusMap(now),
            hidden: hiddenCounts(tab === 'itemmarket' ? lists.itemmarket : lists.bazaar, rankSettings()),
            counts: {
                bazaar: bazaarRows.length,
                itemmarket: marketRows.length,
            },
            summary: summarize(shown, { cashOnHand: app.settings.cashOnHand }),
            diagnostics:
                app.pageDiagnostics && app.pageType === tab
                    ? {
                          ...app.pageDiagnostics,
                          shopLoadError: app.shopLoadError || null,
                      }
                    : null,
            pageType: app.pageType,
            lastScanAt: app.lastScanAt,
            live: app.feed ? app.feed.status() : null,
        });

        if (app.ownBazaar) renderMyBazaar();
    }

    /**
     * Which list to show: the one matching the page you are on, unless you
     * clicked the other tab since arriving. Elsewhere, the last one you chose.
     */
    function activeTab() {
        if (app.tabOverride) return app.tabOverride;
        if (app.pageType === PAGE_BAZAAR) return 'bazaar';
        if (app.pageType === 'itemmarket') return 'itemmarket';
        return app.settings.viewTab === 'itemmarket' ? 'itemmarket' : 'bazaar';
    }

    function onViewChange(tab) {
        app.tabOverride = tab;
        app.settings = { ...app.settings, viewTab: tab };
        gmSet(STORE_SETTINGS, app.settings);
        refreshView();
    }

    /** The refresh button: loads reference data once, then scans the page. */
    async function onScan() {
        if (app.loading) return;

        if (!getStoredKey()) {
            app.panel.setStatus('No API key yet. Paste a Public key.', 'error');
            app.panel.openSettings({ focusKey: !getStoredKey() });
            return;
        }

        if (app.keyDead) {
            app.panel.setStatus('Torn rejected the saved key. Paste a new Public key.', 'error');
            return;
        }

        app.loading = true;
        app.panel.setBusy(true);

        try {
            const firstLoad = !app.index;
            if (firstLoad) await loadReferenceData();
            await checkKeyAccess();

            /*
             * Scan is a full refresh: drop everything the feed holds and rebuild
             * it from fresh data now, then re-read this page. Nothing old
             * survives a Scan.
             */
            clearMarks();
            if (app.feed) {
                app.feed.requestRefresh();
                app.feed.tick().catch(() => {});
            }
            rescan();

            // Replace "Downloading" - it is done. A key warning set by
            // checkKeyAccess is left in place.
            if (firstLoad && !app.panel.state.status.level.match(/warn|error/)) {
                app.panel.setStatus('Ready.');
            }
            if (app.pageType === PAGE_NONE) {
                app.panel.setStatus(
                    app.settings.liveFeed
                        ? 'Not a Bazaar or Item Market page. Showing what is watched.'
                        : 'Not a Bazaar or Item Market page.',
                );
            }
        } catch (error) {
            if (isKeyDeadError(error)) {
                markKeyDead(error);
            } else {
                // A network or Torn outage: retry, but not every 2.5s.
                app.retryLoadAt = Date.now() + 60000;
                app.panel.setStatus(
                    redactKey((error && error.message) || String(error), getStoredKey()),
                    'error',
                );
            }
        } finally {
            app.loading = false;
            app.panel.setBusy(false);
        }
    }

    /* ------------------------------------------------------------------ *
     * Bazaar owner: online status and open/closed
     * ------------------------------------------------------------------ */

    function isSellerClosed(sellerId, now = Date.now()) {
        if (!sellerId) return false;
        const until = app.closedSellers.get(String(sellerId));
        if (!until) return false;
        if (until > now) return true;
        app.closedSellers.delete(String(sellerId));
        return false;
    }

    /**
     * Runs with every scan: reads open/closed from the page banner (free),
     * refreshes the owner's public status when it is due, and paints both.
     */
    function updateOwner(now) {
        const ownerId =
            app.pageType === PAGE_BAZAAR ? bazaarOwnerId(location.href) : null;

        if (!ownerId) {
            if (app.owner) {
                app.owner = null;
                removeOwnerBadges(document);
                if (app.panel) app.panel.setSeller(null);
            }
            return;
        }

        if (!app.owner || app.owner.id !== ownerId) {
            removeOwnerBadges(document);
            app.owner = {
                id: ownerId,
                presence: null,
                fetchedAt: 0,
                pending: false,
                retryAt: 0,
                open: null,
            };
        }

        const owner = app.owner;
        const open = readBazaarOpen(document, ownerId);
        if (open !== null) owner.open = open;
        if (owner.open === false) app.closedSellers.set(ownerId, now + CLOSED_MEMORY_MS);
        if (owner.open === true) app.closedSellers.delete(ownerId);

        paintOwner(now);

        const due =
            !owner.pending &&
            now >= owner.retryAt &&
            now - owner.fetchedAt >= OWNER_REFRESH_MS;
        if (!due || !app.client || !hasUsableKey()) return;
        if (document.visibilityState !== 'visible') return;

        owner.pending = true;
        fetchUserPresence(app.client, ownerId)
            .then((presence) => {
                owner.fetchedAt = Date.now();
                if (presence) owner.presence = presence;
                else owner.retryAt = Date.now() + OWNER_RETRY_MS;
            })
            .catch((error) => {
                if (isKeyDeadError(error)) markKeyDead(error);
                owner.retryAt = Date.now() + OWNER_RETRY_MS;
            })
            .finally(() => {
                owner.pending = false;
                if (app.owner === owner) paintOwner(Date.now());
            });
    }

    function paintOwner(now) {
        const owner = app.owner;
        if (!owner) return;

        if (owner.presence) renderOwnerBadge(document, owner.id, owner.presence, now);

        if (!app.panel) return;
        const words = owner.presence
            ? presenceText(owner.presence, now)
            : { level: 'unknown', text: owner.pending || !owner.fetchedAt ? 'checking' : 'unknown' };

        app.panel.setSeller({
            name: (owner.presence && owner.presence.name) || null,
            level: words.level,
            text: words.text,
            closed: owner.open === false,
        });
    }

    /* ------------------------------------------------------------------ *
     * Online status: bazaar sellers on the list
     * ------------------------------------------------------------------ */

    /** The first SELLER_STATUS_MAX distinct sellers on the list, in list order. */
    function listedSellers(rows) {
        const ids = [];
        for (const r of rows) {
            if (r.source !== SOURCE_BAZAAR || !r.sellerId) continue;
            const id = String(r.sellerId);
            if (!ids.includes(id)) ids.push(id);
            if (ids.length >= SELLER_STATUS_MAX) break;
        }
        return ids;
    }

    /** A player's last known public status: the viewed bazaar's owner, or the lookups. */
    function presenceOf(id) {
        const key = String(id);
        if (app.owner && app.owner.id === key && app.owner.presence) return app.owner.presence;
        const entry = app.presence.get(key);
        return (entry && entry.presence) || null;
    }

    /**
     * Look up the public status of listed players, when due. The viewed
     * bazaar's owner is skipped: updateOwner() already has it.
     */
    function updatePresence(ids, now) {
        for (const [id, s] of app.presence) {
            if (!s.pending && now - s.listedAt > PRESENCE_FORGET_MS) app.presence.delete(id);
        }

        for (const id of ids) {
            if (!app.presence.has(id)) {
                app.presence.set(id, { presence: null, fetchedAt: 0, pending: false, retryAt: 0, listedAt: now });
            }
            app.presence.get(id).listedAt = now;
        }

        if (!app.client || !hasUsableKey()) return;
        if (document.visibilityState !== 'visible') return;
        if (app.panel.collapsed) return;

        let pending = 0;
        for (const s of app.presence.values()) if (s.pending) pending++;

        const ownerId = app.owner && app.owner.id;
        for (const id of ids) {
            if (pending >= PRESENCE_MAX_PENDING) break;
            if (id === ownerId) continue;

            const s = app.presence.get(id);
            if (s.pending || now < s.retryAt || now - s.fetchedAt < PRESENCE_REFRESH_MS) continue;

            pending++;
            s.pending = true;
            fetchUserPresence(app.client, id)
                .then((presence) => {
                    s.fetchedAt = Date.now();
                    if (presence) s.presence = presence;
                    else s.retryAt = Date.now() + PRESENCE_RETRY_MS;
                })
                .catch((error) => {
                    if (isKeyDeadError(error)) markKeyDead(error);
                    s.retryAt = Date.now() + PRESENCE_RETRY_MS;
                })
                .finally(() => {
                    s.pending = false;
                    refreshView();
                });
        }
    }

    /** playerId -> { name, level, text, title } for everyone whose status is known. */
    function statusMap(now) {
        const out = new Map();
        for (const id of app.presence.keys()) {
            const presence = presenceOf(id);
            if (presence) out.set(id, { name: presence.name, ...presenceWord(presence, now) });
        }
        if (app.owner && app.owner.presence) {
            out.set(app.owner.id, { name: app.owner.presence.name, ...presenceWord(app.owner.presence, now) });
        }
        return out;
    }

    /* ------------------------------------------------------------------ *
     * Your own bazaar: the pricing helper
     * ------------------------------------------------------------------ */

    /** Read the rows, tag each with its current asking prices, queue what is missing. */
    function scanOwnBazaarPage(which) {
        const { rows, diagnostics } = scanOwnBazaar(which, document, app.index);
        app.bzRows = rows;
        app.bzDiagnostics = { ...diagnostics, tags: 0 };

        const now = Date.now();
        const hist = loadHistory();
        let changed = false;

        for (const row of rows) {
            touchItem(hist, row.itemId, now);
            changed = true;
            const item = app.index.byId.get(row.itemId);
            if (item && item.marketValue > 0) recordMarketValue(hist, row.itemId, now, item.marketValue);

            const tag = ensureRowTag(row, document);
            app.bzDiagnostics.tags += 1;
            paintRowTag(tag, row.itemId);
            if (!tag.dataset.bound) {
                tag.dataset.bound = '1';
                tag.title = 'Show averages and graph';
                tag.addEventListener('click', (event) => {
                    event.preventDefault();
                    event.stopPropagation();
                    // The row's item NOW: #/manage reuses row elements as you scroll.
                    app.bzSelected = tag.dataset.itemId || row.itemId;
                    if (app.panel.collapsed) app.panel.setCollapsed(false, { save: true });
                    if (app.panel.page !== 'mybazaar') app.panel.showPage('mybazaar');
                    repaintOwnBazaar();
                });
            }
        }
        if (changed) markHistoryDirty();

        if (!app.bzSelected && rows.length) app.bzSelected = rows[0].itemId;

        attachObserver(rows);
        fetchOwnBazaarPrices();
    }

    /** The current prices for one item, from the caches: { im, bz }. */
    function bzPriceOf(itemId) {
        const now = Date.now();
        const rec = app.bzPrices.get(itemId) || {};

        // Bazaars: the stored TornW3B summary first (one call covers every item).
        const summary = gmGet(STORE_W3B_SUMMARY, null);
        let bz = rec.bz || null;
        if (summary && summary.lowest && now - summary.fetchedAt < BZ_SUMMARY_MAX_AGE_MS) {
            // Absent from a fresh summary = no bazaar lists it: price null, known.
            const p = Number(summary.lowest[itemId]) || null;
            if (!bz || summary.fetchedAt >= bz.at) bz = { price: p, at: summary.fetchedAt };
        }

        return { im: rec.im || null, bz };
    }

    /** "$30" when known, "none" when the source lists nothing, "…" until asked. */
    function bzPriceWord(entry) {
        if (!entry) return '…';
        return entry.price > 0 ? formatMoney(entry.price) : 'none';
    }

    /**
     * Only touched when its words or its selected state change: the tags sit
     * inside the observed rows, so every paint would otherwise be a mutation,
     * and every mutation a rescan, and every rescan a paint.
     */
    function paintRowTag(tag, itemId) {
        const { im, bz } = bzPriceOf(itemId);
        const words = 'IM ' + bzPriceWord(im) + ' · Bazaar ' + bzPriceWord(bz);
        if (tag.dataset.words !== words) {
            tag.dataset.words = words;
            tag.textContent = '';
            tag.appendChild(document.createTextNode('IM '));
            tag.appendChild(Object.assign(document.createElement('b'), { textContent: bzPriceWord(im) }));
            tag.appendChild(document.createTextNode(' · Bazaar '));
            tag.appendChild(Object.assign(document.createElement('b'), { textContent: bzPriceWord(bz) }));
        }
        const selected = String(itemId === app.bzSelected);
        if (tag.dataset.selected !== selected) tag.dataset.selected = selected;
    }

    /**
     * Fetch the lowest Item Market ask for the items on screen, one at a time,
     * never faster than BZ_FETCH_GAP_MS, only while this tab is visible. A
     * bazaar price is asked of TornW3B per item only when the shared summary is
     * missing or old. Nothing loops: an item is asked again only after its TTL.
     */
    function fetchOwnBazaarPrices() {
        if (!app.ownBazaar || !app.client || !hasUsableKey()) return;
        if (document.visibilityState !== 'visible') return;

        const now = Date.now();
        if (now - app.bzLastFetchAt < BZ_FETCH_GAP_MS) return;

        const summary = gmGet(STORE_W3B_SUMMARY, null);
        const summaryFresh = Boolean(summary && summary.lowest && now - summary.fetchedAt < BZ_SUMMARY_MAX_AGE_MS);

        // A fresh feed snapshot answers without a request.
        const feed = readFeedCacheEntry(gmGet(FEED_STORE_KEY, null), now);

        for (const row of app.bzRows) {
            const id = row.itemId;
            const rec = app.bzPrices.get(id) || { im: null, bz: null, imAt: 0, bzAt: 0, pending: false };
            app.bzPrices.set(id, rec);
            if (rec.pending) continue;

            const snap = feed.itemmarket.get(id);
            if (snap && snap.rows.length && snap.dataAt > (rec.imAt || 0)) {
                rec.im = { price: snap.rows[0].price, at: snap.dataAt };
                rec.imAt = snap.fetchedAt;
                recordSample(loadHistory(), id, snap.dataAt, { im: snap.rows[0].price });
                markHistoryDirty();
            }

            if (now - (rec.imAt || 0) >= BZ_IM_TTL_MS) {
                rec.pending = true;
                app.bzLastFetchAt = now;
                fetchItemMarket(app.client, id, { now })
                    .then((market) => {
                        const at = Date.now();
                        rec.imAt = at;
                        if (market.listings.length) {
                            const lowest = Math.min(...market.listings.map((l) => l.price));
                            rec.im = { price: lowest, at: market.cacheTimestamp || at };
                            recordSample(loadHistory(), id, at, { im: lowest });
                            markHistoryDirty();
                        } else {
                            rec.im = { price: null, at };
                        }
                    })
                    .catch((error) => {
                        if (isKeyDeadError(error)) markKeyDead(error);
                        rec.imAt = Date.now();
                    })
                    .finally(() => {
                        rec.pending = false;
                        repaintOwnBazaar();
                    });
                return;
            }

            if (!summaryFresh && app.w3b && app.settings.useW3b && now - (rec.bzAt || 0) >= BZ_W3B_TTL_MS) {
                rec.pending = true;
                app.bzLastFetchAt = now;
                fetchW3bListings(app.w3b, id)
                    .then(({ listings }) => {
                        const at = Date.now();
                        rec.bzAt = at;
                        const prices = listings.map((l) => Number(l && l.price)).filter((p) => p > 1);
                        if (prices.length) {
                            const lowest = Math.min(...prices);
                            rec.bz = { price: lowest, at };
                            recordSample(loadHistory(), id, at, { bz: lowest });
                            markHistoryDirty();
                        } else {
                            rec.bz = { price: null, at };
                        }
                    })
                    .catch(() => {
                        rec.bzAt = Date.now();
                    })
                    .finally(() => {
                        rec.pending = false;
                        repaintOwnBazaar();
                    });
                return;
            }
        }
    }

    function repaintOwnBazaar() {
        if (!app.ownBazaar) return;
        for (const row of app.bzRows) {
            if (!document.contains(row.el)) continue;
            paintRowTag(ensureRowTag(row, document), row.itemId);
        }
        renderMyBazaar();
    }

    function renderMyBazaar() {
        if (!app.ownBazaar) return;
        const now = Date.now();
        const hist = loadHistory();
        const items = app.bzRows.map((r) => ({ itemId: r.itemId, name: r.name, ...bzPriceOf(r.itemId) }));
        const selected = items.some((i) => i.itemId === app.bzSelected) ? app.bzSelected : items.length ? items[0].itemId : null;
        app.bzSelected = selected;
        const item = selected ? app.index.byId.get(selected) : null;

        app.panel.renderMyBazaar({
            items,
            selected,
            marketValue: item ? Number(item.marketValue) || null : null,
            averages: selected ? averages(hist, selected, now) : null,
            series: selected ? series(hist, selected, now, app.bzWindow) : null,
            windowKey: app.bzWindow,
            diagnostics: app.bzDiagnostics,
        });
    }

    /* ------------------------------------------------------------------ *
     * Price history: recorded by this script, from now on
     * ------------------------------------------------------------------ */

    function loadHistory() {
        if (!app.history) app.history = readHistory(gmGet(STORE_HISTORY, null));
        return app.history;
    }

    function markHistoryDirty() {
        app.historyDirty = true;
        saveHistoryIfDue();
    }

    /**
     * Every tab holds its own copy, so storage is re-read and merged before a
     * save: the selling tab's inventory items and a bazaar tab's samples both
     * survive whichever saves last.
     */
    function saveHistoryIfDue(force = false) {
        if (!app.history || !app.historyDirty) return;
        const now = Date.now();
        if (!force && now - app.historySavedAt < HISTORY_SAVE_MS) return;
        app.history = mergeHistory(gmGet(STORE_HISTORY, null), app.history);
        pruneHistory(app.history, now);
        gmSet(STORE_HISTORY, app.history);
        app.historySavedAt = now;
        app.historyDirty = false;
    }

    /**
     * Every TornW3B summary (the feed fetches one every 30s in the leading tab):
     * keep the lowest bazaar price of every item for the helper, and every 5
     * minutes record a sample for each tracked item - its bazaar ask from the
     * summary, its Item Market ask from the feed's snapshot when that is recent.
     */
    function onW3bSummary(summary, at) {
        const lowest = {};
        for (const s of summary || []) if (s.lowestPrice > 0) lowest[s.itemId] = s.lowestPrice;
        gmSet(STORE_W3B_SUMMARY, { fetchedAt: at, lowest });

        if (at - app.historySampledAt < HISTORY_SAMPLE_MS) return;
        app.historySampledAt = at;

        const hist = loadHistory();
        const ids = Object.keys(hist.items);
        if (!ids.length) return;

        const feed = readFeedCacheEntry(gmGet(FEED_STORE_KEY, null), at);
        for (const id of ids) {
            const sample = {};
            if (lowest[id] > 0) sample.bz = lowest[id];
            const snap = feed.itemmarket.get(id);
            if (snap && snap.rows.length && at - snap.dataAt < HISTORY_SAMPLE_MS) sample.im = snap.rows[0].price;
            if (sample.bz || sample.im) recordSample(hist, id, at, sample);
            const item = app.index && app.index.byId.get(id);
            if (item && item.marketValue > 0) recordMarketValue(hist, id, at, item.marketValue);
        }
        app.historyDirty = true;
        saveHistoryIfDue();
    }

    /* ------------------------------------------------------------------ *
     * Navigation
     * ------------------------------------------------------------------ */

    /**
     * The Scan button: re-read this page now. No requests - just the DOM
     * already on screen - so it can be pressed freely. Always animates, so a
     * press visibly did something even when the list does not change.
     */
    function onScanPage() {
        // Nothing loaded yet: the first load IS the scan.
        if (!app.index) return onScan();

        rescan();
        app.panel.showScan(scanSummary());
        return undefined;
    }

    function scanSummary() {
        if (app.ownBazaar) {
            const d = app.bzDiagnostics || { rows: 0, identified: 0 };
            return 'Your bazaar: ' + d.identified + ' of ' + d.rows + ' rows priced.';
        }
        if (app.pageType === PAGE_NONE) {
            return 'Not a Bazaar or Item Market page.';
        }

        const found = (app.pageDiagnostics && app.pageDiagnostics.listings) || 0;
        const lockedOnly = (app.pageDiagnostics && app.pageDiagnostics.locked) || 0;
        if (!found && lockedOnly) {
            return 'Scanned: ' + lockedOnly + ' locked $1 listing' + (lockedOnly === 1 ? '' : 's') + ', none for you.';
        }
        if (!found) {
            return 'Scanned: no listings on this page yet.';
        }

        const deals = (app.pageRows || []).length;
        const locked = (app.pageDiagnostics && app.pageDiagnostics.locked) || 0;
        return (
            'Scanned: ' +
            found +
            (found === 1 ? ' listing' : ' listings') +
            ' · ' +
            deals +
            (deals === 1 ? ' deal' : ' deals') +
            (locked ? ' · ' + locked + ' locked' : '')
        );
    }

    /**
     * A new page: scan now, then again while its listings finish drawing. The
     * first scan that finds listings plays the scan animation, so you can see
     * the new page was picked up.
     */
    function scanBurst() {
        const href = location.href;
        app.burstHref = href;

        for (const delay of SCAN_BURST_MS) {
            setTimeout(() => {
                if (app.burstHref !== href || location.href !== href) return;
                if (!app.index || document.visibilityState !== 'visible') return;
                if (app.announcedHref === href) return;

                rescan();

                if (app.pageType === PAGE_NONE) return;
                if (app.pageDiagnostics && app.pageDiagnostics.listings > 0) {
                    app.announcedHref = href;
                    app.panel.showScan();
                }
            }, delay);
        }
    }

    function startPageWatch() {
        app.watchedHref = location.href;
        scanBurst();

        setInterval(() => {
            if (location.href === app.watchedHref) return;
            app.watchedHref = location.href;
            handleRouteChange();
            scanBurst();
        }, HREF_WATCH_MS);
    }

    /** Identity of a feed listing you followed, so it is re-checked first. */
    function openedKey(row) {
        return [row.source, row.itemId, row.sellerId || '', row.profit.listingPrice].join(':');
    }

    function onNavigate(row, { newTab } = {}) {
        // One click, one navigation. Nothing is ever bought by the script.
        if (row.el && document.contains(row.el)) {
            revealRow(row.el);
            return;
        }

        if (row.fromFeed) {
            /*
             * Remember it was followed, and ask the feed to re-verify the item
             * first: a listing someone just went to buy is the one most likely
             * to be gone. If it is, the next refresh removes it.
             */
            const opened = gmGet(STORE_OPENED, {}) || {};
            opened[openedKey(row)] = row.dataAt;
            const keys = Object.keys(opened);
            if (keys.length > 200) delete opened[keys[0]];
            gmSet(STORE_OPENED, opened);

            if (app.feed) app.feed.requestRecheck([row.itemId]);
        }

        if (row.url) {
            openDeal(row.url, newTab);
            return;
        }

        // A bazaar sighting goes back to that bazaar, not to the Item Market.
        if (row.source === SOURCE_BAZAAR && row.sellerId) {
            openDeal(bazaarUrl(row.sellerId, row.itemId, row.profit.listingPrice), newTab);
            return;
        }

        openDeal(itemMarketUrl(row.itemId, row.name), newTab);
    }

    /** A new tab, or this one, per Settings -> "Open deals in a new tab". */
    function openDeal(url, newTab = app.settings.openInNewTab !== false) {
        if (newTab) {
            gmOpenTab(url);
            return;
        }
        location.assign(url);
    }

    function onSettingsChange(partial) {
        app.settings = { ...app.settings, ...partial };
        gmSet(STORE_SETTINGS, app.settings);

        // A change made in one place (a chip, an empty-state button) shows in
        // every control for it.
        app.panel.applySettings(partial);

        // Position and collapse are chrome: nothing to re-price.
        if (Object.keys(partial).every((k) => k === 'panelPos' || k === 'collapsed')) return;

        if (app.index) rescan();
        else refreshView();
    }

    /* ------------------------------------------------------------------ *
     * Live page
     * ------------------------------------------------------------------ */

    function debounce(fn, ms) {
        let timer = null;
        return () => {
            if (timer) clearTimeout(timer);
            timer = setTimeout(fn, ms);
        };
    }

    const debouncedRescan = debounce(() => rescan(), RESCAN_DEBOUNCE_MS);

    /**
     * Ignore anything the panel does to itself.
     *
     * Without this the script can chase its own tail: a rescan re-renders the
     * panel, the panel is a DOM mutation, the mutation triggers a rescan. The
     * observer is normally scoped to the row container so the panel is out of
     * range anyway, but this keeps that a safety property rather than a
     * coincidence of where the target happens to point.
     */
    function onMutations(mutations) {
        const panelRoot = app.panel && app.panel.root;

        const fromPage = mutations.some(
            (m) => (!panelRoot || !panelRoot.contains(m.target)) && !isOwnTagMutation(m),
        );

        if (fromPage) debouncedRescan();
    }

    /** A change to, or inside, one of the helper's own price tags is not the page changing. */
    function isOwnTagMutation(m) {
        const isTag = (n) =>
            n && n.nodeType === 1 && n.classList && n.classList.contains(OWN_BAZAAR_TAG_CLASS);
        const inTag = (n) => {
            const el = n && n.nodeType === 1 ? n : n && n.parentElement;
            return Boolean(el && el.closest && el.closest('.' + OWN_BAZAAR_TAG_CLASS));
        };
        if (inTag(m.target)) return true;
        const nodes = [...(m.addedNodes || []), ...(m.removedNodes || [])];
        return nodes.length > 0 && nodes.every((n) => isTag(n) || inTag(n));
    }

    /**
     * Item Market 2.0 re-renders rows as you sort and page. Without this the
     * markers vanish and the panel quietly goes stale - V1 had no observer at all.
     *
     * Only childList/subtree is observed, never attributes, so our own class
     * toggles cannot retrigger it. The target is always the row container: with
     * no rows there is nothing to watch, and watching document.body instead would
     * put the panel inside the observed subtree.
     */
    function attachObserver(listings) {
        const anchor = listings.find((l) => l.el && l.el.parentElement);
        if (!anchor) return;

        const target = anchor.el.parentElement;

        if (app.observer) {
            if (app.observerTarget === target) return;
            app.observer.disconnect();
        }

        app.observerTarget = target;
        app.observer = new MutationObserver(onMutations);
        app.observer.observe(target, { childList: true, subtree: true });
    }

    function applyPageType(next, { initial = false } = {}) {
        if (next !== app.pageType) app.tabOverride = null;
        app.pageType = next;

        if (!initial) clearMarks();

        /*
         * Reference data is needed on EVERY page now, not just the markets: the
         * live feed prices listings against it. It is a cached, one-time load.
         */
        if (app.index) {
            rescan();
            return;
        }

        if (hasUsableKey()) {
            onScan();
            return;
        }

        if (next === PAGE_NONE && !getStoredKey()) {
            app.panel.setStatus('Paste a Public API key under Settings to begin.');
        }
    }

    function handleRouteChange() {
        const next = detectPage(location.href);
        if (next === app.pageType && location.href === app.pageHref) return;

        applyPageType(next);
    }

    /* ------------------------------------------------------------------ *
     * Live feed
     * ------------------------------------------------------------------ */

    function startLiveFeed() {
        app.w3b = new W3bClient();

        app.feed = new LiveFeed({
            tabId: app.tabId,
            w3b: app.w3b,
            torn: app.client,
            getIndex: () => app.index,
            getSettings: () => app.settings,
            hasUsableKey,
            isVisible: () => document.visibilityState === 'visible',
            load: (key) => gmGet(key, null),
            save: (key, value) => gmSet(key, value),
            onChange: () => refreshView(),
            isKeyDead: isKeyDeadError,
            onKeyDead: markKeyDead,
            onSummary: onW3bSummary,
        });

        // Follower tabs re-render the moment the leader stores something new.
        const listening = gmOnChange(FEED_STORE_KEY, () => refreshView());

        const tick = () => {
            app.feed
                .tick()
                .catch(() => {})
                .finally(() => {
                    // Without a change listener, followers refresh on the tick.
                    if (!listening || app.feed.leading) refreshView();
                });
        };

        setInterval(tick, FEED_TICK_MS);

        /*
         * Coming back to this tab after following a link: the opened listings
         * are exactly the ones most likely to have changed. Re-verify them first.
         */
        document.addEventListener('visibilitychange', () => {
            if (document.visibilityState !== 'visible') {
                // Step down at once rather than waiting for the next tick.
                tick();
                saveHistoryIfDue(true);
                return;
            }

            const opened = gmGet(STORE_OPENED, {}) || {};
            const ids = Object.keys(opened)
                .map((k) => k.split(':')[1])
                .filter(Boolean);
            if (ids.length) app.feed.requestRecheck(ids.slice(-10));

            tick();
        });

        tick();
    }

    /* ------------------------------------------------------------------ *
     * Menu
     * ------------------------------------------------------------------ */

    function registerMenu() {
        gmMenu('Open settings', () => {
            app.panel.openSettings({ focusKey: !getStoredKey() });
        });

        gmMenu('Key safety / rotate key', () => {
            alert(
                'Key safety\n\n' +
                    '1. The panel needs PUBLIC access only.\n' +
                    '2. The selling page keeps a separate LIMITED key, used only\n' +
                    '   there to read your inventory.\n' +
                    '3. Both keys stay in this browser. They are sent only to\n' +
                    '   api.torn.com over HTTPS, never written to the console,\n' +
                    '   and never reach any third-party server.\n\n' +
                    'Opening your API key settings.',
            );
            gmOpenTab(TORN_API_KEY_URL);
        });

        // Maintenance lives here rather than in the panel's Settings.
        gmMenu('Re-download item data', onClearCache);

        gmMenu('Reset panel position', () => {
            onSettingsChange({ panelPos: null });
            app.panel.applyPosition(null);
        });

        gmMenu('Show scan diagnostics', () => {
            const d = app.pageDiagnostics;
            alert(
                d
                    ? 'Scan of the page you are on\n\n' +
                          [
                              'page: ' + (d.pageType || 'none'),
                              'item images found: ' + d.images,
                              'listing cards: ' + d.cards,
                              'read from Torn aria labels: ' + d.fromAria,
                              'parsed: ' + d.listings,
                              'skipped - item not in database: ' + d.noItem,
                              'skipped - no price: ' + d.noPrice,
                              'skipped - locked ($1, padlocked for you): ' + (d.locked || 0),
                              'price inferred: ' + d.priceAssumed,
                              'quantity assumed: ' + d.qtyAssumed,
                          ].join('\n')
                    : 'Open a Bazaar or the Item Market first.',
            );
        });

        gmMenu('Show my bazaar diagnostics', () => {
            const d = app.bzDiagnostics;
            const own = ownBazaarPage(location.href);
            alert(
                'Your own bazaar\n\n' +
                    [
                        'page detected: ' + (own || 'none (needs bazaar.php with #/add or #/manage, no userId)'),
                        'rows found: ' + (d ? d.rows : 0),
                        'rows with an item image: ' + (d ? d.withImage : 0),
                        'items identified: ' + (d ? d.identified : 0),
                        'rows skipped - item unknown: ' + (d ? d.noItem : 0),
                        'price tags placed: ' + (d ? d.tags : 0),
                        'items with a price history: ' + Object.keys(loadHistory().items).length,
                    ].join('\n'),
            );
        });
    }

    /* ------------------------------------------------------------------ *
     * The selling page (its own tab)
     * ------------------------------------------------------------------ */

    const sell = {
        client: null,
        te: null,
        page: null,
        index: null,
        inventory: null,
        inventoryAt: null,
        traders: null,
        idsByName: new Map(),
        lists: new Map(),
        listState: new Map(),
        /* The paced TornExchange queue: one call per slot, shared pace with every tab. */
        queue: null,
        expanded: new Set(),
        presence: new Map(),
        keyDead: false,
        keyError: null,
        error: null,
        loading: false,
        /* After a failed inventory read, the timer does not ask again before this. */
        inventoryRetryAt: 0,
    };

    /* The selling page asks for traders' statuses this often, visible tab only. */
    const SELL_PRESENCE_REFRESH_MS = 60000;
    const SELL_PRESENCE_MAX_PENDING = 3;
    /* A failed TornExchange call is not retried sooner than this. */
    const TE_RETRY_MS = 5 * 60 * 1000;
    /* Inventory is asked again after this, or on Refresh. */
    const INVENTORY_REFRESH_MS = 15 * 60 * 1000;

    function getSellKey() {
        return gmGet(STORE_SELL_KEY, '') || '';
    }

    function getTeKey() {
        return gmGet(STORE_TE_KEY, '') || '';
    }

    function sellPrefs() {
        const stored = gmGet(STORE_SELL_PREFS, {}) || {};
        const out = { ...SELLING_PAGE_DEFAULTS };
        for (const key of Object.keys(SELLING_PAGE_DEFAULTS)) {
            if (Object.prototype.hasOwnProperty.call(stored, key)) out[key] = stored[key];
        }
        return out;
    }

    function teState() {
        return gmGet(STORE_TE_STATE, {}) || {};
    }

    function setTeState(patch) {
        gmSet(STORE_TE_STATE, { ...teState(), ...patch });
    }

    function sellPresenceOf(id) {
        const entry = sell.presence.get(String(id));
        return (entry && entry.presence) || null;
    }

    function sellStatusMap(now) {
        const out = new Map();
        for (const [id, s] of sell.presence) {
            if (s.presence) out.set(id, { name: s.presence.name, ...presenceWord(s.presence, now) });
        }
        return out;
    }

    /** Everything the page shows, from what is loaded now. */
    function renderSelling() {
        if (!sell.page) return;
        const now = Date.now();
        const prefs = sellPrefs();
        const st = teState();
        const access = gmGet(STORE_SELL_KEY_ACCESS, null);

        const tradersFor = (itemId) => {
            const best = sell.traders ? sell.traders.map.get(String(itemId)) || [] : [];
            const full = sell.lists.get(String(itemId));
            return mergeTraders(best, full ? full.traders : null, sell.idsByName);
        };
        const sortBy = prefs.sortBy === SORT_BUNDLE ? SORT_BUNDLE : SORT_ITEM;
        const build = (onlineOnly) =>
            sell.inventory && sell.index
                ? buildSellingRows(sell.inventory, sell.index, { tradersFor, presenceOf: sellPresenceOf, onlineOnly, sortBy })
                : [];

        /*
         * Statuses are asked for from the rows with EVERY trader on them. With
         * Online only, rows drop the traders whose status is not known yet -
         * which, built from those, would be everyone, and nobody would ever be
         * asked about.
         */
        const allRows = build(false);
        const rows = prefs.onlineOnly ? build(true).filter((r) => r.best) : allRows;
        const watch = tradersToWatch(allRows, { expanded: sell.expanded });
        updateSellPresence(watch, now);

        // Online only, nobody shown yet, and statuses still on their way.
        const checkingOnline =
            Boolean(prefs.onlineOnly) &&
            watch.some((id) => {
                const s = sell.presence.get(String(id));
                return !s || (!s.presence && (s.pending || !s.fetchedAt) && now >= s.retryAt);
            });

        const itemLists = new Map();
        for (const [id, s] of sell.listState) itemLists.set(id, s);

        sell.page.render({
            rows,
            statuses: sellStatusMap(now),
            prefs: { ...prefs, sortBy },
            expanded: sell.expanded,
            info: {
                hasKey: Boolean(getSellKey()),
                keyAccess: access && access.name,
                keyError: sell.keyError,
                hasTeKey: Boolean(getTeKey()),
                teError: st.error || null,
                teBadKey: Boolean(st.badKey),
                teWaitUntil: st.blockedUntil > now ? st.blockedUntil : null,
                teAt: sell.traders ? sell.traders.fetchedAt : null,
                inventoryAt: sell.inventoryAt,
                loading: sell.loading,
                checkingOnline,
                error: sell.error,
                itemLists,
            },
        });
    }

    /** The item database, shared with the overlay's cache; fetched with this page's key if stale. */
    async function loadSellIndex() {
        const cached = gmGet(STORE_ITEMS, null);
        if (isItemsCacheFresh(cached)) {
            sell.index = buildItemIndex(cached.items);
            return;
        }
        const raw = await fetchItems(sell.client);
        gmSet(STORE_ITEMS, makeItemsCacheEntry(raw));
        sell.index = buildItemIndex(raw);
    }

    function sellKeyErrorText(error) {
        if (error && Number(error.code) === TORN_ERROR_ACCESS_LEVEL) {
            return 'This key cannot read your inventory. It needs Limited access.';
        }
        if (isKeyDeadError(error)) return 'Torn rejected this key. Paste a new Limited key.';
        return redactKey((error && error.message) || String(error), getSellKey());
    }

    async function loadSellInventory({ force = false } = {}) {
        if (!getSellKey() || sell.keyDead) return;

        const cached = readInventoryCacheEntry(gmGet(STORE_INVENTORY, null), Date.now(), INVENTORY_REFRESH_MS);
        if (cached && !force) {
            sell.inventory = cached.items;
            sell.inventoryAt = cached.fetchedAt;
            return;
        }

        sell.loading = true;
        renderSelling();
        try {
            if (!sell.index) await loadSellIndex();
            const raw = await fetchInventory(sell.client);
            const merged = mergeInventory(raw);
            gmSet(STORE_INVENTORY, makeInventoryCacheEntry(merged));
            sell.inventory = merged;
            sell.inventoryAt = Date.now();
            sell.keyError = null;

            const access = await fetchKeyAccess(sell.client);
            if (access && access.level !== null) gmSet(STORE_SELL_KEY_ACCESS, access);

            const hist = loadHistory();
            for (const it of merged) touchItem(hist, it.id, Date.now());
            markHistoryDirty();
            saveHistoryIfDue(true);
        } catch (error) {
            sell.keyError = sellKeyErrorText(error);
            // Not again for a while; a rejected key, not until a new one is saved.
            sell.inventoryRetryAt = Date.now() + INVENTORY_RETRY_MS;
            if (isKeyDeadError(error)) {
                sell.keyDead = true;
                gmSet(STORE_SELL_KEY_DEAD, true);
            }
        } finally {
            sell.loading = false;
            renderSelling();
        }
    }

    /** Re-read the stored trader prices (another tab may have fetched them). */
    function loadSellTraders(now = Date.now()) {
        const entry = gmGet(STORE_TE, null);
        const fetchedAt = entry && entry.fetchedAt;
        if (sell.traders && sell.traders.fetchedAt === fetchedAt) return;
        sell.traders = readTeCacheEntry(entry, now);

        const ids = gmGet(STORE_TE_IDS, null);
        if (ids && ids.map && now - ids.fetchedAt < TE_REFRESH_MS) {
            sell.idsByName = new Map(Object.entries(ids.map));
        }
        sell.lists = readTeItemLists(gmGet(STORE_TE_LISTS, null), now);
    }

    /**
     * One TornExchange call for the top buyers every TE_REFRESH_MS, from
     * whichever visible tab gets there first, plus one for the trader id list.
     * `lastAttemptAt` is stored BEFORE the call, so two tabs cannot both ask;
     * failures wait TE_RETRY_MS, and a 429 waits what TornExchange says. Both
     * calls go through the paced queue like every other.
     */
    async function refreshSellTraders({ force = false } = {}) {
        if (!getTeKey() || sell.teLoading) return;
        if (document.visibilityState !== 'visible') return;

        const now = Date.now();
        loadSellTraders(now);

        const st = teState();
        if (st.badKey) return;
        if (st.blockedUntil && now < st.blockedUntil) return;
        if (now - (st.lastAttemptAt || 0) < (force ? 30000 : TE_RETRY_MS)) return;
        if (!force && sell.traders && now - sell.traders.fetchedAt < TE_REFRESH_MS) return;

        setTeState({ lastAttemptAt: now });
        sell.teLoading = true;
        renderSelling();

        try {
            const map = await sell.queue.enqueue(() => fetchTeBestListings(sell.te));
            gmSet(STORE_TE, makeTeCacheEntry(map, Date.now()));
            setTeState({ error: null });
            sell.traders = null;
            loadSellTraders();
        } catch {
            // Recorded by the queue's onSettled.
        } finally {
            sell.teLoading = false;
            renderSelling();
        }

        // Trader ids by name, for buyers the top-three list does not carry.
        const ids = gmGet(STORE_TE_IDS, null);
        if (!teState().badKey && (!ids || Date.now() - ids.fetchedAt >= TE_REFRESH_MS)) {
            sell.queue
                .enqueue(() => fetchTeActiveTraders(sell.te))
                .then((map) => {
                    gmSet(STORE_TE_IDS, { fetchedAt: Date.now(), map: Object.fromEntries(map) });
                    sell.idsByName = map;
                    renderSelling();
                })
                .catch(() => {});
        }
    }

    /** A TornExchange call failed: a 429 wait or a bad key is kept for every tab. */
    function onTeSettled(error) {
        if (error && error.http === 429) {
            setTeState({ blockedUntil: Date.now() + error.retryAfterMs, error: error.message });
        } else if (error && error.badKey) {
            setTeState({ badKey: true, error: error.message });
        }
        renderSelling();
    }

    /**
     * The full buyer list for one item, when its row is opened: every page its
     * own slot in the queue. Not asked during a TornExchange wait, and a failed
     * list is not asked again before its retry time.
     */
    function loadTeItemList(itemId) {
        const id = String(itemId);
        if (sell.lists.has(id)) return;
        const now = Date.now();
        const st = sell.listState.get(id);
        if (st && (st.loading || now < (st.retryAt || 0))) return;
        if (!getTeKey() || teState().badKey) return;

        const blockedUntil = Number(teState().blockedUntil) || 0;
        if (now < blockedUntil) {
            sell.listState.set(id, { loading: false, error: 'TornExchange asked us to wait.', at: now, retryAt: blockedUntil });
            return;
        }

        sell.listState.set(id, { loading: true, error: null, at: now, retryAt: 0 });
        fetchTeListings(sell.te, id, { schedule: (fn) => sell.queue.enqueue(fn) })
            .then(({ traders }) => {
                gmSet(STORE_TE_LISTS, writeTeItemList(gmGet(STORE_TE_LISTS, null), id, traders));
                sell.lists.set(id, { at: Date.now(), traders });
                sell.listState.set(id, { loading: false, error: null, at: Date.now(), retryAt: 0 });
            })
            .catch((error) => {
                const at = Date.now();
                const retryAt = error && error.http === 429 ? at + (error.retryAfterMs || TE_RETRY_MS) : at + TE_RETRY_MS;
                sell.listState.set(id, { loading: false, error: (error && error.message) || 'TornExchange failed.', at, retryAt });
            })
            .finally(() => renderSelling());
    }

    /** Traders' public statuses, when due: visible tab only, inside the shared budget. */
    function updateSellPresence(ids, now) {
        for (const id of ids) {
            if (!sell.presence.has(id)) {
                sell.presence.set(id, { presence: null, fetchedAt: 0, pending: false, retryAt: 0 });
            }
        }
        if (!getSellKey() || sell.keyDead || document.visibilityState !== 'visible') return;

        let pending = 0;
        for (const s of sell.presence.values()) if (s.pending) pending++;

        for (const id of ids) {
            if (pending >= SELL_PRESENCE_MAX_PENDING) break;
            const s = sell.presence.get(id);
            if (s.pending || now < s.retryAt || now - s.fetchedAt < SELL_PRESENCE_REFRESH_MS) continue;

            pending++;
            s.pending = true;
            fetchUserPresence(sell.client, id)
                .then((presence) => {
                    s.fetchedAt = Date.now();
                    if (presence) s.presence = presence;
                    else s.retryAt = Date.now() + PRESENCE_RETRY_MS;
                })
                .catch((error) => {
                    if (isKeyDeadError(error)) {
                        sell.keyDead = true;
                        sell.keyError = sellKeyErrorText(error);
                        gmSet(STORE_SELL_KEY_DEAD, true);
                    }
                    s.retryAt = Date.now() + PRESENCE_RETRY_MS;
                })
                .finally(() => {
                    s.pending = false;
                    renderSelling();
                });
        }
    }

    function onSellSaveKey(key) {
        key = String(key || '').trim();
        if (!key) {
            sell.keyError = 'Paste a key first.';
            renderSelling();
            return;
        }
        if (key === getTeKey()) {
            sell.keyError = 'That is the TornExchange key. Paste your Torn key here.';
            renderSelling();
            return;
        }
        gmSet(STORE_SELL_KEY, key);
        gmDel(STORE_SELL_KEY_DEAD);
        gmDel(STORE_SELL_KEY_ACCESS);
        gmDel(STORE_INVENTORY);
        sell.keyDead = false;
        sell.keyError = null;
        sell.inventory = null;
        sell.inventoryAt = null;
        sell.inventoryRetryAt = 0;
        sell.page.showView('list');
        loadSellInventory({ force: true }).then(() => refreshSellTraders());
    }

    function onSellForgetKey() {
        gmDel(STORE_SELL_KEY);
        gmDel(STORE_SELL_KEY_DEAD);
        gmDel(STORE_SELL_KEY_ACCESS);
        gmDel(STORE_INVENTORY);
        sell.keyDead = false;
        sell.keyError = null;
        sell.inventory = null;
        sell.inventoryAt = null;
        renderSelling();
    }

    function onSellSaveTeKey(key) {
        key = String(key || '').trim();
        if (!key) {
            setTeState({ error: 'Paste a key first.' });
            renderSelling();
            return;
        }
        // The Torn key is never sent to a third party - not even this one.
        if (key === getSellKey() || key === getStoredKey()) {
            setTeState({ error: 'That is a Torn key. Paste the key from tornexchange.com.' });
            renderSelling();
            return;
        }
        gmSet(STORE_TE_KEY, key);
        gmDel(STORE_TE_STATE);
        sell.page.showView('list');
        refreshSellTraders({ force: true });
        renderSelling();
    }

    function onSellForgetTeKey() {
        gmDel(STORE_TE_KEY);
        gmDel(STORE_TE_STATE);
        gmDel(STORE_TE);
        gmDel(STORE_TE_LISTS);
        gmDel(STORE_TE_IDS);
        sell.traders = null;
        sell.lists = new Map();
        sell.idsByName = new Map();
        renderSelling();
    }

    function onSellRefresh() {
        for (const s of sell.presence.values()) s.fetchedAt = 0;
        loadSellInventory({ force: true }).then(() => refreshSellTraders({ force: true }));
    }

    function onSellExpand(itemId) {
        const id = String(itemId);
        if (sell.expanded.has(id)) sell.expanded.delete(id);
        else {
            sell.expanded.add(id);
            loadTeItemList(id);
        }
        renderSelling();
    }

    function openSellLink(url) {
        if (sellPrefs().linksNewTab !== false) gmOpenTab(url);
        else location.assign(url);
    }

    function bootSellingPage() {
        sell.client = new TornApiClient({
            getKey: getSellKey,
            loadWindow: () => gmGet(STORE_API_WINDOW, []),
            saveWindow: (recent) => gmSet(STORE_API_WINDOW, recent),
        });
        /*
         * The pace and any penalty wait live in storage, shared by every tab:
         * a reload or a second selling tab carries on from the same clock.
         */
        sell.te = new TeClient({
            getKey: getTeKey,
            loadState: () => teState(),
            saveState: (state) => setTeState(state),
        });
        sell.queue = new TeQueue({
            client: sell.te,
            isVisible: () => document.visibilityState === 'visible',
            onSettled: onTeSettled,
        });
        sell.keyDead = Boolean(gmGet(STORE_SELL_KEY_DEAD, false));
        if (sell.keyDead) sell.keyError = 'Torn rejected this key. Paste a new Limited key.';

        sell.page = new SellingPage({
            onSaveKey: onSellSaveKey,
            onForgetKey: onSellForgetKey,
            onRevealKey: () => getSellKey(),
            onSaveTeKey: onSellSaveTeKey,
            onForgetTeKey: onSellForgetTeKey,
            onRevealTeKey: () => getTeKey(),
            onRefresh: onSellRefresh,
            onPrefsChange: (partial) => {
                gmSet(STORE_SELL_PREFS, { ...sellPrefs(), ...partial });
                renderSelling();
            },
            onExpand: onSellExpand,
            onOpenProfile: (id) => openSellLink('https://www.torn.com/profiles.php?XID=' + encodeURIComponent(String(id))),
            onOpenList: (idOrName) => openSellLink(tePriceListUrl(idOrName)),
        });
        sell.page.mount();

        loadSellTraders();
        gmOnChange(STORE_TE, () => {
            loadSellTraders();
            renderSelling();
        });

        renderSelling();
        if (!getSellKey() || !getTeKey()) sell.page.openSettings();

        (async () => {
            try {
                if (getSellKey() && !sell.keyDead) await loadSellIndex();
            } catch (error) {
                sell.keyError = sellKeyErrorText(error);
                if (isKeyDeadError(error)) {
                    sell.keyDead = true;
                    gmSet(STORE_SELL_KEY_DEAD, true);
                }
            }
            await loadSellInventory();
            await refreshSellTraders();
            renderSelling();
        })();

        setInterval(() => {
            if (document.visibilityState !== 'visible') return;
            refreshSellTraders();
            const due = inventoryRefreshDue({
                inventoryAt: sell.inventoryAt,
                retryAt: sell.inventoryRetryAt,
                keyDead: sell.keyDead,
                refreshMs: INVENTORY_REFRESH_MS,
            });
            if (due && !sell.loading && getSellKey()) loadSellInventory({ force: true });
            renderSelling();
        }, 15000);

        document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'visible') renderSelling();
        });
    }

    /* ------------------------------------------------------------------ *
     * Boot
     * ------------------------------------------------------------------ */

    function boot() {
        // A tab opened for the selling page: this whole tab is the page.
        if (isTradersPageUrl(location.href)) {
            bootSellingPage();
            return;
        }

        injectStyles();

        app.settings = loadSettings();
        app.keyDead = Boolean(gmGet(STORE_KEY_DEAD, false));

        /*
         * One request budget for every open Torn tab. Torn counts 100/min per
         * user across all keys and tools; each tab keeping its own window let
         * two tabs spend 140/min.
         */
        app.client = new TornApiClient({
            getKey: getStoredKey,
            loadWindow: () => gmGet(STORE_API_WINDOW, []),
            saveWindow: (recent) => gmSet(STORE_API_WINDOW, recent),
        });

        app.panel = new Panel({
            onScan,
            onScanPage,
            onNavigate,
            onSettingsChange,
            onSaveKey,
            onForgetKey,
            onClearCache,
            onViewChange,
            /*
             * The key is put into the field only when the user asks to see it.
             * A value sitting in an <input> on torn.com is readable by every
             * script on the page, including other userscripts.
             */
            onRevealKey: () => getStoredKey(),
            onOpenSelling: () => gmOpenTab(tradersPageUrl()),
            onSelectBazaarItem: (itemId) => {
                app.bzSelected = String(itemId);
                repaintOwnBazaar();
            },
            onBazaarWindow: (key) => {
                app.bzWindow = key;
                renderMyBazaar();
            },
        });

        app.panel.mount();
        app.panel.enableHotkey();
        app.panel.applySettings(app.settings);

        refreshKeyState();
        registerMenu();

        applyPageType(detectPage(location.href), { initial: true });

        if (!getStoredKey()) {
            app.panel.setStatus('Paste a Public API key to begin.', 'warn');
            app.panel.openSettings({ focusKey: !getStoredKey() });
        } else if (app.keyDead) {
            app.panel.setStatus('Torn rejected the saved key. Paste a new Public key.', 'error');
        }

        window.addEventListener('hashchange', handleRouteChange);
        window.addEventListener('popstate', handleRouteChange);

        setInterval(() => {
            if (document.visibilityState !== 'visible') return;

            // Never loaded yet (no key at boot, or a failed first load). A key
            // Torn has rejected is never retried - see markKeyDead.
            if (!app.index) {
                if (hasUsableKey() && !app.loading && Date.now() >= app.retryLoadAt) {
                    onScan();
                }
                return;
            }

            refreshItemsIfStale();
            saveHistoryIfDue();

            if (detectPage(location.href) === PAGE_NONE) {
                if (app.pageType !== PAGE_NONE) rescan();
                return;
            }

            rescan();
        }, POLL_INTERVAL_MS);

        startPageWatch();
        startLiveFeed();
    }

    boot();
})();
